last_modified: 2026-01-27
title: "Serve a web framework"
description: "Create a package.json, install deps, run a web framework (Express), and expose it publicly from a sandbox"
url: /examples/sandbox_web_framework/
layout: sandbox-example.tsx
---

With Deno Sandbox you can create a `package.json`, install dependencies, run a
web framework (such as Express), and expose it publicly over HTTP.

This example shows how to create a minimal Express app inside the sandbox, run
it on port 3000, and expose it publicly using `sandbox.exposeHttp()`.

```ts
import { Sandbox } from "@deno/sandbox";

await using sandbox = await Sandbox.create();

// 1) Write package.json and server.js in the sandbox
const PACKAGE_JSON = {
  name: "sandbox-express-demo",
  private: true,
  type: "module",
  dependencies: { express: "^4.19.2" },
};
await sandbox.fs.writeTextFile(
  "package.json",
  JSON.stringify(PACKAGE_JSON, null, 2),
);

await sandbox.fs.writeTextFile(
  "server.js",
  `import express from 'express';
const app = express();
app.get('/', (req, res) => res.send('Hello from Express in @deno/sandbox!'));
app.get('/time', (req, res) => res.json({ now: new Date().toISOString() }));
app.listen(3000, () => console.log('listening on :3000'));
`,
);

// 2) Install dependencies
await sandbox.sh`deno install`;

// 3) Start the server
const server = await sandbox.deno.run({ entrypoint: "server.js" });

// 4) Publish to the internet
const publicUrl = await sandbox.exposeHttp({ port: 3000 });
console.log("Public URL:", publicUrl); // e.g. https://<random>.sandbox.deno.net

// Fetch from your local machine to verify
const resp = await fetch(`${publicUrl}/time`);
console.log(await resp.json());

// Keep the process alive as long as you need; when done, closing the sandbox
// will tear it down.
```

/**
 * @title Cancel async work with AbortController
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run -N <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/AbortController} MDN: AbortController
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/AbortSignal} MDN: AbortSignal
 * @group Web Standard APIs
 *
 * AbortController produces an AbortSignal that can cancel fetch requests,
 * remove event listeners, and stop any code that checks the signal. One
 * controller can cancel many operations at once. This example aborts a
 * slow fetch, fans one signal out to several listeners, combines signals
 * with AbortSignal.any, and aborts with a custom reason.
 */

// Start a local server that takes a full second to answer, so the abort
// below always fires first and the example is self-contained.
const server = Deno.serve({ port: 0, onListen() {} }, async () => {
  await new Promise((resolve) => setTimeout(resolve, 1000));
  return new Response("finally done");
});
const url = `http://localhost:${server.addr.port}/`;

// Pass the signal to fetch, then call abort on the controller. The fetch
// promise rejects with a DOMException whose name is AbortError.
const controller = new AbortController();
setTimeout(() => controller.abort(), 50);

try {
  await fetch(url, { signal: controller.signal });
} catch (err) {
  console.log((err as DOMException).name); // AbortError
}

// A signal is an EventTarget. Any number of listeners can subscribe to its
// abort event, so one controller can tear down several things together.
const teardown = new AbortController();
teardown.signal.addEventListener("abort", () => console.log("stop the upload")); // stop the upload
teardown.signal.addEventListener(
  "abort",
  () => console.log("hide the spinner"),
); // hide the spinner
teardown.abort();

// AbortSignal.any builds a signal that aborts as soon as any of its inputs
// abort. This is how you combine a user cancel with other conditions.
const userCancel = new AbortController();
const shutdown = new AbortController();
const combined = AbortSignal.any([userCancel.signal, shutdown.signal]);

userCancel.abort();
console.log(combined.aborted); // true
console.log(shutdown.signal.aborted); // false

// The abort method accepts a custom reason, which can be any value. The
// signal exposes it as signal.reason, and aborted fetches reject with it.
const custom = new AbortController();
custom.abort(new Error("user closed the dialog"));
console.log(custom.signal.aborted); // true
console.log((custom.signal.reason as Error).message); // user closed the dialog

// Without an explicit reason the signal gets a default DOMException.
const plain = new AbortController();
plain.abort();
console.log((plain.signal.reason as DOMException).name); // AbortError

// Stop the local server so the script can exit.
await server.shutdown();

/**
 * @title AES Encryption and Decryption
 * @difficulty intermediate
 * @tags cli, web
 * @run <url>
 * @group Cryptography
 *
 * This example demonstrates AES encryption and decryption using Deno's built-in SubtleCrypto API.
 */

// Define the text to be encrypted
const text = "Hello, Deno 2!";

// Convert the text to a Uint8Array using TextEncoder (required for encryption)
const encoder = new TextEncoder();
const data = encoder.encode(text);

// Generate an AES-GCM key for encryption and decryption
// We used AES-GCM in this example as it is a widely used encryption mode, but you can also use modes like AES-CBC or AES-CTR for different use cases.
const key = await crypto.subtle.generateKey(
  {
    name: "AES-GCM",
    length: 256, // 256-bit encryption key for strong security
  },
  true, // The key is extractable for encryption and decryption
  ["encrypt", "decrypt"], // Key usages: encryption and decryption
);

// Generate a random initialization vector (IV) for AES-GCM
// The IV must be unique for each encryption operation but doesn't need to be secret.
const iv = crypto.getRandomValues(new Uint8Array(12)); // 12-byte IV for AES-GCM

// Encrypt the text using AES-GCM
const encryptedData = await crypto.subtle.encrypt(
  {
    name: "AES-GCM",
    iv: iv, // Initialization vector must be unique for each encryption
  },
  key, // The generated key
  data, // The text data to encrypt
);

console.log("Encrypted Data:", new Uint8Array(encryptedData)); // Log the encrypted result as a byte array

// Decrypt the encrypted data back to plaintext using the same IV and key. The IV and Key used for decryption must the same as used for encryption
const decryptedData = await crypto.subtle.decrypt(
  {
    name: "AES-GCM",
    iv: iv, // Same IV used for encryption
  },
  key, // The same key used for encryption
  encryptedData, // The encrypted data to decrypt
);

// Convert the decrypted data back to a string using TextDecoder
const decryptedText = new TextDecoder().decode(decryptedData);
console.log("Decrypted Text:", decryptedText);

/**
 * @title Control the terminal with ANSI escape codes
 * @difficulty intermediate
 * @tags cli
 * @run <url>
 * @resource {https://jsr.io/@std/fmt/doc/colors/~} Doc: @std/fmt colors
 * @resource {https://docs.deno.com/api/deno/~/Deno.stdout} Doc: Deno.stdout
 * @group CLI
 *
 * Terminals interpret special byte sequences, called ANSI escape codes, as
 * commands: change the text color, erase a line, move or hide the cursor.
 * Writing them directly is all it takes to build colored output and
 * self-updating status lines without any dependencies.
 */

import { green } from "jsr:@std/fmt@^1.0.0/colors";
import { delay } from "jsr:@std/async@^1.0.0/delay";

// Escape sequences start with the escape byte, written \x1b, followed by [
// and a command. Writing raw bytes to stdout keeps full control over when
// a newline is emitted.
const encoder = new TextEncoder();
function write(text: string) {
  Deno.stdout.writeSync(encoder.encode(text));
}

// Colors and text styles are select graphic rendition commands. The
// sequence \x1b[31m switches to red and \x1b[0m resets all styling. Always
// reset, otherwise the style leaks into the next line of output.
console.log("\x1b[31mred\x1b[0m \x1b[1mbold\x1b[0m \x1b[4munderline\x1b[0m");

// For colors alone you rarely need raw codes. The standard library wraps
// them in plain functions that emit the same bytes:
console.log(green("green via @std/fmt/colors"));

// Now the classic trick behind installers and download counters: a single
// status line that rewrites itself. The sequence \x1b[2K erases the whole
// current line and \r returns the cursor to column zero, so the next write
// replaces the line instead of appending. \x1b[?25l hides the cursor while
// the line is being redrawn and \x1b[?25h shows it again. Restore it in a
// finally block, otherwise an early exception leaves the terminal without
// a cursor. Related codes move the cursor instead of erasing: \x1b[1A goes
// up one line and \x1b[1B goes down.
const steps = ["Resolving packages", "Downloading", "Linking", "Cleaning up"];

// Redrawing a line only works on an interactive terminal. When output is
// piped, print ordinary lines instead.
if (Deno.stdout.isTerminal()) {
  write("\x1b[?25l");
  try {
    for (let i = 0; i < steps.length; i++) {
      write(`\x1b[2K\r[${i + 1}/${steps.length}] ${steps[i]}...`);
      await delay(600);
    }
    write("\x1b[2K\rInstall complete.\n");
  } finally {
    write("\x1b[?25h");
  }
} else {
  for (const step of steps) {
    console.log(`${step}...`);
    await delay(100);
  }
  console.log("Install complete.");
}

// In a terminal the four steps flash by on one line, which then settles on
// the final text:
//
//   Install complete.

// When piped, the fallback prints each step on its own line:
//
//   deno run ansi_terminal.ts | cat
//   red bold underline
//   green via @std/fmt/colors
//   Resolving packages...
//   Downloading...
//   Linking...
//   Cleaning up...
//   Install complete.

/**
 * @title Connect to Claude (Anthropic API)
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -E <url>
 * @resource {https://www.npmjs.com/package/@anthropic-ai/sdk} @anthropic-ai/sdk on npm
 * @resource {https://docs.claude.com/en/api/overview} Claude API reference
 * @group AI
 *
 * The official Anthropic SDK runs in Deno straight from npm. This example
 * streams a chat response from Claude so tokens print as they arrive, which
 * keeps long replies responsive and avoids request timeouts. Set your key in
 * the ANTHROPIC_API_KEY environment variable before running.
 */

import Anthropic from "npm:@anthropic-ai/sdk";

// The client reads the API key from the ANTHROPIC_API_KEY environment variable
// by default, so there is nothing to pass to the constructor.
const client = new Anthropic();

// Open a streaming request. Streaming is the recommended default for anything
// that might produce a long reply: tokens arrive incrementally instead of in
// one large response at the end.
const stream = client.messages.stream({
  model: "claude-opus-4-8",
  max_tokens: 1024,
  messages: [
    { role: "user", content: "In one sentence, what makes Deno distinctive?" },
  ],
});

// The `text` event yields each text delta as the model produces it. Write the
// chunks straight to stdout so they render as a single, growing reply.
stream.on("text", (delta) => {
  Deno.stdout.writeSync(new TextEncoder().encode(delta));
});

// Wait for the stream to finish and read the complete message. The final
// message also carries token usage, which is useful for cost tracking.
const message = await stream.finalMessage();
console.log(`\n\nOutput tokens: ${message.usage.output_tokens}`);

/**
 * @title RAG: ground Claude's answer in your documents
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -E <url>
 * @resource {https://docs.voyageai.com/docs/embeddings} Voyage AI embeddings
 * @resource {https://www.npmjs.com/package/@anthropic-ai/sdk} @anthropic-ai/sdk on npm
 * @group AI
 *
 * Retrieval-augmented generation grounds an answer in your own data. Anthropic
 * has no embeddings endpoint, so this example embeds a small knowledge base
 * and the question with Voyage AI, finds the closest passages by cosine
 * similarity, and passes them to Claude as context. Set ANTHROPIC_API_KEY and
 * VOYAGE_API_KEY before running.
 */

import Anthropic from "npm:@anthropic-ai/sdk";

const anthropic = new Anthropic();

// A tiny knowledge base. In a real app these passages would live in a vector
// database rather than an array.
const documents = [
  "Deno is secure by default: network, file system, and environment access " +
  "must be granted explicitly with flags like --allow-net.",
  "Deno has a built-in test runner. Write Deno.test() and run `deno test`.",
  "Deno supports npm packages through the npm: specifier, for example " +
  "import express from 'npm:express'.",
];

// Embed text with Voyage AI's REST API. input_type marks whether the text is
// a stored document or a search query, which improves retrieval quality.
async function embed(
  input: string[],
  inputType: "document" | "query",
): Promise<number[][]> {
  const res = await fetch("https://api.voyageai.com/v1/embeddings", {
    method: "POST",
    headers: {
      authorization: `Bearer ${Deno.env.get("VOYAGE_API_KEY")}`,
      "content-type": "application/json",
    },
    body: JSON.stringify({
      model: "voyage-3.5-lite",
      input,
      input_type: inputType,
    }),
  });
  if (!res.ok) {
    throw new Error(`Voyage error ${res.status}: ${await res.text()}`);
  }
  const json = await res.json();
  return json.data.map((d: { embedding: number[] }) => d.embedding);
}

// Cosine similarity scores how close two embedding vectors are.
function cosine(a: number[], b: number[]): number {
  let dot = 0, normA = 0, normB = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }
  return dot / (Math.sqrt(normA) * Math.sqrt(normB));
}

const question = "How do I run tests in Deno?";

// Embed the documents once (this is the "index") and the incoming question.
const docVectors = await embed(documents, "document");
const [queryVector] = await embed([question], "query");

// Rank documents by similarity to the question and keep the top two.
const retrieved = documents
  .map((text, i) => ({ text, score: cosine(queryVector, docVectors[i]) }))
  .sort((a, b) => b.score - a.score)
  .slice(0, 2);

// Hand the retrieved passages to Claude as context and ask it to answer from
// them, which keeps the response grounded in your data.
const context = retrieved.map((d) => `- ${d.text}`).join("\n");
const message = await anthropic.messages.create({
  model: "claude-opus-4-8",
  max_tokens: 1024,
  messages: [
    {
      role: "user",
      content: `Answer the question using only the context below.\n\n` +
        `Context:\n${context}\n\nQuestion: ${question}`,
    },
  ],
});

for (const block of message.content) {
  if (block.type === "text") console.log(block.text);
}

/**
 * @title Stream a Claude response to the browser
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -E <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events} MDN: Server-sent events
 * @resource {https://www.npmjs.com/package/@anthropic-ai/sdk} @anthropic-ai/sdk on npm
 * @group AI
 *
 * A chat UI needs tokens to appear as the model produces them. This server
 * streams a Claude response to the browser over server-sent events: the
 * browser opens an EventSource, and each text delta from the Anthropic SDK is
 * forwarded as one SSE message. Open http://localhost:8000 after starting it,
 * with ANTHROPIC_API_KEY set.
 */

import Anthropic from "npm:@anthropic-ai/sdk";

const client = new Anthropic();

// A minimal page that opens an EventSource and appends each token as it
// arrives. Deltas are JSON-encoded on the server, so newlines survive.
const PAGE = `<!doctype html>
<meta charset="utf-8" />
<title>Streaming Claude</title>
<pre id="out"></pre>
<script>
  const out = document.getElementById("out");
  const source = new EventSource("/chat");
  source.onmessage = (e) => { out.textContent += JSON.parse(e.data); };
  source.addEventListener("done", () => source.close());
</script>`;

function handler(req: Request): Response {
  const url = new URL(req.url);

  // Serve the page itself at the root.
  if (url.pathname !== "/chat") {
    return new Response(PAGE, { headers: { "content-type": "text/html" } });
  }

  // The prompt can come from the query string; fall back to a default.
  const prompt = url.searchParams.get("q") ??
    "In two sentences, explain why streaming improves a chat UI.";

  const encoder = new TextEncoder();
  const body = new ReadableStream({
    async start(controller) {
      const stream = client.messages.stream({
        model: "claude-opus-4-8",
        max_tokens: 1024,
        messages: [{ role: "user", content: prompt }],
      });

      // Forward every text delta as one SSE message. JSON.stringify keeps
      // newlines from breaking the `data:` framing.
      stream.on("text", (delta) => {
        controller.enqueue(
          encoder.encode(`data: ${JSON.stringify(delta)}\n\n`),
        );
      });

      try {
        await stream.finalMessage();
        // A named event lets the browser close the connection cleanly.
        controller.enqueue(encoder.encode('event: done\ndata: ""\n\n'));
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        controller.enqueue(
          encoder.encode(`event: error\ndata: ${JSON.stringify(message)}\n\n`),
        );
      } finally {
        controller.close();
      }
    },
  });

  // The text/event-stream content type is what makes this SSE; no-store keeps
  // proxies from buffering the tokens.
  return new Response(body, {
    headers: {
      "content-type": "text/event-stream",
      "cache-control": "no-store",
    },
  });
}

Deno.serve(handler);

/**
 * @title Get structured JSON output from Claude
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -E <url>
 * @resource {https://platform.claude.com/docs/en/build-with-claude/structured-outputs} Claude structured outputs
 * @resource {https://www.npmjs.com/package/@anthropic-ai/sdk} @anthropic-ai/sdk on npm
 * @group AI
 *
 * When you need machine-readable output, constrain Claude's response to a
 * JSON schema with output_config.format. The model returns JSON matching the
 * schema, so you can parse it directly instead of coaxing structure out of
 * prose or writing fragile string parsing. Set ANTHROPIC_API_KEY first.
 */

import Anthropic from "npm:@anthropic-ai/sdk";

const client = new Anthropic();

// Describe the exact shape you want back. Structured outputs require every
// object to set additionalProperties: false.
const schema = {
  type: "object",
  properties: {
    name: { type: "string" },
    field: { type: "string" },
    languages: { type: "array", items: { type: "string" } },
  },
  required: ["name", "field", "languages"],
  additionalProperties: false,
};

const response = await client.messages.create({
  model: "claude-opus-4-8",
  max_tokens: 1024,
  // output_config.format constrains the whole response to the schema.
  output_config: { format: { type: "json_schema", schema } },
  messages: [
    {
      role: "user",
      content:
        "Ada Lovelace was an English mathematician, regarded as the first " +
        "computer programmer.",
    },
  ],
});

// The response text is JSON that matches the schema, ready to parse.
const block = response.content.find((b) => b.type === "text");
if (block?.type === "text") {
  const person = JSON.parse(block.text);
  console.log(person);
  // { name: "Ada Lovelace", field: "mathematics", languages: ["English"] }
}

/**
 * @title Build an agent with tool use
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -E <url>
 * @resource {https://platform.claude.com/docs/en/agents-and-tools/tool-use/overview} Claude tool use overview
 * @resource {https://www.npmjs.com/package/@anthropic-ai/sdk} @anthropic-ai/sdk on npm
 * @group AI
 *
 * Tool use lets Claude call functions you define and act on the results. You
 * describe each tool with a JSON schema, and when Claude decides to use one it
 * returns a tool_use request instead of a final answer. You run the tool, send
 * the result back, and repeat until Claude is done. This loop is the core of
 * an agent. Set ANTHROPIC_API_KEY before running.
 */

import Anthropic from "npm:@anthropic-ai/sdk";

const client = new Anthropic();

// Describe the tool with a JSON schema. A clear description and prescriptive
// "when to call it" wording help Claude decide to use it at the right time.
const tools: Anthropic.Tool[] = [
  {
    name: "get_weather",
    description:
      "Get the current weather for a city. Call this whenever the user asks " +
      "about weather conditions.",
    input_schema: {
      type: "object",
      properties: {
        city: { type: "string", description: "City name, e.g. Tokyo" },
      },
      required: ["city"],
    },
  },
];

// The actual implementation. In a real app this would call a weather API; here
// it returns canned data so the example runs without extra setup.
function getWeather(city: string): string {
  const data: Record<string, string> = {
    Tokyo: "18°C, clear",
    Paris: "12°C, light rain",
    Oslo: "4°C, snow",
  };
  return data[city] ?? `No data for ${city}`;
}

// The API is stateless, so we carry the full conversation in `messages`.
const messages: Anthropic.MessageParam[] = [
  { role: "user", content: "Compare the weather in Tokyo and Oslo right now." },
];

// Agent loop: keep calling the model until it stops requesting tools.
while (true) {
  const response = await client.messages.create({
    model: "claude-opus-4-8",
    max_tokens: 1024,
    tools,
    messages,
  });

  // No tool requested means Claude produced its final answer.
  if (response.stop_reason !== "tool_use") {
    for (const block of response.content) {
      if (block.type === "text") console.log(block.text);
    }
    break;
  }

  // Record the assistant turn; it holds the tool_use blocks we must answer.
  messages.push({ role: "assistant", content: response.content });

  // Run every requested tool and gather the results.
  const toolResults: Anthropic.ToolResultBlockParam[] = [];
  for (const block of response.content) {
    if (block.type === "tool_use" && block.name === "get_weather") {
      const { city } = block.input as { city: string };
      toolResults.push({
        type: "tool_result",
        tool_use_id: block.id,
        content: getWeather(city),
      });
    }
  }

  // Feed the results back so Claude can continue from where it left off.
  messages.push({ role: "user", content: toolResults });
}

