// can return one without any conversion.
const response = new Response(blob);
console.log(response.headers.get("content-type")); // text/plain

/**
 * @title Convert a Buffer (node:buffer)
 * @difficulty beginner
 * @tags cli, deploy
 * @run <url>
 * @resource {https://docs.deno.com/api/node/buffer/} Doc: node:buffer
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Uint8Array} MDN: Uint8Array
 * @group Encoding
 *
 * Node.js APIs and many npm packages produce Buffer objects. Deno supports
 * Buffer through the node:buffer module, and since Buffer is a subclass of
 * Uint8Array, converting to web-standard types is straightforward. This
 * example shows the common conversions in both directions.
 */
import { Buffer } from "node:buffer";

// We start with a Buffer containing the bytes of the string "Hello".
const buffer = Buffer.from("Hello", "utf8");

// To convert to a string, use the built-in toString method with an
// optional encoding.
console.log(buffer.toString("utf8")); // Hello

// A Buffer is a subclass of Uint8Array, so web APIs accept it directly.
// To get a plain Uint8Array view over the same memory, pass byteOffset and
// length. Buffers are often slices of a larger shared allocation.
const bytes = new Uint8Array(buffer.buffer, buffer.byteOffset, buffer.length);
console.log(bytes); // Uint8Array(5) [ 72, 101, 108, 108, 111 ]

// To get an exact ArrayBuffer, slice the range out of the underlying
// buffer. Taking the buffer property alone may include unrelated bytes
// from the shared allocation pool.
const arrayBuffer = buffer.buffer.slice(
  buffer.byteOffset,
  buffer.byteOffset + buffer.byteLength,
);
console.log(arrayBuffer.byteLength); // 5

// The Blob constructor accepts a Buffer like any other view.
const blob = new Blob([buffer]);
console.log(blob.size); // 5

// To convert to a ReadableStream, wrap it with ReadableStream.from.
const stream = ReadableStream.from([buffer]);
console.log(stream instanceof ReadableStream); // true

// For the reverse direction, TextDecoder accepts any ArrayBuffer view, so
// it decodes DataViews and Buffers directly.
const view = new DataView(arrayBuffer);
console.log(new TextDecoder().decode(view)); // Hello

/**
 * @title Convert a Node.js Readable
 * @difficulty beginner
 * @tags cli, deploy
 * @run <url>
 * @resource {https://docs.deno.com/api/node/stream/} Doc: node:stream
 * @resource {https://docs.deno.com/examples/convert_readablestream/} Example: Convert a ReadableStream
 * @group Encoding
 *
 * Node.js APIs and npm packages often return a Node.js Readable rather than
 * a web ReadableStream. The node:stream/consumers module collects one into
 * any common type directly. This example shows each conversion.
 */
import { Readable } from "node:stream";
import { blob, buffer, json, text } from "node:stream/consumers";

// A helper that produces a fresh Readable for each conversion below,
// because a stream can only be read once.
function readableOf(content: string): Readable {
  return Readable.from([content]);
}

// To collect into a string, use the text consumer.
console.log(await text(readableOf("Hello"))); // Hello

// To parse the stream contents as JSON, use the json consumer.
const data = await json(readableOf('{"name":"Deno"}')) as { name: string };
console.log(data.name); // Deno

// To collect into a Buffer, use the buffer consumer. Since a Buffer is a
// Uint8Array, this is also the route to bytes.
const bytes = await buffer(readableOf("Hello"));
console.log(bytes.length); // 5

// To collect into a Blob, use the blob consumer. An ArrayBuffer is then one
// call away.
const asBlob = await blob(readableOf("Hello"));
console.log(asBlob.size); // 5

// To get an array of the chunks, use the built-in toArray method.
const chunks = await readableOf("Hello").toArray();
console.log(chunks); // [ "Hello" ]

// To convert to a web ReadableStream, use the static toWeb method. Web
// streams carry bytes, so the Readable should contain Uint8Array chunks.
// The reverse direction is Readable.fromWeb.
const byteReadable = Readable.from([new TextEncoder().encode("Hello")]);
const webStream = Readable.toWeb(byteReadable);
console.log(await new Response(webStream as ReadableStream).text()); // Hello

/**
 * @title Convert a ReadableStream
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/ReadableStream} MDN: ReadableStream
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Response} MDN: Response
 * @group Encoding
 *
 * Network responses, file handles, and subprocess output all hand you a
 * ReadableStream. The easiest way to collect one into a string, bytes, or
 * JSON is to wrap it in a Response, which provides all the conversion
 * methods. This example shows each common conversion.
 */

// A helper that produces a fresh stream of UTF-8 bytes for each conversion
// below, because a stream can only be read once.
function streamOf(text: string): ReadableStream<Uint8Array> {
  return ReadableStream.from([new TextEncoder().encode(text)]);
}

// To collect into a string, wrap the stream in a Response and use the text
// method.
const text = await new Response(streamOf("Hello")).text();
console.log(text); // Hello

// To collect into a Uint8Array, use the bytes method.
const bytes = await new Response(streamOf("Hello")).bytes();
console.log(bytes); // Uint8Array(5) [ 72, 101, 108, 108, 111 ]

// To collect into an ArrayBuffer, use the arrayBuffer method.
const buffer = await new Response(streamOf("Hello")).arrayBuffer();
console.log(buffer.byteLength); // 5

// To parse the stream contents as JSON, use the json method.
const data = await new Response(streamOf('{"name":"Deno"}')).json();
console.log(data.name); // Deno

// To collect into a Blob, use the blob method.
const blob = await new Response(streamOf("Hello")).blob();
console.log(blob.size); // 5

// To get an array of the raw chunks instead of joining them, use
// Array.fromAsync. Each chunk arrives as it was written to the stream.
const chunks = await Array.fromAsync(streamOf("Hello"));
console.log(chunks.length); // 1

// Remember that a stream is consumed by reading it. To use the same stream
// in two places, split it with tee first.
const [first, second] = streamOf("Hello").tee();
console.log(await new Response(first).text()); // Hello
console.log(await new Response(second).text()); // Hello

/**
 * @title Convert a string to bytes and back
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/TextEncoder} MDN: TextEncoder
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/TextDecoder} MDN: TextDecoder
 * @group Encoding
 *
 * Hashing, file writes, and network protocols all want bytes, not strings.
 * This example shows how to encode a string into each common binary type
 * and decode it back.
 */

// We start with a plain string.
const text = "Hello";

// To convert to a Uint8Array of UTF-8 bytes, use TextEncoder.
const bytes = new TextEncoder().encode(text);
console.log(bytes); // Uint8Array(5) [ 72, 101, 108, 108, 111 ]

// To convert back, use TextDecoder.
console.log(new TextDecoder().decode(bytes)); // Hello

// To get an ArrayBuffer, encode first and take the underlying buffer.
const buffer = new TextEncoder().encode(text).buffer;
console.log(buffer.byteLength); // 5

// To convert to a Blob, pass the string directly. The Blob constructor
// encodes it as UTF-8 for you.
const blob = new Blob([text]);
console.log(blob.size); // 5

// To convert to a ReadableStream, the most direct route is through a Blob.
const stream = new Blob([text]).stream();
console.log(await new Response(stream).text()); // Hello

// To convert to a base64 string, encode to bytes and use the built-in
// toBase64 method.
const base64 = new TextEncoder().encode(text).toBase64();
console.log(base64); // SGVsbG8=

// To decode base64 back to a string, combine fromBase64 and TextDecoder.
console.log(new TextDecoder().decode(Uint8Array.fromBase64(base64))); // Hello

// When working with Node.js APIs, Buffer.from encodes a string directly,
// with an optional encoding argument.
import { Buffer } from "node:buffer";
console.log(Buffer.from(text, "utf8").toString("base64")); // SGVsbG8=

/**
 * @title Convert a Uint8Array
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Uint8Array} MDN: Uint8Array
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/ReadableStream} MDN: ReadableStream
 * @group Encoding
 *
 * Uint8Array is the workhorse binary type in Deno: file reads, network
 * payloads, and hashes all produce or consume it. This example shows how to
 * convert one into the other common binary and text representations.
 */

// We start with a Uint8Array containing the bytes of the string "Hello".
const bytes = new TextEncoder().encode("Hello");

// To convert to a string, decode the bytes with TextDecoder.
const text = new TextDecoder().decode(bytes);
console.log(text); // Hello

// A Uint8Array is a view over an underlying ArrayBuffer. The view may
// cover only part of that buffer, so to get an exact ArrayBuffer, slice
// the range described by byteOffset and byteLength.
const exact = bytes.buffer.slice(
  bytes.byteOffset,
  bytes.byteOffset + bytes.byteLength,
);
console.log(exact.byteLength); // 5

// If the view is known to span its whole buffer, the buffer property can
// be used directly. This does not copy the bytes.
console.log(bytes.buffer.byteLength); // 5

// To convert to a Blob, pass the array in the parts list of the Blob
// constructor.
const blob = new Blob([bytes]);
console.log(blob.size); // 5

// To create a DataView over the same bytes, pass the buffer together with
// the offset and length of the view.
const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
console.log(view.getUint8(4)); // 111

// ReadableStream.from wraps any iterable into a stream. This is useful for
// APIs that consume streams, like the Response constructor.
const stream = ReadableStream.from([bytes]);
console.log(stream instanceof ReadableStream); // true

// To convert to a base64 or hex string, use the built-in methods available
// since Deno 2.x. The matching fromBase64 and fromHex methods decode back.
console.log(bytes.toBase64()); // SGVsbG8=
console.log(bytes.toHex()); // 48656c6c6f
const decoded = Uint8Array.fromBase64("SGVsbG8=");
console.log(decoded); // Uint8Array(5) [ 72, 101, 108, 108, 111 ]

// When working with Node.js APIs, convert to a Buffer with Buffer.from.
// This copies the bytes. To share memory instead, pass the underlying
// buffer together with the offset and length.
import { Buffer } from "node:buffer";
const nodeBuffer = Buffer.from(bytes);
console.log(nodeBuffer.toString("utf8")); // Hello

