/**
 * @title Parse large CSV files as streams
 * @difficulty beginner
 * @tags cli, deploy
 * @run -R -W <url>
 * @resource {https://jsr.io/@std/csv/doc/~/CsvParseStream} Doc: CsvParseStream
 * @resource {/examples/parsing_serializing_csv/} Example: Parsing and serializing CSV
 * @group Encoding
 *
 * Reading a whole CSV file into memory does not work once the file grows to
 * gigabytes. CsvParseStream from jsr:@std/csv parses records as the bytes
 * arrive, so only one record is in memory at a time. For small files the
 * in-memory parse function shown in /examples/parsing_serializing_csv/ is
 * simpler.
 */
import { CsvParseStream } from "jsr:@std/csv";

// We create a small sample file. In a real application this could be a
// multi-gigabyte export.
const dir = await Deno.makeTempDir();
const path = `${dir}/measurements.csv`;
await Deno.writeTextFile(
  path,
  `city,temperature,humidity
Berlin,18.5,60
Madrid,24.1,35
Oslo,11.2,72
`,
);

// Open the file and build a pipeline. The raw bytes pass through a
// TextDecoderStream to become text, then through a CsvParseStream to
// become records. With skipFirstRow the header line names the fields and
// every record is an object.
const file = await Deno.open(path);
const records = file.readable
  .pipeThrough(new TextDecoderStream())
  .pipeThrough(new CsvParseStream({ skipFirstRow: true }));

// Iterate with for await. The pipeline pulls from the file on demand and
// closes it when the iteration ends. Every field value is a string.
for await (const record of records) {
  console.log(record.city, record.temperature);
}
//- Berlin 18.5
//- Madrid 24.1
//- Oslo 11.2

// Files without a header line work too. The columns option supplies the
// field names and also types the records, so record.city is checked by the
// TypeScript compiler.
const headerless = `${dir}/headerless.csv`;
await Deno.writeTextFile(headerless, `Berlin,18.5,60\nMadrid,24.1,35\n`);
const file2 = await Deno.open(headerless);
const rows = file2.readable
  .pipeThrough(new TextDecoderStream())
  .pipeThrough(
    new CsvParseStream({ columns: ["city", "temperature", "humidity"] }),
  );
for await (const row of rows) {
  console.log(row);
}
//- { city: "Berlin", temperature: "18.5", humidity: "60" }
//- { city: "Madrid", temperature: "24.1", humidity: "35" }

// Reading and writing files requires the -R and -W permissions.
await Deno.remove(dir, { recursive: true });

/**
 * @title User Data Processing with Deno Collections
 * @difficulty intermediate
 * @tags cli, deploy
 * @group Data Processing
 * @run <url>
 *
 * Demonstrates using Deno's @std/collections library for processing user data.
 * This example uses pick, omit, and partition to manipulate data structures.
 */

import { omit, partition, pick } from "jsr:@std/collections";

// Define the User type with fields for id, name, role, age, and country
type User = {
  id: number;
  name: string;
  role: string;
  age: number;
  country: string;
};

// Sample array of user data for demonstration purposes
const users: User[] = [
  { id: 1, name: "Alice", role: "admin", age: 30, country: "USA" },
  { id: 2, name: "Bob", role: "user", age: 25, country: "Canada" },
  { id: 3, name: "Charlie", role: "user", age: 28, country: "USA" },
  { id: 4, name: "Dave", role: "admin", age: 35, country: "Canada" },
  { id: 5, name: "Eve", role: "user", age: 22, country: "UK" },
];

// 1. Pick specific fields from each user for selective data extraction
// Using pick to include only id, name, and country for each user in the new array
const pickedUsers = users.map((user) => pick(user, ["id", "name", "country"]));
console.log("Picked user data:", pickedUsers);

// 2. Omit specific fields from each user to remove sensitive data
// Using omit to exclude the "id" field from each user object in the new array
const omitUsers = users.map((user) => omit(user, ["id"]));
console.log("Omitted user data:", omitUsers);

// 3. Partition users based on role to categorize them into admins and regular users
// Using partition to split users array into two groups: admins and regular users
const [admins, regularUsers] = partition(
  users,
  (user) => user.role === "admin", // Condition to check if user role is admin
);
console.log("Admins:", admins);
console.log("Regular Users:", regularUsers);

/**
 * @title Parse and format dates
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://docs.deno.com/api/web/~/Temporal} Doc: Temporal
 * @resource {/examples/temporal/} Example: Temporal API
 * @group Web Standard APIs
 *
 * Everyday date work is parsing a value, formatting it for people, and
 * doing arithmetic on it. The built-in Temporal API covers all three with
 * explicit types for dates, times, and datetimes. This example walks the
 * common tasks.
 */

// Parse an ISO 8601 string into a plain calendar date. The from method
// validates as it parses.
const date = Temporal.PlainDate.from("2026-06-12");
console.log(date.toString()); // 2026-06-12

// With overflow reject, impossible dates throw instead of clamping.
try {
  Temporal.PlainDate.from("2026-02-30", { overflow: "reject" });
} catch {
  console.log("2026-02-30 is not a real date");
}

// Datetimes parse the same way, and toLocaleString formats them for
// people using the Intl machinery.
const meeting = Temporal.PlainDateTime.from("2026-06-12T09:30:00");
console.log(meeting.toLocaleString("en-US", {
  dateStyle: "long",
  timeStyle: "short",
})); // June 12, 2026 at 9:30 AM

// Date arithmetic is explicit about units, and the calendar handles month
// lengths and leap years.
console.log(date.add({ weeks: 2 }).toString()); // 2026-06-26

// until produces the duration between two dates; total converts it to a
// single unit.
const release = Temporal.PlainDate.from("2026-09-01");
const days = date.until(release).total({ unit: "days", relativeTo: date });
console.log(days); // 81

// Calendar facts are properties, no formulas needed.
console.log(date.dayOfWeek); // 5 (Friday)
console.log(date.daysInMonth); // 30

// Temporal parses ISO 8601 only. For data in custom patterns, parse from
// the standard library converts to a Date. It interprets the value in the
// local time zone, so hand it to Temporal through that same zone to keep
// the calendar date intact.
import { parse } from "jsr:@std/datetime/parse";
const legacy = parse("06/12/2026", "MM/dd/yyyy");
const imported = Temporal.Instant.fromEpochMilliseconds(legacy.getTime())
  .toZonedDateTimeISO(Temporal.Now.timeZoneId()).toPlainDate();
console.log(imported.toString()); // 2026-06-12

/**
 * @title Debounce a function
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://jsr.io/@std/async/doc/~/debounce} Doc: @std/async debounce
 * @resource {https://jsr.io/@std/async/doc/~/DebouncedFunction} Doc: @std/async DebouncedFunction
 * @group Standard library
 *
 * A debounced function waits until calls stop arriving before it runs.
 * That makes it a good fit for noisy event sources, such as file watcher
 * events that fire several times for a single save. This example shows
 * how a burst of calls collapses into one, and how to flush or cancel a
 * pending call.
 */

import { debounce } from "jsr:@std/async/debounce";
import { delay } from "jsr:@std/async/delay";

// Wrap a function with debounce and a wait time in milliseconds. The
// counter proves how many times the wrapped function actually runs.
let runs = 0;
const record = debounce((text: string) => {
  runs += 1;
  console.log(`ran with: ${text}`); // ran with: third
}, 100);

// Three calls land inside the 100ms window. Each call resets the timer,
// so only the last one runs, 100ms after the burst ends.
record("first");
record("second");
record("third");

// Wait past the debounce window so the pending call can fire.
await delay(150);
console.log(`runs: ${runs}`); // runs: 1

// The pending property reports whether a call is waiting. The flush
// method runs that pending call immediately instead of waiting.
const notify = debounce((msg: string) => {
  console.log(`notify: ${msg}`); // notify: deploy finished
}, 5_000);

notify("deploy finished");
console.log(notify.pending); // true
notify.flush();
console.log(notify.pending); // false

// The clear method drops the pending call without running it.
let pings = 0;
const ping = debounce(() => {
  pings += 1;
}, 5_000);

ping();
ping.clear();
console.log(pings); // 0
console.log(ping.pending); // false

/**
 * @title Check if two values are deeply equal
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://jsr.io/@std/assert/doc/~/equal} Doc: @std/assert equal
 * @resource {https://docs.deno.com/api/node/util/} Doc: node:util
 * @group Basics
 *
 * Two objects with the same contents are not equal with the === operator,
 * which compares references. To compare by value, use a deep equality
 * check. This example shows the two built-in options.
 */

// Reference comparison fails even when the contents match.
const first = { a: 1 };
const second = { a: 1 };
console.log(first === second); // false

// The standard library exports equal, a non-throwing deep comparison.
import { equal } from "jsr:@std/assert";

console.log(equal({ a: [1, 2] }, { a: [1, 2] })); // true
console.log(equal(new Map([["a", 1]]), new Map([["a", 1]]))); // true
console.log(equal({ a: 1 }, { a: 1, b: undefined })); // false

// Node.js compatibility offers isDeepStrictEqual with the same job.
import { isDeepStrictEqual } from "node:util";

console.log(isDeepStrictEqual({ a: [1, 2] }, { a: [1, 2] })); // true

// Strict means types matter. A string is never equal to a number.
console.log(isDeepStrictEqual({ a: 1 }, { a: "1" })); // false

// In tests, prefer an asserting variant, which throws with a readable diff
// of the two values on failure.
import { assertEquals } from "jsr:@std/assert";

assertEquals({ a: [1, 2] }, { a: [1, 2] });
console.log("assertEquals passed"); // assertEquals passed

// The Node.js equivalent assertion also works in Deno.
import { deepStrictEqual } from "node:assert/strict";

deepStrictEqual({ a: [1, 2] }, { a: [1, 2] });
console.log("deepStrictEqual passed"); // deepStrictEqual passed

/**
 * @title Deleting files
 * @difficulty beginner
 * @tags cli
 * @resource {https://docs.deno.com/api/deno/~/Deno.remove} Doc: Deno.remove
 * @run -W <url>
 * @group File System
 *
 * Removing files and directories is a common task. Deno has a number of
 * functions for this task.
 */

// In the case that we want to remove a simple file,
// we can simply call Deno.remove with the filename as
// a parameter
await Deno.remove("example.txt");

// There is also a sync version of the api available
await Deno.writeTextFile("toBeRemoved.txt", "noop");
Deno.removeSync("toBeRemoved.txt");

// If we want to remove a directory, we could do exactly
// what we did above. If the directory has contents, the
// call would error out. If we want to recursively delete
// the contents of a directory, we should set recursive to
// true
await Deno.remove("./dir", { recursive: true });

// A common pattern is to remove a file or directory only
// if it already exists. The correct way of doing this is
// by just doing it and trying to catch any NotFound errors.
try {
  await Deno.remove("example.txt");
} catch (err) {
  if (!(err instanceof Deno.errors.NotFound)) {
    throw err;
  }
}

/**
 * @title Bundle code with Deno.bundle
 * @difficulty intermediate
 * @tags cli
 * @run --unstable-bundle -R -W --allow-run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.bundle} Doc: Deno.bundle
 * @resource {https://docs.deno.com/runtime/reference/bundling/} Bundling in the Deno manual
 * @group CLI
 *
 * Deno.bundle compiles a module graph into a single JavaScript file,
 * resolving and inlining all imports, including jsr: and npm: packages. It is
 * the programmatic counterpart of the deno bundle subcommand, useful in build
 * scripts that need to produce self-contained output for browsers, serverless
 * platforms, or distribution.
 */

// Write a small entrypoint to bundle. It pulls a helper from the standard
// library on JSR, so the bundler has a real dependency to resolve.
await Deno.writeTextFile(
  "app.ts",
  `import { toCamelCase } from "jsr:@std/text";
console.log(toCamelCase("hello from the bundle"));
`,
);

// Bundle the entrypoint. The platform option targets either "deno" or
// "browser", and write makes the bundler save the file itself. Without
// outputPath the bundled code is returned in result.outputFiles instead.
const result = await Deno.bundle({
  entrypoints: ["./app.ts"],
  outputPath: "dist/app.js",
  platform: "deno",
  minify: true,
  write: true,
});

// The result reports success and any errors or warnings in a structured
// form, so a build script can fail loudly when something goes wrong.
if (!result.success) {
  for (const error of result.errors) console.error(error.text);
  Deno.exit(1);
}

// The bundle is a single ordinary JavaScript file with the @std/text code
// inlined. It runs anywhere, with no imports left to resolve.
const stat = await Deno.stat("dist/app.js");
console.log(`bundled ${stat.size} bytes`); // bundled 462 bytes

// Run it to prove it is self-contained. Deno.spawnAndWait is a shorthand
// for Deno.Command; pass stdout: "piped" to capture the output instead of
// inheriting the terminal.
const output = await Deno.spawnAndWait(Deno.execPath(), {
  args: ["run", "dist/app.js"],
  stdout: "piped",
});
console.log(new TextDecoder().decode(output.stdout)); // helloFromTheBundle

/**
 * @title Compile a script into an executable
 * @difficulty beginner
 * @tags cli
 * @run <url> Deno
 * @resource {https://docs.deno.com/runtime/reference/cli/compile/} Doc: deno compile
 * @resource {/examples/command_line_arguments} Example: Command line arguments
 * @group CLI
 *
 * The deno compile subcommand turns a script and all of its dependencies
 * into a single self-contained binary. The result runs on machines that do
 * not have Deno installed, which makes it a simple way to ship command line
 * tools.
 */

// Any script can be compiled. This one greets whoever is named in the first
// command line argument.
const name = Deno.args[0] ?? "world";
console.log(`Hello, ${name}!`);

// Compile it. Deno bundles the script together with the runtime and writes
// an executable named after the file:
//
//   deno compile greet.ts
//   Compile greet.ts to greet
//
//   Embedded Files
//
//   greet
//   └── greet.ts (70B)
//
//   Files: 1.53KB
//   Metadata: 1.38KB
//   Remote modules: 12B

// The binary is a normal executable. It is large, roughly 70 MB, because
// the whole JavaScript runtime is embedded in it.
//
//   ./greet
//   Hello, world!
//
//   ./greet Deno
//   Hello, Deno!

// Use the --output flag to pick a different name or path for the binary:
//
//   deno compile --output hello greet.ts

// Permission flags given at compile time are baked into the binary. This
// program fetches a page, so it is compiled with -N for network access.
// Whoever runs the binary is never prompted, and the program can never
// exceed the permissions it was compiled with.
//
//   deno compile -N --output check_site server.ts
//   Check server.ts
//   Compile server.ts to check_site
//
//   ./check_site
//   200

// Data files are not picked up automatically, because only imported modules
// are bundled. The --include flag embeds extra files into the binary. The
// program reads them with regular file APIs, resolved against
// import.meta.url:
//
//   const banner = await Deno.readTextFile(
//     new URL("./banner.txt", import.meta.url),
//   );
//
//   deno compile --include banner.txt --output app app.ts
//   Compile app.ts to app
//
//   Embedded Files
//
//   app
//   ├── app.ts (377B)
//   └── banner.txt (20B)
//
//   ./app
//   Welcome to the show

// Cross-compilation produces binaries for other platforms. The --target
// flag accepts these values:
//
//   x86_64-unknown-linux-gnu
//   aarch64-unknown-linux-gnu
//   x86_64-pc-windows-msvc
//   x86_64-apple-darwin
//   aarch64-apple-darwin

// On the first use of a foreign target, Deno downloads the runtime for that
// platform and caches it. This Linux binary was produced on a Mac:
//
//   deno compile --target x86_64-unknown-linux-gnu --output greet-linux greet.ts
//   Compile greet.ts to greet-linux
//   Download https://dl.deno.land/.../denort-x86_64-unknown-linux-gnu.zip
//
//   file greet-linux
//   greet-linux: ELF 64-bit LSB pie executable, x86-64 ...

/**
 * @title Find and update outdated dependencies
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://docs.deno.com/runtime/reference/cli/outdated/} Doc: deno outdated
 * @resource {https://docs.deno.com/runtime/fundamentals/modules/} Doc: Modules and dependencies
 * @group CLI
 *
 * Dependencies pinned months ago quietly fall behind. The deno outdated
 * subcommand compares what your lockfile resolves to against the newest
 * versions on JSR and npm, and can rewrite deno.json for you.
 */

// This script imports one dependency at an old version, the kind of pin
// that accumulates in any project over time.
import { basename } from "jsr:@std/path@1.0.6";

console.log(basename("/tmp/projects/report.txt"));

// The walkthrough below uses a project with a deno.json import map and a
// lockfile created back when these versions were current:
//
//   {
//     "imports": {
//       "@std/path": "jsr:@std/path@^1.0.6",
//       "chalk": "npm:chalk@^4.1.0"
//     }
//   }

// Running deno outdated prints a table. Current is what the lockfile
// resolves today, Update is the newest version that still satisfies the
// semver range in deno.json, and Latest is the newest version overall:
//
//   deno outdated
//   ┌───────────────┬─────────┬────────┬────────┐
//   │ Package       │ Current │ Update │ Latest │
//   ├───────────────┼─────────┼────────┼────────┤
//   │ jsr:@std/path │ 1.0.6   │ 1.1.5  │ 1.1.5  │
//   ├───────────────┼─────────┼────────┼────────┤
//   │ npm:chalk     │ 4.1.0   │ 4.1.2  │ 5.6.2  │
//   └───────────────┴─────────┴────────┴────────┘
//
//   Run deno update --latest to update to the latest available versions,
//   or deno outdated --help for more information.

// The --update flag applies the Update column. It respects the semver
// ranges, so chalk moves to the newest 4.x release and does not cross into
// the 5.x major:
//
//   deno outdated --update
//   Updated 2 dependencies:
//    - jsr:@std/path ^1.0.6 -> ^1.1.5
//    - npm:chalk     ^4.1.0 -> ^4.1.2

// Adding --latest crosses major version boundaries and applies the Latest
// column instead:
//
//   deno outdated --update --latest
//   Updated 2 dependencies:
//    - jsr:@std/path ^1.0.6 -> ^1.1.5
//    - npm:chalk     ^4.1.0 -> ^5.6.2

// Both forms rewrite deno.json in place. After --update --latest the import
// map reads:
//
//   {
//     "imports": {
//       "@std/path": "jsr:@std/path@^1.1.5",
//       "chalk": "npm:chalk@^5.6.2"
//     }
//   }

// Major version jumps can contain breaking changes, so review the changelog
// before reaching for --latest. The plain deno outdated command makes no
// changes at all and is always safe to run.

