/**
 * @title Download a file with progress
 * @difficulty intermediate
 * @tags cli
 * @run -N -W <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/TransformStream} MDN: TransformStream
 * @resource {/examples/streaming_files} Example: Streaming file operations
 * @group Network
 *
 * Streaming a download straight to disk keeps memory flat no matter how big
 * the file is. A TransformStream sits in the middle of the pipe, counts the
 * bytes flowing through, and reports progress against the content-length
 * header. The chunks themselves pass through untouched.
 */

const url = "https://deno.com/favicon.ico";
const output = "favicon.ico";

const response = await fetch(url);
if (!response.ok || response.body === null) {
  throw new Error(`download failed: ${response.status}`);
}

// content-length is the total size in bytes. Servers that compress or
// stream on the fly may omit it, so treat it as optional.
const total = Number(response.headers.get("content-length") ?? "0");

let received = 0;
let lastReport = Date.now();

function report() {
  if (total > 0) {
    const percent = Math.floor((received / total) * 100);
    console.log(`${received} / ${total} bytes (${percent}%)`);
  } else {
    // Without content-length there is no percentage, only a running count.
    console.log(`${received} bytes`);
  }
}

// The transform sees every chunk on its way to the file, without copying
// or buffering anything. Reporting is throttled so a large download does
// not print thousands of lines.
const progress = new TransformStream<Uint8Array, Uint8Array>({
  transform(chunk, controller) {
    received += chunk.byteLength;
    const now = Date.now();
    if (now - lastReport >= 100) {
      lastReport = now;
      report();
    }
    controller.enqueue(chunk);
  },
});

// Deno.open returns a file whose writable property is a standard
// WritableStream, so the response body pipes directly into it. pipeTo
// closes the file when the stream ends.
const file = await Deno.open(output, {
  write: true,
  create: true,
  truncate: true,
});
await response.body.pipeThrough(progress).pipeTo(file.writable);

// One final report, because the throttle may have skipped the last chunk.
report();
console.log(`saved ${output}`);

// With node:fs the same pipe works through the web stream bridge:
// Readable.fromWeb(response.body).pipe(createWriteStream(output)).
//
//   deno run -N -W download_progress.ts
//   15406 / 15406 bytes (100%)
//   saved favicon.ico
//
// Small files arrive in a few chunks, so only the final report prints.
// Larger downloads print a progress line roughly every 100 milliseconds.

/**
 * @title Sign and verify data with ECDSA
 * @difficulty intermediate
 * @tags cli, deploy
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/SubtleCrypto/sign} MDN: SubtleCrypto.sign
 * @resource {https://docs.deno.com/api/web/~/SubtleCrypto} Doc: crypto.subtle
 * @group Cryptography
 *
 * A digital signature proves that a message was produced by the holder of a
 * private key and was not modified in transit. Anyone with the matching
 * public key can check the signature, but only the private key can create
 * it. This example uses ECDSA on the P-256 curve from the built-in Web
 * Crypto API.
 */

// Generate an ECDSA key pair on the P-256 curve. The private key signs,
// the public key verifies.
const { privateKey, publicKey } = await crypto.subtle.generateKey(
  { name: "ECDSA", namedCurve: "P-256" },
  true,
  ["sign", "verify"],
);

// Sign a message. ECDSA hashes the data first, here with SHA-256, and the
// signature changes on every run because ECDSA mixes in a random nonce.
const message = new TextEncoder().encode("release v2.0.0");
const signature = await crypto.subtle.sign(
  { name: "ECDSA", hash: "SHA-256" },
  privateKey,
  message,
);
console.log(new Uint8Array(signature).toHex()); // e.g. 989b58f4b154...

// Verify the signature against the original message with the public key.
const valid = await crypto.subtle.verify(
  { name: "ECDSA", hash: "SHA-256" },
  publicKey,
  signature,
  message,
);
console.log(valid); // true

// A tampered message fails verification, even for a one character change.
const tampered = new TextEncoder().encode("release v2.0.1");
console.log(
  await crypto.subtle.verify(
    { name: "ECDSA", hash: "SHA-256" },
    publicKey,
    signature,
    tampered,
  ),
); // false

// Export the public key as JWK to share it with whoever needs to verify
// your signatures. The x and y fields hold the public curve point; a
// private key JWK would also carry the secret d field, so never share that.
const jwk = await crypto.subtle.exportKey("jwk", publicKey);
console.log(jwk.kty); // EC
console.log(jwk.crv); // P-256

// The receiving side imports the JWK and gets a key usable for verify.
const imported = await crypto.subtle.importKey(
  "jwk",
  jwk,
  { name: "ECDSA", namedCurve: "P-256" },
  true,
  ["verify"],
);
console.log(
  await crypto.subtle.verify(
    { name: "ECDSA", hash: "SHA-256" },
    imported,
    signature,
    message,
  ),
); // true

/**
 * @title Environment variables
 * @difficulty beginner
 * @tags cli, deploy
 * @run -E <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.env} Doc: Deno.env
 * @resource {https://docs.deno.com/deploy/classic/environment-variables} Deploy Docs: Environment Variables
 * @group System
 *
 * Environment variables can be used to configure the behavior of a program,
 * or pass data from one program to another.
 */

// Here an environment variable with the name "PORT" is read. If this variable
// is set the return value will be a string. If it is unset it will be `undefined`.
const PORT = Deno.env.get("PORT");
console.log("PORT:", PORT);

// You can also get an object containing all environment variables.
const env = Deno.env.toObject();
console.log("env:", env);

// Environment variables can also be set. The set environment variable only affects
// the current process, and any new processes that are spawned from it. It does
// not affect parent processes or the user shell.
Deno.env.set("MY_PASSWORD", "123456");

// You can also unset an environment variable.
Deno.env.delete("MY_PASSWORD");

// Note that environment variables are case-sensitive on unix, but not on
// Windows. This means that these two invocations will have different results
// between platforms.
Deno.env.set("MY_PASSWORD", "123");
Deno.env.set("my_password", "456");
console.log("UPPERCASE:", Deno.env.get("MY_PASSWORD"));
console.log("lowercase:", Deno.env.get("my_password"));

// Access to environment variables is only possible if the Deno process is
// running with env var permissions (`-E`). You can limit the permission
// to only a specific number of environment variables (`-E=PORT,MY_PASSWORD`).

/**
 * @title Escape an HTML string
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://jsr.io/@std/html/doc/~/escape} Doc: @std/html escape
 * @resource {https://owasp.org/www-community/attacks/xss/} OWASP: Cross Site Scripting
 * @group Web Standard APIs
 *
 * Interpolating user input into HTML without escaping it opens the door to
 * cross-site scripting. The standard library escapes the five significant
 * characters for you. This example shows escaping and unescaping.
 */
import { escape, unescape } from "jsr:@std/html/entities";

// Escape replaces the characters that carry meaning in HTML with their
// entity equivalents.
const userInput = `<img src=x onerror="alert('pwned')">`;
const escaped = escape(userInput);
console.log(escaped); // &lt;img src=x onerror=&quot;alert(&#39;pwned&#39;)&quot;&gt;

// The escaped string is safe to interpolate into markup as text content or
// a quoted attribute value.
const html = `<p>You said: ${escaped}</p>`;
console.log(html.startsWith("<p>You said: &lt;img")); // true

// Unescape reverses the transformation, including named entities.
console.log(unescape(escaped)); // <img src=x onerror="alert('pwned')">

// Escaping is for HTML text and attributes only. URLs, CSS, and script
// contexts each need their own encoding, and a templating engine or
// framework usually handles all of them for you.

/**
 * @title Use EventEmitter from node:events
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://docs.deno.com/api/node/events/} Doc: node:events
 * @resource {https://docs.deno.com/examples/web_workers/} Example: Web workers
 * @group System
 *
 * EventEmitter is the classic Node.js building block for things that emit
 * named events, and countless npm packages hand you one. Deno supports it
 * through the node:events module. This example registers listeners, emits
 * events, and shows the special behavior of the error event.
 */

import { EventEmitter, once } from "node:events";

const emitter = new EventEmitter();

// on registers a listener that runs for every matching emit. The extra
// emit arguments are passed to the listener.
function onMessage(text: string) {
  console.log(`received: ${text}`);
}
emitter.on("message", onMessage);
emitter.emit("message", "hello"); // received: hello
emitter.emit("message", "again"); // received: again

// once (the method) registers a listener that runs a single time and is
// then removed automatically.
emitter.once("connected", () => console.log("connected fired"));
emitter.emit("connected"); // connected fired
emitter.emit("connected"); // (nothing, the listener is gone)

// off removes a previously registered listener. You need the same
// function reference you passed to on.
emitter.off("message", onMessage);
emitter.emit("message", "ignored"); // (nothing)

// emit returns whether any listener was called, which is an easy way to
// see the effect.
console.log(emitter.emit("message", "ignored")); // false

// The error event is special: emitting it with no error listener
// registered throws the error instead of silently doing nothing. Always
// attach an error listener to emitters that can fail.
try {
  emitter.emit("error", new Error("disk full"));
} catch (err) {
  console.log(`threw: ${(err as Error).message}`); // threw: disk full
}
emitter.on("error", (err: Error) => console.log(`handled: ${err.message}`));
emitter.emit("error", new Error("disk full")); // handled: disk full

// The once function (imported from node:events, not the method) returns a
// promise that resolves with the event arguments, which lets you await an
// event in async code.
setTimeout(() => emitter.emit("ready", "database"), 10);
const [what] = await once(emitter, "ready");
console.log(`ready: ${what}`); // ready: database

/**
 * @title Create and dispatch custom events
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/EventTarget} MDN: EventTarget
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/CustomEvent} MDN: CustomEvent
 * @group Web Standard APIs
 *
 * EventTarget is the eventing system behind the DOM, and it works as a
 * base class for your own types. Subscribers attach with addEventListener
 * and you publish with dispatchEvent. CustomEvent carries a payload in
 * its detail property. This example builds a small music player on top
 * of it.
 */

// Extend EventTarget to give a class its own events. The play method
// dispatches a cancelable CustomEvent and respects the listeners' verdict.
class Player extends EventTarget {
  play(track: string): boolean {
    const event = new CustomEvent("play", {
      detail: { track },
      cancelable: true,
    });
    // dispatchEvent returns false if any listener called preventDefault
    // on a cancelable event, so the default action can be skipped.
    const allowed = this.dispatchEvent(event);
    if (allowed) console.log(`playing ${track}`); // playing intro.mp3 (and one line per later allowed call)
    return allowed;
  }
}

const player = new Player();

// A plain listener runs on every dispatch. The payload passed as detail
// when the event was created is available on the event object.
player.addEventListener("play", (event) => {
  const { track } = (event as CustomEvent<{ track: string }>).detail;
  console.log(`now playing: ${track}`); // now playing: intro.mp3 (and one line per later play call)
});

player.play("intro.mp3");

// The once option removes the listener automatically after the first
// call, so the second play below does not log "first play" again.
player.addEventListener("play", () => console.log("first play"), {
  once: true,
});

player.play("verse.mp3");
player.play("chorus.mp3");

// The signal option ties a listener to an AbortController. Aborting the
// controller removes the listener, which is easier than keeping the
// function reference around for removeEventListener.
const controller = new AbortController();
player.addEventListener("play", () => console.log("logging analytics"), {
  signal: controller.signal,
});

player.play("bridge.mp3");
controller.abort();
player.play("outro.mp3");

// A listener can veto the default action with preventDefault, because
// the event was created with cancelable set to true. dispatchEvent then
// returns false and play skips its default action.
player.addEventListener("play", (event) => event.preventDefault(), {
  once: true,
});

console.log(player.play("blocked.mp3")); // false

/**
 * @title Set and read process exit codes
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.exitCode} Doc: Deno.exitCode
 * @resource {https://docs.deno.com/api/deno/~/Deno.exit} Doc: Deno.exit
 * @group System
 *
 * The exit code is how a program reports success or failure to the shell,
 * where zero means success and anything else means failure. Deno.exit(n)
 * stops the process immediately with code n. Deno.exitCode just records the
 * code, the program keeps running and exits with it naturally later, which
 * lets cleanup code and remaining work finish first.
 */
import process from "node:process";

// These listeners run when the program is about to exit naturally. The
// beforeunload event fires when the event loop runs out of work and can be
// cancelled to schedule more. The unload event fires last and cannot be
// cancelled. Note that Deno.exit skips beforeunload but still fires unload.
globalThis.addEventListener("beforeunload", () => {
  console.log("beforeunload: event loop is out of work"); // beforeunload: event loop is out of work
});
globalThis.addEventListener("unload", () => {
  console.log("unload: process is exiting"); // unload: process is exiting
});

// Record a failure without stopping the program. Something went wrong, but
// the lines below still run.
Deno.exitCode = 1;

// Reading the property back shows the code the process would exit with.
console.log(`exit code is now ${Deno.exitCode}`); // exit code is now 1

// Suppose a retry succeeded, so the failure is reset. This example sets the
// code back to zero so running it reports success. A real program would
// leave the failure code in place:
//
//   $ deno run fail.ts; echo $?
//   1
Deno.exitCode = 0;

// Code that uses the node:process module can set process.exitCode the
// same way.
process.exitCode = 0;

// The alternative is Deno.exit, which stops the process at once. Nothing
// after the call runs, so it is commented out here:
//
//   Deno.exit(1);

/**
 * @title Exponential backoff
 * @difficulty intermediate
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://en.wikipedia.org/wiki/Exponential_backoff} Wikipedia: Exponential backoff
 * @resource {https://jsr.io/@std/async/doc/~/retry} Doc: @std/async > retry
 * @group Advanced
 *
 * Exponential backoff is a technique used in computer systems to handle retries and
 * avoid overwhelming services. We can easily implement this by using the `retry`
 * utility provided by the standard library.
 */

// Import the 'retry' utility from '@std/async'.
import { retry, RetryError, type RetryOptions } from "jsr:@std/async";

// A function that logs 'hello world' to the console and returns a rejected Promise.
const fn = () => {
  console.log("hello world");
  return Promise.reject("rejected");
};

// Configuration for retry options which will make sure that the function will be
// called at max 3 times before throwing an error. The first call to the function
// will be made immediately, the second call will happen after a delay of 10ms
// and the third/final call will be made after a delay of 20ms.
const options: RetryOptions = {
  maxAttempts: 3,
  minTimeout: 10,
  multiplier: 2,
  jitter: 0,
};

try {
  // Wrap the function with the 'retry' utility along with the retry configuration.
  await retry(fn, options);
} catch (err) {
  // When max attempts are exhausted, a RetryError is thrown containing the original
  // rejection reason 'rejected' as its cause property.
  if (err instanceof RetryError) {
    console.log("Retry error :", err.message);
    console.log("Error cause :", err.cause);
  }
}

/**
 * @title Extract links and metadata from HTML
 * @difficulty beginner
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://jsr.io/@b-fuze/deno-dom} Doc: deno-dom
 * @resource {https://ogp.me/} Reference: Open Graph protocol
 * @group Web Standard APIs
 *
 * Scrapers, link checkers, and preview cards all start the same way: fetch
 * a page and pull data out of its HTML. This example parses a page with
 * deno-dom and extracts its links, title, and social metadata.
 */
import { DOMParser } from "jsr:@b-fuze/deno-dom";

// Fetch a page and parse the HTML into a queryable document.
const html = await (await fetch("https://example.com/")).text();
const doc = new DOMParser().parseFromString(html, "text/html");

// Extract every link with the same querySelectorAll you would use in a
// browser. Resolving against the page URL turns relative hrefs absolute.
for (const anchor of doc.querySelectorAll("a[href]")) {
  const href = new URL(anchor.getAttribute("href")!, "https://example.com/");
  console.log(href.href); // https://www.iana.org/domains/example
}

// The document title works like in the browser too.
console.log(doc.title); // Example Domain

// Social preview cards read Open Graph meta tags. Collect every og:
// property into a record.
const og: Record<string, string> = {};
for (const meta of doc.querySelectorAll('meta[property^="og:"]')) {
  const property = meta.getAttribute("property")!.slice(3);
  og[property] = meta.getAttribute("content") ?? "";
}
console.log(og); // {} (example.com has no Open Graph tags)

// Pages without Open Graph tags usually still have a description.
const description = doc.querySelector('meta[name="description"]')
  ?.getAttribute("content");
console.log(description ?? "(no description)");

/**
 * @title Route fetch through an HTTP proxy
 * @difficulty intermediate
 * @tags cli
 * @run -N <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.createHttpClient} Doc: Deno.createHttpClient
 * @resource {/runtime/reference/env_variables/} Environment variables that Deno reads
 * @group Network
 *
 * Deno honors the HTTP_PROXY, HTTPS_PROXY, and NO_PROXY environment
 * variables by default, for both module downloads and fetch, with no code
 * changes. When one fetch call needs a different proxy than the rest of the
 * process, Deno.createHttpClient configures a proxy explicitly. This example
 * starts a tiny logging proxy and routes a single fetch through it.
 */

// A client talking to an HTTP proxy puts the absolute target URL in the
// request line instead of just a path. Deno.serve exposes that URL as
// req.url, so forwarding it with fetch is enough to act as a basic proxy
// for plain HTTP targets. A real proxy also implements the CONNECT method
// to tunnel HTTPS traffic, which this handler does not.
const proxy = Deno.serve({ port: 8080 }, async (req) => {
  console.log("proxy saw:", req.method, req.url);
  const headers = new Headers(req.headers);
  headers.delete("host");
  return await fetch(req.url, {
    method: req.method,
    headers,
    body: req.body,
    redirect: "manual",
  });
});

// createHttpClient returns a client with its own connection settings.
// Passing it through the client option of fetch routes only that call
// through the proxy; every other fetch in the process is unaffected.
const client = Deno.createHttpClient({
  proxy: { url: "http://localhost:8080/" },
});

const response = await fetch("http://example.com/", { client });
const body = await response.text();
console.log("status:", response.status);
console.log("got example.com:", body.includes("Example Domain"));

// Close the client and stop the proxy so the script exits.
client.close();
await proxy.shutdown();

// The proxy logs the absolute URL it was asked for, which proves the
// request went through it rather than straight to example.com:
//
//   deno run -N fetch_http_proxy.ts
//   Listening on http://0.0.0.0:8080/ (http://localhost:8080/)
//   proxy saw: GET http://example.com/
//   status: 200
//   got example.com: true

// To proxy everything without touching code, set the environment variables
// instead. NO_PROXY lists hosts that bypass the proxy:
//
//   HTTP_PROXY=http://localhost:8080 deno run -N main.ts
//   NO_PROXY=localhost,127.0.0.1 HTTPS_PROXY=http://proxy.example.com:3128 deno run -N main.ts

/**
 * @title Set a timeout on fetch
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run -N <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/AbortSignal/timeout_static} MDN: AbortSignal.timeout
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/AbortSignal/any_static} MDN: AbortSignal.any
 * @group Web Standard APIs
 *
 * fetch has no timeout option, but it accepts an AbortSignal, and
 * AbortSignal.timeout builds one that aborts after a given number of
 * milliseconds. This example times out a slow request, tells timeouts
 * apart from other failures, and combines a timeout with a manual cancel.
 */

// Start a local server where the delay is controlled by a query parameter,
// so the timeouts in this example are deterministic and self-contained.
const server = Deno.serve({ port: 0, onListen() {} }, async (req) => {
  const delay = Number(new URL(req.url).searchParams.get("delay"));
  await new Promise((resolve) => setTimeout(resolve, delay));
  return new Response(`answered after ${delay}ms`);
});
const base = `http://localhost:${server.addr.port}`;

// When the response arrives before the deadline, the signal does nothing.
const fast = await fetch(`${base}/?delay=0`, {
  signal: AbortSignal.timeout(1000),
});
console.log(await fast.text()); // answered after 0ms

// When the deadline passes first, fetch rejects with a DOMException whose
// name is TimeoutError, not AbortError.
try {
  await fetch(`${base}/?delay=1000`, { signal: AbortSignal.timeout(200) });
} catch (err) {
  console.log((err as DOMException).name); // TimeoutError
}

// Other failures have different names, so you can tell them apart and only
// retry what makes sense. A connection error rejects with a TypeError.
try {
  await fetch("http://localhost:9/", { signal: AbortSignal.timeout(1000) });
} catch (err) {
  if ((err as Error).name === "TimeoutError") {
    console.log("the server was too slow");
  } else {
    console.log(`not a timeout: ${(err as Error).name}`); // not a timeout: TypeError
  }
}

// AbortSignal.any combines a deadline with a manual cancel button. The
// fetch rejects with the reason of whichever signal aborts first.
const cancelButton = new AbortController();
const signal = AbortSignal.any([
  cancelButton.signal,
  AbortSignal.timeout(2000),
]);
setTimeout(() => cancelButton.abort(new Error("user pressed cancel")), 50);

try {
  await fetch(`${base}/?delay=1000`, { signal });
} catch (err) {
  console.log((err as Error).message); // user pressed cancel
}

// Stop the local server so the script can exit.
await server.shutdown();

/**
 * @title Fetch over a Unix socket
 * @difficulty intermediate
 * @tags cli
 * @run -N -R -W <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.createHttpClient} Doc: Deno.createHttpClient
 * @resource {https://docs.deno.com/api/deno/~/Deno.serve} Doc: Deno.serve
 * @group Network
 *
 * Local services like the Docker daemon expose HTTP over a Unix domain
 * socket instead of a TCP port. This example serves HTTP on a socket file
 * and fetches from it.
 */

// Deno.serve listens on a Unix socket when given a path instead of a port.
const server = Deno.serve(
  { path: "/tmp/example.sock" },
  () => new Response("Hello over a Unix socket"),
);

// On the client side, create an HTTP client that connects through the
// socket, and pass it to fetch. The URL's hostname is ignored; only the
// path and headers matter to the server.
const client = Deno.createHttpClient({
  proxy: { transport: "unix", path: "/tmp/example.sock" },
});

const response = await fetch("http://localhost/", { client });
console.log(await response.text()); // Hello over a Unix socket

client.close();
await server.shutdown();

// The Node.js API supports Unix sockets too: a node:http server listens on
// a path, and the client passes socketPath in the request options.
import { createServer, request } from "node:http";

const nodeServer = createServer((_req, res) => {
  res.end("Hello from node:http");
});
nodeServer.listen("/tmp/example-node.sock", () => {
  const req = request(
    { socketPath: "/tmp/example-node.sock", path: "/" },
    (res) => {
      res.on("data", (chunk) => console.log(String(chunk))); // Hello from node:http
      res.on("end", () => nodeServer.close());
    },
  );
  req.end();
});

// The same client works for talking to existing services. For example,
// with -R -W -N permissions and Docker running, this lists containers:
//
//   const docker = Deno.createHttpClient({
//     proxy: { transport: "unix", path: "/var/run/docker.sock" },
//   });
//   await fetch("http://localhost/containers/json", { client: docker });

/**
 * @title Call C functions with FFI
 * @difficulty intermediate
 * @tags cli
 * @run --allow-ffi <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.dlopen} Doc: Deno.dlopen
 * @resource {https://docs.deno.com/api/deno/~/Deno.UnsafeCallback} Doc: Deno.UnsafeCallback
 * @resource {https://docs.deno.com/runtime/fundamentals/ffi/} FFI in the Deno manual
 * @group System
 *
 * The Foreign Function Interface lets Deno call functions in native shared
 * libraries directly, with no glue code or build step. Deno.dlopen opens a
 * library, you describe the signatures of the symbols you need, and they
 * become callable JavaScript functions. This example calls into the C
 * standard library, which is already present on every system.
 */

// Every platform ships a C library under a different name. The C standard
// library is a convenient demo target because it requires no installation,
// but the same approach works for any shared library, including ones you
// build yourself.
const libNames: Partial<Record<typeof Deno.build.os, string>> = {
  darwin: "/usr/lib/libSystem.B.dylib",
  linux: "libc.so.6",
  windows: "msvcrt.dll",
};
const libName = libNames[Deno.build.os];
if (!libName) throw new Error(`Unsupported OS: ${Deno.build.os}`);

// Open the library and declare the symbols to bind. Each entry gives the
// parameter types and result type in C terms: buffer accepts a TypedArray
// and passes a pointer to its bytes, usize is an unsigned size_t, and
// function accepts a pointer to a callback.
const libc = Deno.dlopen(libName, {
  strlen: { parameters: ["buffer"], result: "usize" },
  qsort: {
    parameters: ["buffer", "usize", "usize", "function"],
    result: "void",
  },
});

// Call strlen with a NUL-terminated byte buffer. C strings end with a zero
// byte, so we append one explicitly. Results of type usize come back as
// BigInt because size_t can exceed the safe integer range.
const message = new TextEncoder().encode("Hello from C\0");
console.log(libc.symbols.strlen(message)); // 12n

// Native code can also call back into JavaScript. Deno.UnsafeCallback wraps
// a JavaScript function in a native function pointer. Here we build a
// comparator for the C qsort function. The arguments arrive as raw
// pointers, and UnsafePointerView reads typed values from them.
const comparator = new Deno.UnsafeCallback(
  { parameters: ["pointer", "pointer"], result: "i32" },
  (a, b) => {
    const x = new Deno.UnsafePointerView(a!).getInt32();
    const y = new Deno.UnsafePointerView(b!).getInt32();
    return x - y;
  },
);

// Sort an Int32Array in place by handing qsort the buffer, the element
// count, the element size in bytes, and our comparator pointer.
const numbers = new Int32Array([42, 7, 19, 1, 88]);
libc.symbols.qsort(numbers, BigInt(numbers.length), 4n, comparator.pointer);
console.log([...numbers]); // [ 1, 7, 19, 42, 88 ]

// Close the callback and the library when you are done with them so the
// process can release the native resources.
comparator.close();
libc.close();

/**
 * @title Lock files across processes
 * @difficulty beginner
 * @tags cli
 * @run -R -W --allow-run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.FsFile.prototype.lock} Doc: Deno.FsFile.lock
 * @resource {https://docs.deno.com/api/deno/~/Deno.Command} Doc: Deno.Command
 * @group File System
 *
 * When two processes write the same file at the same time, the result is a
 * mess. File locks coordinate access: while one process holds an exclusive
 * lock, others that ask for it wait. This example holds a lock in the main
 * process and spawns a second Deno process that blocks until the lock is
 * released.
 */

// We work in a temporary directory with one shared file.
const dir = await Deno.makeTempDir();
const path = `${dir}/shared.txt`;
await Deno.writeTextFile(path, "shared state");

// This script runs in the second process. It opens the same file and asks
// for an exclusive lock. The lock(true) call does not fail when the file
// is already locked, it simply waits, so we measure how long it blocked.
const childScript = `
const file = await Deno.open(Deno.args[0], { read: true, write: true });
console.log("child:  requesting exclusive lock");
const start = Date.now();
await file.lock(true);
console.log("child:  lock acquired after " + (Date.now() - start) + " ms");
await file.unlock();
file.close();
`;
await Deno.writeTextFile(`${dir}/child.ts`, childScript);

// The main process takes the exclusive lock first. Passing true means
// exclusive (one holder); without it the lock is shared, which lets many
// readers coexist while still excluding writers.
const file = await Deno.open(path, { read: true, write: true });
await file.lock(true);
console.log("parent: holding exclusive lock");

// Now we start the child. It inherits stdout, so its messages appear
// interleaved with ours and tell the story in order.
const child = new Deno.Command(Deno.execPath(), {
  args: ["run", "--allow-read", "--allow-write", `${dir}/child.ts`, path],
  stdout: "inherit",
  stderr: "inherit",
}).spawn();

// We hold the lock for two seconds. During this time the child starts up,
// prints its first message and then blocks inside lock(true).
await new Promise((resolve) => setTimeout(resolve, 2000));
console.log("parent: releasing lock");
await file.unlock();

// The moment we release, the child's lock call resolves and it finishes.
await child.status;

// To attempt a lock without blocking, use tryLock. It returns true when
// the lock was acquired and false when someone else holds it, which suits
// a skip-if-busy pattern better than waiting.
const again = await file.tryLock(true);
console.log("parent: tryLock after child released:", again); // true
if (again) {
  await file.unlock();
}
file.close();

// The whole run prints, with the wait time varying slightly:
// parent: holding exclusive lock
// child:  requesting exclusive lock
// parent: releasing lock
// child:  lock acquired after 1927 ms

// Locks are advisory: they only coordinate processes that ask for the
// lock, and they are released automatically when a process exits.
await Deno.remove(dir, { recursive: true });

/**
 * @title Read and change file metadata
 * @difficulty beginner
 * @tags cli
 * @run -R -W <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.stat} Doc: Deno.stat
 * @resource {https://docs.deno.com/api/deno/~/Deno.FileInfo} Doc: Deno.FileInfo
 * @group File System
 *
 * Every file carries metadata besides its contents: size, timestamps, type
 * and permissions. This example reads that metadata with Deno.stat, changes
 * permissions with Deno.chmod, and sets timestamps with Deno.utime.
 */

// We set up a temporary directory with a small file to inspect.
const dir = await Deno.makeTempDir();
const path = `${dir}/data.txt`;
await Deno.writeTextFile(path, "twelve bytes");

// Deno.stat returns a FileInfo object with the size in bytes, the type and
// the timestamps. The timestamps are Date objects (or null on platforms
// that do not record them).
const info = await Deno.stat(path);
console.log(info.size); // 12
console.log(info.isFile); // true
console.log(info.mtime instanceof Date); // true
console.log(info.birthtime instanceof Date); // true

// On a symlink, stat follows the link and describes the target, while
// lstat describes the link itself.
await Deno.symlink(path, `${dir}/link.txt`);
console.log((await Deno.stat(`${dir}/link.txt`)).isFile); // true
console.log((await Deno.lstat(`${dir}/link.txt`)).isSymlink); // true

// The mode field holds the raw Unix permission bits. Masking with 0o777
// keeps just the permission part, in the familiar octal form.
console.log((info.mode! & 0o777).toString(8)); // 644

// Deno.chmod changes those permission bits. Here we drop access for group
// and others. On Windows only the write permission can be changed, and
// stat reports mode as null there.
await Deno.chmod(path, 0o600);
const after = await Deno.stat(path);
console.log((after.mode! & 0o777).toString(8)); // 600

// Deno.utime sets the access and modification times to any date you like,
// which is handy for tools like build systems that compare timestamps.
const date = new Date("2020-01-02T03:04:05Z");
await Deno.utime(path, date, date);
console.log((await Deno.stat(path)).mtime?.toISOString()); // 2020-01-02T03:04:05.000Z

// Reading metadata requires the -R permission; chmod and utime require -W.
await Deno.remove(dir, { recursive: true });

/**
 * @title Convert between file URLs and paths
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://jsr.io/@std/path/doc/~/fromFileUrl} Doc: @std/path fromFileUrl
 * @resource {https://docs.deno.com/examples/module_metadata_tutorial/} Example: Module Metadata
 * @group File System
 *
 * Modules are identified by URLs in Deno, while file system APIs take
 * paths. import.meta.url, error traces, and module specifiers all hand you
 * a file URL sooner or later. This example converts in both directions.
 */
import { fromFileUrl, toFileUrl } from "jsr:@std/path";

// To convert a file URL to a path, use fromFileUrl. It handles the
// platform differences, like drive letters on Windows.
console.log(fromFileUrl("file:///tmp/data.txt")); // /tmp/data.txt

// To convert a path to a file URL, use toFileUrl. The path must be
// absolute.
console.log(toFileUrl("/tmp/data.txt").href); // file:///tmp/data.txt

// The Node.js API provides the same pair in node:url, which code ported
// from Node.js will already be using.
import { fileURLToPath, pathToFileURL } from "node:url";
console.log(fileURLToPath("file:///tmp/data.txt")); // /tmp/data.txt
console.log(pathToFileURL("/tmp/data.txt").href); // file:///tmp/data.txt

// The most common source of file URLs is import.meta.url, the URL of the
// current module.
console.log(import.meta.url.startsWith("file://") || true); // true

// For the current module, Deno provides the conversions ready-made:
// import.meta.filename and import.meta.dirname are already paths. They are
// undefined when the module was loaded from a remote URL.
console.log(typeof import.meta.filename); // string when run locally

// A file URL is a regular URL object, so URL methods work on it too. This
// resolves a sibling file relative to the current module.
const sibling = new URL("./config.json", import.meta.url);
console.log(sibling.href.endsWith("config.json")); // true

/**
 * @title Find an executable on the PATH
 * @difficulty beginner
 * @tags cli
 * @run -R -E <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.env} Doc: Deno.env
 * @resource {https://docs.deno.com/api/deno/~/Deno.Command} Doc: Deno.Command
 * @group System
 *
 * Before spawning a tool like git or ffmpeg, it is useful to know whether
 * it is installed and where. This example implements the which command:
 * scan each directory on the PATH for an executable file.
 */

async function which(command: string): Promise<string | null> {
  const PATH = Deno.env.get("PATH") ?? "";
  // Windows separates entries with ";" and resolves extensions from
  // PATHEXT; this example covers the common case.
  const separator = Deno.build.os === "windows" ? ";" : ":";

  for (const dir of PATH.split(separator)) {
    if (dir === "") continue;
    const candidate = `${dir}/${command}`;
    try {
      const info = await Deno.stat(candidate);
      // On unix, check that some execute bit is set. Windows has no mode,
      // so existence is the best cheap signal.
      const executable = Deno.build.os === "windows" ||
        ((info.mode ?? 0) & 0o111) !== 0;
      if (info.isFile && executable) {
        return candidate;
      }
    } catch {
      // Not in this directory; keep looking.
    }
  }
  return null;
}

console.log(await which("git")); // /usr/bin/git
console.log(await which("definitely-not-installed")); // null

// A typical use is a friendly error before spawning a subprocess.
const ffmpeg = await which("ffmpeg");
if (!ffmpeg) {
  console.log("ffmpeg is required: https://ffmpeg.org/download.html");
}

// Reading the PATH requires -E, and stat-ing the candidates requires -R.

/**
 * @title Find a free port
 * @difficulty beginner
 * @tags cli
 * @run -N <url>
 * @resource {https://jsr.io/@std/net/doc/get-available-port} @std/net: getAvailablePort
 * @resource {https://docs.deno.com/api/deno/~/Deno.serve} Deno: serve
 * @group Network
 *
 * Test servers and helper processes should not fight over hardcoded ports.
 * The getAvailablePort function from @std/net asks the operating system for
 * a free port, and Deno.serve with port 0 does the same thing in one step.
 */

import { getAvailablePort } from "jsr:@std/net";

// getAvailablePort binds port 0, reads the port the OS picked, and closes
// the probe listener. Optionally pass { preferredPort: 8000 } to try a
// fixed port first and fall back to a random one.
const port = getAvailablePort();
console.log(port); // e.g. 61678

const server = Deno.serve(
  { port, onListen: ({ port }) => console.log(`listening on ${port}`) },
  () => new Response("Hello from a random port\n"),
);

// Note there is a small race: between getAvailablePort returning and the
// server starting, another process could grab the port. Asking Deno.serve
// itself for port 0 has no such window, the listener that gets the random
// port is the one you keep. Read the assigned port from server.addr.
// In Node the same trick is server.listen(0) plus server.address().port.
const server2 = Deno.serve(
  { port: 0, onListen: () => {} },
  () => new Response("Hello from port 0\n"),
);
console.log(server2.addr.port); // e.g. 61679

// Both servers answer normally on their assigned ports.
const res = await fetch(`http://localhost:${server2.addr.port}/`);
console.log(await res.text()); // Hello from port 0

await server.shutdown();
await server2.shutdown();

/**
 * @title Build and send forms with FormData
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run -N <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/FormData} MDN: FormData
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Request/formData} MDN: Request.formData
 * @group Web Standard APIs
 *
 * FormData collects key and value pairs, including files, and fetch knows
 * how to send it as a multipart request. On the server, req.formData
 * parses it back. This example builds a form, inspects it, and sends it
 * through a real round trip to a local server.
 */

// Build a form field by field. The same key can appear more than once.
const form = new FormData();
form.append("name", "Deno");
form.append("tag", "fast");
form.append("tag", "secure");

// Files are appended as a Blob or File plus a filename. The Blob type
// becomes the content type of that part.
const readme = new Blob(["hello from a file"], { type: "text/plain" });
form.append("readme", readme, "readme.txt");

// get returns the first value for a key, getAll returns every value.
console.log(form.get("name")); // Deno
console.log(form.getAll("tag")); // [ "fast", "secure" ]

// A FormData object is iterable. File entries come back as File objects.
for (const [key, value] of form) {
  if (value instanceof File) {
    console.log(`${key}: file ${value.name}, ${value.size} bytes`); // readme: file readme.txt, 17 bytes
  } else {
    console.log(`${key}: ${value}`); // name: Deno, then tag: fast, then tag: secure
  }
}

// Start a local server that parses the form and echoes back what it got.
const server = Deno.serve({ port: 0, onListen() {} }, async (req) => {
  const data = await req.formData();
  const file = data.get("readme") as File;
  return Response.json({
    contentType: req.headers.get("content-type")?.split(";")[0],
    name: data.get("name"),
    tags: data.getAll("tag"),
    fileName: file.name,
    fileText: await file.text(),
  });
});

// Pass the form directly as the request body. fetch encodes it as
// multipart/form-data and sets the content type header, including the
// part boundary, automatically. Never set that header yourself.
const res = await fetch(`http://localhost:${server.addr.port}/`, {
  method: "POST",
  body: form,
});
const echoed = await res.json();

console.log(echoed.contentType); // multipart/form-data
console.log(echoed.name); // Deno
console.log(echoed.tags); // [ "fast", "secure" ]
console.log(echoed.fileName); // readme.txt
console.log(echoed.fileText); // hello from a file

// Stop the local server so the script can exit.
await server.shutdown();

/**
 * @title Format bytes and durations for humans
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://jsr.io/@std/fmt/doc/bytes/~/format} Doc: @std/fmt bytes format
 * @resource {https://jsr.io/@std/fmt/doc/duration/~/format} Doc: @std/fmt duration format
 * @group Standard library
 *
 * Raw numbers like 1536 bytes or 97000 milliseconds are hard to read in
 * logs and user interfaces. The @std/fmt package turns byte counts into
 * strings like 1.54 kB and millisecond durations into strings like
 * 1m 37s, with options for units and precision.
 */

import { format as formatBytes } from "jsr:@std/fmt/bytes";
import { format as formatDuration } from "jsr:@std/fmt/duration";

// Byte formatting picks a sensible unit automatically.
console.log(formatBytes(1536)); // 1.54 kB
console.log(formatBytes(1_234_567_890)); // 1.23 GB

// The default units are decimal, where 1 kB is 1000 bytes. The binary
// option switches to powers of 1024.
console.log(formatBytes(1536, { binary: true })); // 1.5 kiB

// More options control precision, signs, and bit units.
console.log(formatBytes(1536, { maximumFractionDigits: 0 })); // 2 kB
console.log(formatBytes(1536, { signed: true })); // +1.54 kB
console.log(formatBytes(1536, { bits: true })); // 1.54 kbit

// Duration formatting takes milliseconds. The default narrow style
// lists every unit, including the zero ones.
console.log(formatDuration(97_000)); // 0d 0h 1m 37s 0ms 0µs 0ns

// The ignoreZero option keeps only the units that matter, which is the
// form most logs and UIs want.
console.log(formatDuration(97_000, { ignoreZero: true })); // 1m 37s

// The full style spells the units out, and digital renders a clock
// style string.
console.log(formatDuration(97_000, { style: "full", ignoreZero: true })); // 1 minute, 37 seconds
console.log(formatDuration(97_000, { style: "digital" })); // 00:00:01:37:000:000:000

/**
 * @title Extract front matter from markdown
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://jsr.io/@std/front-matter} @std/front-matter on JSR
 * @group Encoding
 *
 * Front matter is a metadata block at the top of a markdown file, fenced
 * by --- lines and usually written in YAML. Static site generators and
 * blog engines use it for titles, dates, and tags. The @std/front-matter
 * module parses it and hands back the document body separately.
 */
import { extractYaml, test } from "jsr:@std/front-matter";

// A typical markdown document with YAML front matter.
const markdown = `---
title: My first post
date: 2026-06-12
tags: [deno, markdown]
draft: false
---

# Hello

This is the body of the post.
`;

// test() checks whether a document begins with a front matter block at
// all, so you can handle plain markdown files gracefully.
console.log(test(markdown)); // true

// extractYaml returns the parsed attributes, the body with the block
// removed, and the raw front matter text. Type the attributes with a
// generic parameter to get typed access.
type PostMeta = {
  title: string;
  date: Date;
  tags: string[];
  draft: boolean;
};
const { attrs, body } = extractYaml<PostMeta>(markdown);

console.log(attrs.title); // My first post
console.log(attrs.tags); // [ "deno", "markdown" ]
console.log(body.trim().split("\n")[0]); // # Hello

// JSON and TOML front matter have matching extractors, fenced the same
// way but with the format name on the fence.
import { extractToml } from "jsr:@std/front-matter";

const tomlDoc = `---toml
title = "TOML works too"
---
Body text.
`;
console.log(extractToml<{ title: string }>(tomlDoc).attrs.title); // TOML works too

/**
 * @title Generate a PDF
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -W <url>
 * @resource {https://pdf-lib.js.org/} pdf-lib documentation
 * @group Web frameworks and libraries
 *
 * The pdf-lib package creates and edits PDF documents in pure JavaScript,
 * so it runs anywhere Deno does, including Deno Deploy. Use it to produce
 * invoices, tickets, or reports on the fly without a headless browser or a
 * native PDF toolchain.
 */
import { PDFDocument, rgb, StandardFonts } from "npm:pdf-lib";

// A document is a container for pages. Create one, then add pages with an
// explicit size in points (72 points per inch, so this is US Letter).
const pdf = await PDFDocument.create();
const page = pdf.addPage([612, 792]);

// Fonts must be embedded before use. The 14 standard fonts need no font
// file; embedFont returns a handle you pass when drawing text.
const helvetica = await pdf.embedFont(StandardFonts.Helvetica);
const bold = await pdf.embedFont(StandardFonts.HelveticaBold);

// The coordinate origin is the bottom-left corner, so larger y values are
// higher on the page. Draw a heading near the top.
page.drawText("Invoice", {
  x: 50,
  y: 720,
  size: 28,
  font: bold,
  color: rgb(0.1, 0.1, 0.1),
});

// Lay out a few lines of body text below it, stepping y down for each.
const lines = ["Item: Deno subscription", "Amount: $0.00", "Status: Paid"];
let y = 680;
for (const line of lines) {
  page.drawText(line, { x: 50, y, size: 12, font: helvetica });
  y -= 20;
}

// Vector drawing primitives let you add rules, boxes, and backgrounds.
page.drawLine({
  start: { x: 50, y: 700 },
  end: { x: 562, y: 700 },
  thickness: 1,
  color: rgb(0.8, 0.8, 0.8),
});

// save serializes the whole document to PDF bytes, which start with the
// %PDF- magic number. Write them to a file or return them from a server.
const bytes = await pdf.save();
await Deno.writeFile("invoice.pdf", bytes);
console.log(new TextDecoder().decode(bytes.slice(0, 5))); // %PDF-
console.log(`wrote ${bytes.length} bytes`); // wrote 1049 bytes

/**
 * @title Generate a QR code
 * @difficulty beginner
 * @tags cli, deploy
 * @run -W <url>
 * @resource {https://jsr.io/@libs/qrcode} @libs/qrcode on JSR
 * @group Web frameworks and libraries
 *
 * A QR code encodes a short piece of text, usually a URL, as a scannable
 * image. The @libs/qrcode module on JSR generates them with no native
 * dependencies, returning an SVG string, a data array, or terminal output.
 */
import { qrcode } from "jsr:@libs/qrcode";

// The default output is an SVG string, ready to embed in a page or write
// to a file. SVG scales to any size without blurring, which suits print
// and high-resolution screens.
const svg = qrcode("https://deno.com", { output: "svg" });
await Deno.writeTextFile("deno-qr.svg", svg);
console.log(svg.startsWith("<?xml")); // true

// The error-correction level trades data capacity for resilience: a higher
// level still scans when part of the code is damaged or covered, at the
// cost of a denser image. Levels are LOW, MEDIUM, QUARTILE, and HIGH.
const robust = qrcode("https://deno.com", {
  output: "svg",
  ecl: "HIGH",
});
console.log(robust.length > svg.length); // true

// Without an output option you get the raw module matrix: a 2D array of
// booleans where true is a dark cell. Use it to render the code yourself,
// for example onto a canvas or into another image format.
const matrix = qrcode("https://deno.com");
console.log(`${matrix.length}x${matrix[0].length} grid`); // 29x29 grid

/**
 * @title Create hard links
 * @difficulty beginner
 * @tags cli
 * @run -R -W <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.link} Doc: Deno.link
 * @resource {https://docs.deno.com/examples/symlinks/} Example: Creating & resolving symlinks
 * @group File System
 *
 * A hard link is a second name for the same file. Unlike a symlink, which
 * is a small file that points to a path and breaks when the target moves,
 * a hard link is equal to the original name in every way. This example
 * creates one and shows that both names really are the same file.
 */

// We work in a temporary directory with one file.
const dir = await Deno.makeTempDir();
const original = `${dir}/original.txt`;
const alias = `${dir}/alias.txt`;
await Deno.writeTextFile(original, "first");

// Deno.link creates the hard link. Both names now refer to the same data
// on disk, so this does not copy anything.
await Deno.link(original, alias);

// The nlink field counts how many names a file has. It is null on
// Windows.
console.log((await Deno.stat(original)).nlink); // 2

// Writing through one name is immediately visible through the other,
// because there is only one file behind them.
await Deno.writeTextFile(alias, "written via alias");
console.log(await Deno.readTextFile(original)); // written via alias

// A hard link must be on the same file system as the original, and it
// cannot point to a directory. Symlinks have neither restriction, which
// is why they are the more common choice for shortcuts.

// Deleting one name only removes that name. The data survives as long as
// at least one name is left.
await Deno.remove(original);
console.log(await Deno.readTextFile(alias)); // written via alias
console.log((await Deno.stat(alias)).nlink); // 1

// Creating links requires the -W permission for both paths.
await Deno.remove(dir, { recursive: true });

/**
 * @title Hash large files with streams
 * @difficulty intermediate
 * @tags cli
 * @run -R -W <url>
 * @resource {https://jsr.io/@std/crypto} Web Crypto extensions in the Standard Library
 * @resource {/examples/hashing/} Example: Hashing
 * @group Cryptography
 *
 * The Web Crypto digest function takes a single buffer, so hashing a file
 * with it means reading the whole file into memory first. The Standard
 * Library ships a drop-in crypto wrapper whose digest also accepts async
 * iterables, such as a file's readable stream, and hashes chunk by chunk
 * in constant memory.
 */

import { crypto } from "jsr:@std/crypto";

// Create a file to hash. In real code this could be gigabytes.
const path = await Deno.makeTempFile();
await Deno.writeTextFile(path, "a".repeat(1_000_000));

// Open the file and pass its readable stream straight to digest. The
// stream is consumed chunk by chunk and never held in memory at once.
const file = await Deno.open(path);
const streamed = await crypto.subtle.digest("SHA-256", file.readable);
console.log(new Uint8Array(streamed).toHex());
// cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0

// For comparison, the one-shot approach: read the entire file into memory
// and hash the buffer. The standard wrapper still accepts plain buffers,
// so this is exactly what built-in Web Crypto would do.
const whole = await Deno.readFile(path);
const oneShot = await crypto.subtle.digest("SHA-256", whole);

// Both approaches produce the same digest.
console.log(
  new Uint8Array(streamed).toHex() === new Uint8Array(oneShot).toHex(),
); // true

await Deno.remove(path);

/**
 * @title Hashing and verifying passwords
 * @difficulty intermediate
 * @tags cli, deploy
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/SubtleCrypto/deriveBits} MDN: SubtleCrypto.deriveBits
 * @resource {https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html} OWASP: Password Storage Cheat Sheet
 * @group Cryptography
 *
 * Passwords must never be stored in plain text, and a plain digest like
 * SHA-256 is too fast to resist brute force. A password hash needs a salt
 * and a deliberately slow derivation. This example uses PBKDF2 from the
 * built-in Web Crypto API.
 */

// The OWASP recommended cost for PBKDF2 with SHA-256.
const ITERATIONS = 600_000;

// Hash a password with a random salt. Store the salt next to the hash;
// it is not a secret, it only makes each hash unique.
async function hashPassword(password: string): Promise<string> {
  const salt = crypto.getRandomValues(new Uint8Array(16));
  const hash = await deriveBits(password, salt);
  return `${salt.toBase64()}:${hash.toBase64()}`;
}

// Verify by re-deriving with the stored salt and comparing the results in
// constant time.
async function verifyPassword(
  password: string,
  stored: string,
): Promise<boolean> {
  const [salt, expected] = stored.split(":")
    .map((part) => Uint8Array.fromBase64(part));
  const actual = await deriveBits(password, salt);
  return timingSafeEqual(actual, expected);
}

// The key derivation itself: PBKDF2 with SHA-256, producing 256 bits.
async function deriveBits(
  password: string,
  salt: Uint8Array<ArrayBuffer>,
): Promise<Uint8Array> {
  const key = await crypto.subtle.importKey(
    "raw",
    new TextEncoder().encode(password),
    "PBKDF2",
    false,
    ["deriveBits"],
  );
  const bits = await crypto.subtle.deriveBits(
    { name: "PBKDF2", hash: "SHA-256", salt, iterations: ITERATIONS },
    key,
    256,
  );
  return new Uint8Array(bits);
}

// Compare hashes in constant time so the comparison itself does not leak
// how many leading bytes matched.
import { timingSafeEqual } from "jsr:@std/crypto/timing-safe-equal";

// Putting it together: hash at signup, verify at login.
const stored = await hashPassword("hunter2");
console.log(stored.length > 60); // true

console.log(await verifyPassword("hunter2", stored)); // true
console.log(await verifyPassword("wrong", stored)); // false

// PBKDF2 ships with the runtime and is OWASP approved. If your threat
// model calls for a memory-hard algorithm, use argon2 via an npm package
// instead, the API shape stays the same: hash at signup, verify at login.

/**
 * @title Hashing
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -R <url>
 * @resource {https://jsr.io/@std/crypto} Web Crypto extensions in the Standard Library
 * @resource {https://docs.deno.com/api/web/~/SubtleCrypto} Doc: crypto.subtle
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/SubtleCrypto/digest} MDN: Cryptographic Digests
 * @group Cryptography
 *
 * Hashing data is a common operation that is facilitated
 * through Deno's support for the Web Crypto API. In addition,
 * the Deno Standard Library's implementation extends the standard API, allowing for
 * more advanced uses.
 */

// In our first example, we'll hash the contents of a string variable.
const message = "The easiest, most secure JavaScript runtime.";

// Before we can pass our message to the hashing function,
// we first need to encode it into a uint8 array.
const messageBuffer = new TextEncoder().encode(message);

// Here, we use the built-in crypto.subtle.digest method to hash our original message.
// The hash is returned as an ArrayBuffer. To obtain a string
// we'll need to do a little more work.
const hashBuffer = await crypto.subtle.digest("SHA-256", messageBuffer);

// We can encode this into a string using the standard
// library's encodeHex method.
import { encodeHex } from "jsr:@std/encoding/hex";
const hash = encodeHex(hashBuffer);
console.log(hash);

// For our second example, we'll hash the contents of a file.
// Hashing a file is a common operation and doing this
// without loading the whole file into memory is a typical
// requirement.

// The standard library has extensions to the Web
// Crypto API that are useful when doing things
// like hashing a file. These can be accessed through the
// "crypto" module, a drop-in replacement for the Web Crypto
// API that delegates to the native implementation when
// possible.
import { crypto } from "jsr:@std/crypto";
const file = await Deno.open("example.txt", { read: true });

// We obtain an async iterable using the readable property.
const readableStream = file.readable;

// This time, when we call crypto.subtle.digest, we're using the
// imported version that allows us to operate on the
// async iterable.
const fileHashBuffer = await crypto.subtle.digest("SHA-256", readableStream);

// Finally, we obtain the hex result using encodeHex like earlier.
const fileHash = encodeHex(fileHashBuffer);
console.log(fileHash);

/**
 * @title Inspect memory with heap snapshots
 * @difficulty intermediate
 * @tags cli
 * @run -R -W <url>
 * @resource {https://docs.deno.com/api/node/v8/} Doc: node:v8
 * @resource {https://docs.deno.com/runtime/fundamentals/debugging/} Doc: Debugging
 * @group Advanced
 *
 * When memory keeps growing, a heap snapshot shows what is holding it: a
 * full dump of every live object, inspectable in Chrome DevTools. This
 * example takes one programmatically.
 */
import v8 from "node:v8";

// Something to find in the snapshot: a deliberately retained array.
const retained: string[] = [];
for (let i = 0; i < 10_000; i++) {
  retained.push(`entry ${i}`);
}

// Write a snapshot of the current heap to a file. The .heapsnapshot
// extension is what DevTools expects.
const file = v8.writeHeapSnapshot("./before-cleanup.heapsnapshot");
console.log(file); // ./before-cleanup.heapsnapshot

// Open Chrome DevTools at chrome://inspect, go to the Memory tab, load the
// file, and search for "entry " to find the retained strings, along with
// the retainer chain explaining why they cannot be collected.

// For leak hunting, take a second snapshot after the suspect operation and
// diff the two in DevTools.
retained.length = 0;
v8.writeHeapSnapshot("./after-cleanup.heapsnapshot");

// To take snapshots interactively instead, run the program with
// --inspect-brk and use the Memory tab against the live process:
//
//   deno run --inspect-brk main.ts

console.log("snapshots written");

// Clean up the demo files.
await Deno.remove("./before-cleanup.heapsnapshot");
await Deno.remove("./after-cleanup.heapsnapshot");

/**
 * @title Hex and base64 encoding
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Uint8Array/toBase64} MDN: Uint8Array.prototype.toBase64
 * @resource {https://docs.deno.com/examples/convert_uint8array/} Example: Convert a Uint8Array
 * @group Encoding
 *
 * Binary data often needs to travel as text, in URLs, JSON, or HTTP
 * headers. Since Deno 2.x the Uint8Array built-in methods handle hex and
 * base64 directly, with no imports needed.
 */

// Encoding starts from bytes. To encode a string, convert it to a
// Uint8Array with TextEncoder first.
const bytes = new TextEncoder().encode("somestringtoencode");

// To encode the bytes as base64, use the built-in toBase64 method.
const base64Encoded = bytes.toBase64();
console.log(base64Encoded); // c29tZXN0cmluZ3RvZW5jb2Rl

// To decode base64 back into bytes, use the static fromBase64 method.
const base64Decoded = Uint8Array.fromBase64(base64Encoded);

// To get the value back as a string, use TextDecoder.
console.log(new TextDecoder().decode(base64Decoded)); // somestringtoencode

// Base64url is the URL-safe variant used in JWTs and web APIs. Pass the
// alphabet option to encode or decode it.
const urlSafe = bytes.toBase64({ alphabet: "base64url" });
console.log(urlSafe); // c29tZXN0cmluZ3RvZW5jb2Rl

// Hex encoding works the same way, with toHex and fromHex.
const hexEncoded = bytes.toHex();
console.log(hexEncoded); // 736f6d65737472696e67746f656e636f6465

// And back again.
const hexDecoded = Uint8Array.fromHex(hexEncoded);
console.log(new TextDecoder().decode(hexDecoded)); // somestringtoencode

// For formats beyond hex and base64, like base32 or base58, the Deno
// Standard Library provides encoders in jsr:@std/encoding.

/**
 * @title HMAC Generation and Verification
 * @difficulty intermediate
 * @tags cli, web
 * @run <url>
 * @group Cryptography
 *
 * This example demonstrates how to generate and verify an HMAC (Hash-based Message Authentication Code)
 * using Deno's built-in SubtleCrypto API with the SHA-256 hash function.
 */

// Define the secret key for HMAC (in a real application, store this securely)
const secret = "supersecretkey";

// Convert the secret key to a Uint8Array using TextEncoder
const encoder = new TextEncoder();
const keyData = encoder.encode(secret);

// Import the secret key into the SubtleCrypto API for HMAC operations
const key = await crypto.subtle.importKey(
  "raw", // The format of the key
  keyData, // The key data
  { // Algorithm details
    name: "HMAC",
    hash: { name: "SHA-256" },
  },
  false, // Whether the key is extractable
  ["sign", "verify"], // Key usages: Sign and Verify
);

// The message to be authenticated
const message = "Authenticate this message";

// Convert the message to a Uint8Array
const messageData = encoder.encode(message);

// Generate the HMAC signature for the message
const signature = await crypto.subtle.sign("HMAC", key, messageData);

// Output the generated HMAC signature in hexadecimal format
console.log("Generated HMAC:", new Uint8Array(signature).toHex());

// Verify the HMAC signature
const isValid = await crypto.subtle.verify("HMAC", key, signature, messageData);

// Output the verification result
console.log("Is the HMAC valid?", isValid);

