/**
 * @title Protect routes with JWT in Hono
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -E <url>
 * @resource {https://hono.dev/docs/middleware/builtin/jwt} Hono JWT middleware
 * @resource {https://www.npmjs.com/package/hono} hono on npm
 * @group Network
 *
 * A common auth pattern is issuing a JSON Web Token at login and requiring it
 * on protected routes. Hono ships a JWT helper to sign tokens and middleware
 * to verify them, attaching the decoded payload to the request. Set JWT_SECRET
 * before running.
 */

import { Hono } from "npm:hono";
import { jwt, sign } from "npm:hono/jwt";

const secret = Deno.env.get("JWT_SECRET") ?? "dev-secret-change-me";
const app = new Hono();

// Issue a token. In a real app you would verify the user's credentials first,
// then put their id and roles in the payload.
app.post("/login", async (c) => {
  const token = await sign({ sub: "user-123", role: "admin" }, secret);
  return c.json({ token });
});

// The jwt middleware rejects requests without a valid Bearer token and, when
// valid, stores the decoded payload for handlers to read.
app.use("/api/*", jwt({ secret, alg: "HS256" }));

app.get("/api/me", (c) => {
  const payload = c.get("jwtPayload");
  return c.json({ payload });
});

// Try it:
//   curl -XPOST localhost:8000/login           -> { "token": "..." }
//   curl localhost:8000/api/me -H "Authorization: Bearer <token>"
Deno.serve(app.fetch);

/**
 * @title Proxy HTTP requests
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Request} MDN: Request
 * @resource {/examples/http_server} Example: HTTP Server: Hello world
 * @group Network
 *
 * A reverse proxy receives requests and forwards them to another server.
 * Because fetch, Request, and Response are the same objects on both sides,
 * a proxy in Deno is a few lines: rewrite the URL, forward, return.
 */

// The server we forward every request to.
const UPSTREAM = "https://example.com";

async function handler(req: Request): Promise<Response> {
  // Build the upstream URL from the incoming request's path and query.
  const url = new URL(req.url);
  const target = new URL(url.pathname + url.search, UPSTREAM);

  // Forward the method, headers, and body as they came in. The host header
  // must match the upstream, so let fetch regenerate it.
  const headers = new Headers(req.headers);
  headers.delete("host");

  const response = await fetch(target, {
    method: req.method,
    headers,
    body: req.body,
    redirect: "manual",
  });

  // Responses stream straight through; nothing is buffered in memory.
  return response;
}

Deno.serve(handler);

// Requests to the proxy now answer with the upstream's content:
//
//   curl -s http://localhost:8000/ | head -c 15
//   <!doctype html>

// A real deployment usually adds forwarding headers so the upstream knows
// the original client, e.g. headers.set("x-forwarded-for", clientIp) using
// the info argument of the handler.

// The same proxy works on a node:http server; fetch bridges to the web
// Response, whose body is then streamed out through the Node response.
import { createServer } from "node:http";

createServer(async (req, res) => {
  const target = new URL(req.url ?? "/", UPSTREAM);
  const response = await fetch(target);
  res.writeHead(
    response.status,
    Object.fromEntries(response.headers.entries()),
  );
  for await (const chunk of response.body ?? []) {
    res.write(chunk);
  }
  res.end();
}).listen(8001);

/**
 * @title HTTP requests
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run -N <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API} MDN: Fetch API
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/ReadableStream} MDN: ReadableStream
 * @group Network
 *
 * This example demonstrates how to make an HTTP request to a server.
 */

// To make a request to a server, you use the `fetch` API.
let resp = await fetch("https://example.com");

// The response is a `Response` object. This contains the status code, headers,
// and the body.
console.log(resp.status); // 200
console.log(resp.headers.get("Content-Type")); // "text/html"
console.log(await resp.text()); // "Hello, World!"

// The response body can also be read as JSON, an ArrayBuffer, or a Blob. A body
// can be read only once.
resp = await fetch("https://example.com");
await resp.arrayBuffer();
/** or await resp.json(); */
/** or await resp.blob(); */

// The response body can also be streamed in chunks.
resp = await fetch("https://example.com");
for await (const chunk of resp.body!) {
  console.log("chunk", chunk);
}

// When making a request, you can also specify the method, headers, and a body.
resp = await fetch("https://example.com", {
  method: "POST",
  headers: {
    "Content-Type": "application/json",
    "X-API-Key": "foobar",
  },
  body: JSON.stringify({
    param: "value",
  }),
});

// `fetch` also accepts a `Request` object instead of URL + options.
const req = new Request("https://example.com", {
  method: "DELETE",
});
resp = await fetch(req);

// Instead of a string, the body can also be any typed array, blob, or
// a URLSearchParams object.
const url = "https://example.com";
new Request(url, {
  method: "POST",
  body: new Uint8Array([1, 2, 3]),
});
new Request(url, {
  method: "POST",
  body: new Blob(["Hello, World!"]),
});
new Request(url, {
  method: "POST",
  body: new URLSearchParams({ "foo": "bar" }),
});

// Forms can also be sent with `fetch` by using a `FormData` object as the body.
const formData = new FormData();
formData.append("name", "Deno");
formData.append("file", new Blob(["Hello, World!"]), "hello.txt");
resp = await fetch("https://example.com", {
  method: "POST",
  body: formData,
});

// Fetch also supports streaming the request body.
const bodyStream = new ReadableStream({
  start(controller) {
    controller.enqueue(new TextEncoder().encode("Hello, World!"));
    controller.close();
  },
});
resp = await fetch("https://example.com", {
  method: "POST",
  body: bodyStream,
});

