/**
 * @title HTTP server: Cookies
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://jsr.io/@std/http/doc/cookie} @std/http: cookie
 * @resource {https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Cookies} MDN: Using HTTP cookies
 * @group Network
 *
 * Cookies carry state between requests in the cookie and set-cookie headers.
 * The @std/http/cookie module parses and serializes them with the right
 * attributes. This example sets a session cookie on login, reads it back on
 * later requests, and deletes it on logout.
 */

import { deleteCookie, getCookies, setCookie } from "jsr:@std/http/cookie";

Deno.serve((req) => {
  const url = new URL(req.url);
  // getCookies parses the cookie request header into a plain object.
  const cookies = getCookies(req.headers);

  if (url.pathname === "/login") {
    const headers = new Headers({ "content-type": "text/plain" });
    // setCookie appends a set-cookie header. httpOnly hides the cookie from
    // document.cookie, secure restricts it to HTTPS, and sameSite Lax keeps
    // it off cross-site subrequests. Use all three for session cookies.
    setCookie(headers, {
      name: "session",
      value: crypto.randomUUID(),
      httpOnly: true,
      secure: true,
      sameSite: "Lax",
      maxAge: 3600,
      path: "/",
    });
    return new Response("Logged in\n", { headers });
  }

  if (url.pathname === "/logout") {
    const headers = new Headers({ "content-type": "text/plain" });
    // deleteCookie sets the same cookie with an expiry in the past. The
    // path and domain must match the values used when it was set.
    deleteCookie(headers, "session", { path: "/" });
    return new Response("Logged out\n", { headers });
  }

  if (cookies.session) {
    return new Response(`Welcome back, session ${cookies.session}\n`);
  }
  return new Response("No session yet. Visit /login first.\n");
});

// Log in and inspect the set-cookie header:
//
//   curl -i http://localhost:8000/login
//
//   HTTP/1.1 200 OK
//   content-type: text/plain
//   set-cookie: session=b46ba9d6-6f07-435d-a681-67a0fdf240f1; Secure; HttpOnly; Max-Age=3600; SameSite=Lax; Path=/
//   content-length: 10
//   date: Thu, 11 Jun 2026 18:54:45 GMT
//
//   Logged in
//
// Send the cookie back on the next request:
//
//   curl http://localhost:8000/ -H "cookie: session=b46ba9d6-6f07-435d-a681-67a0fdf240f1"
//   Welcome back, session b46ba9d6-6f07-435d-a681-67a0fdf240f1
//
// Logging out overwrites the cookie with one that expires immediately:
//
//   curl -i http://localhost:8000/logout
//
//   HTTP/1.1 200 OK
//   content-type: text/plain
//   set-cookie: session=; Path=/; Expires=Thu, 01 Jan 1970 00:00:00 GMT
//   content-length: 11
//   date: Thu, 11 Jun 2026 18:54:45 GMT
//
//   Logged out

/**
 * @title HTTP server: CORS
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/CORS} MDN: Cross-Origin Resource Sharing
 * @resource {/examples/http_server} Example: HTTP server: Hello World
 * @group Network
 *
 * Browsers block cross-origin requests unless the server opts in with CORS
 * headers. This example answers OPTIONS preflight requests and sets the
 * allow-origin header on actual responses, echoing back origins from a
 * configured allowlist instead of using a wildcard.
 */

// The origins allowed to call this API. Echoing one of these back is safer
// than a wildcard: responses to credentialed requests (cookies, client
// certificates, authorization headers) must name a concrete origin, the
// browser rejects * in that mode.
const allowedOrigins = new Set([
  "http://localhost:5173",
  "https://app.example.com",
]);

function corsHeaders(req: Request): Headers {
  const headers = new Headers();
  const origin = req.headers.get("origin");
  if (origin && allowedOrigins.has(origin)) {
    headers.set("access-control-allow-origin", origin);
    // The response now differs per origin, so shared caches must key on it.
    headers.set("vary", "origin");
  }
  return headers;
}

Deno.serve((req) => {
  const headers = corsHeaders(req);

  // Before non-simple requests (methods like PUT, or custom headers) the
  // browser sends an OPTIONS preflight. Answer with the methods and headers
  // we accept. max-age lets the browser cache the verdict for a day.
  if (req.method === "OPTIONS") {
    headers.set("access-control-allow-methods", "GET, POST, PUT, DELETE");
    headers.set("access-control-allow-headers", "content-type, authorization");
    headers.set("access-control-max-age", "86400");
    return new Response(null, { status: 204, headers });
  }

  // Actual responses only need the allow-origin header (plus
  // access-control-expose-headers if the page should read custom headers).
  headers.set("content-type", "application/json");
  return new Response(JSON.stringify({ message: "Hello, CORS" }), { headers });
});

// Simulate a preflight from an allowed origin with curl:
//
//   curl -i -X OPTIONS http://localhost:8000/ \
//     -H "origin: http://localhost:5173" \
//     -H "access-control-request-method: PUT"
//
//   HTTP/1.1 204 No Content
//   access-control-allow-headers: content-type, authorization
//   access-control-allow-methods: GET, POST, PUT, DELETE
//   access-control-allow-origin: http://localhost:5173
//   access-control-max-age: 86400
//   vary: origin
//   date: Thu, 11 Jun 2026 18:54:35 GMT
//
// A request from an origin that is not on the allowlist gets no CORS
// headers back, so the browser blocks the page from reading the response.

/**
 * @title HTTP server: File upload
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://usefresh.dev/docs/advanced/forms#handling-file-uploads} Handling File Uploads in Fresh
 * @resource {/examples/writing_files} Writing files
 * @resource {/examples/http_server_routing} Example: HTTP server: Server routing
 * @group Network
 *
 * An example HTTP server that provides sending and receiving of a file upload.<br><br>
 * <strong>This example is overly simplified and for demonstration purposes only:</strong><br>
 * In the "real world" forms should be validated (especially file type) and
 *  protect against cross-site request forgery.
 */

import { unescape } from "jsr:@std/html/entities";

// Set up an async function to use with Deno.serve().
async function handler(req: Request) {
  // Get the method from the incoming Request. The default is a GET request.
  const method: string = req.method;

  // Respond to a POST request which we receive if the form we create below is submitted.
  if (method === "POST") {
    // Get the file from the submitted FormData.
    const formData: FormData = await req.formData();
    const file: File | null = formData?.get("file") as File;
    // If we did not receive a file respond with a 400 status code and a message to explain.
    if (!file) {
      return new Response("File required but not provided.", { status: 400 });
    }

    // Here you would do more with the received file, in this example we're
    //  responding with the filename and the raw file byte code.
    return new Response(
      `File name: ${file.name} \n File content: ${await file.bytes()}`,
    );
  }

  // For all other requests other than POST (e.g. GET), let's create an HTML form element
  //  with an encType of 'multipart/form-data' and an input field for the user to select a
  // file from their computer.
  const inputForm = `
    &#x3C;form method=&#x22;POST&#x22; enctype=&#x22;multipart/form-data&#x22;&#x3E;
      &#x3C;input name=&#x22;file&#x22; type=&#x22;file&#x22; /&#x3E;
      &#x3C;button type=&#x22;submit&#x22;&#x3E;Upload&#x3C;/button&#x3E;
    &#x3C;/form&#x3E;
  `;

  // We need to specify the 'text/html' Content-Type to actually render the HTML form, this would normally be handled by a web framework, this example is designed to show the simplest way to handle a file upload over HTTP with Deno.
  const responseOptions: RequestInit = {
    headers: {
      "Content-Type": "text/html",
    },
  };
  // Note: We are only using unescape() here because our HTML string has been encoded for
  //  display in the documentation.
  return new Response(unescape(inputForm), responseOptions);
}

// Lastly we pass the handler we created to Deno.serve().
Deno.serve(handler);

/**
 * @title HTTP server: Serving files
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -R <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.serve} Doc: Deno.serve
 * @resource {https://jsr.io/@std/http#file-server} Doc: @std/http/file-server
 * @resource {/examples/http_server} Example: HTTP Server: Hello World
 * @group Network
 *
 * An example of an HTTP server that serves files.
 */

// Import utility methods for serving files with mime types.
import { serveDir, serveFile } from "jsr:@std/http/file-server";

// Here we start a simple server
Deno.serve((req: Request) => {
  // Get the path from the url (ie. example.com/whatever -> /whatever)
  const pathname = new URL(req.url).pathname;

  if (pathname === "/simple_file") {
    // In the most basic case we can just call this function with the
    // request object and path to the file
    return serveFile(req, "./path/to/file.txt");
  }

  if (pathname.startsWith("/static")) {
    // We can also serve a whole directory using the serveDir utility
    // method. By default it serves the current directory but this
    // can be changed using the "fsRoot" option. We can use the "urlRoot"
    // option to strip off the start of the url in the case we don't
    // serve the directory at the top level.
    return serveDir(req, {
      fsRoot: "public",
      urlRoot: "static",
    });
  }

  return new Response("404: Not Found", {
    status: 404,
  });
});

/**
 * @title HTTP server: Graceful shutdown
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.HttpServer} Deno: HttpServer
 * @resource {https://docs.deno.com/api/deno/~/Deno.addSignalListener} Deno: addSignalListener
 * @group Network
 *
 * Killing a server mid-request drops connections and loses work. A graceful
 * shutdown stops accepting new connections, lets in-flight requests finish,
 * and only then exits. Deno.serve returns an HttpServer whose shutdown
 * method does exactly that, much like server.close in node:http.
 */

// A deliberately slow endpoint so a request can be in flight during
// shutdown. The root responds immediately.
const server = Deno.serve(async (req) => {
  const url = new URL(req.url);
  if (url.pathname === "/slow") {
    await new Promise((resolve) => setTimeout(resolve, 3000));
    return new Response("Slow work finished\n");
  }
  return new Response("Hello\n");
});

async function shutdown(signal: string) {
  console.log(`${signal} received, draining connections...`);

  // Safety net: if draining hangs (a stuck client, an endless stream),
  // exit anyway after a deadline.
  const hardExit = setTimeout(() => {
    console.error("Drain timed out, exiting now");
    Deno.exit(1);
  }, 10_000);

  // shutdown() stops the listener so no new connections are accepted, then
  // resolves once every in-flight request has completed.
  await server.shutdown();

  // Clear the timer and remove the signal listeners. Both keep the event
  // loop alive, so the process exits on its own once they are gone.
  clearTimeout(hardExit);
  Deno.removeSignalListener("SIGINT", onSigint);
  Deno.removeSignalListener("SIGTERM", onSigterm);
  console.log("All requests drained, bye");
}

const onSigint = () => shutdown("SIGINT");
const onSigterm = () => shutdown("SIGTERM");

// SIGINT is what Ctrl+C sends, SIGTERM is what process managers, docker
// stop, and Kubernetes send first. Note that SIGTERM listeners are not
// supported on Windows.
Deno.addSignalListener("SIGINT", onSigint);
if (Deno.build.os !== "windows") {
  Deno.addSignalListener("SIGTERM", onSigterm);
}

// Start a slow request, then send SIGTERM while it is still running:
//
//   curl http://localhost:8000/slow &
//   kill -TERM <server pid>
//
// The server logs:
//
//   SIGTERM received, draining connections...
//   All requests drained, bye
//
// and the curl still prints its full response before the process exits:
//
//   Slow work finished

/**
 * @title HTTP server: Health checks
 * @difficulty beginner
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://kubernetes.io/docs/tasks/configure-pod-container/configure-liveness-readiness-startup-probes/} Kubernetes: Liveness and readiness probes
 * @resource {/examples/http_server} Example: HTTP server: Hello World
 * @group Network
 *
 * Health endpoints let load balancers and orchestrators decide what to do
 * with a process. Liveness answers "is this process alive at all", readiness
 * answers "can it take traffic right now". This server exposes both.
 */

// Readiness depends on the things the server needs to do useful work, such
// as a database pool or a warmed cache. Here a flag flips to true once the
// simulated dependency has started up.
let dbConnected = false;

setTimeout(() => {
  dbConnected = true;
  console.log("Database connected, now ready");
}, 2000);

// In a real service this would issue a cheap query, like SELECT 1.
function pingDb(): Promise<boolean> {
  return Promise.resolve(dbConnected);
}

Deno.serve(async (req) => {
  const url = new URL(req.url);
  // Probes must see the current state, so never let a cache answer them.
  const headers = { "cache-control": "no-store" };

  // Liveness: a 200 whenever the process is serving requests. Orchestrators
  // restart the container when this fails repeatedly, so keep it free of
  // dependency checks. A broken database should not cause a restart loop.
  if (url.pathname === "/healthz") {
    return new Response("ok\n", { status: 200, headers });
  }

  // Readiness: 200 only when dependencies are usable. On failure the
  // orchestrator takes the instance out of load balancing but does not
  // restart it, and puts it back once it reports ready again.
  if (url.pathname === "/readyz") {
    const ready = await pingDb();
    return new Response(ready ? "ready\n" : "database unavailable\n", {
      status: ready ? 200 : 503,
      headers,
    });
  }

  return new Response("Hello\n", { headers });
});

// Right after startup the process is alive but not yet ready:
//
//   curl -i http://localhost:8000/healthz
//
//   HTTP/1.1 200 OK
//   cache-control: no-store
//   content-length: 3
//   date: Thu, 11 Jun 2026 18:55:02 GMT
//
//   ok
//
//   curl -i http://localhost:8000/readyz
//
//   HTTP/1.1 503 Service Unavailable
//   cache-control: no-store
//   content-length: 21
//   date: Thu, 11 Jun 2026 18:55:02 GMT
//
//   database unavailable
//
// Two seconds later the dependency is up and readiness flips:
//
//   curl -i http://localhost:8000/readyz
//
//   HTTP/1.1 200 OK
//   cache-control: no-store
//   content-length: 6
//   date: Thu, 11 Jun 2026 18:55:04 GMT
//
//   ready

/**
 * @title HTTP server: Hot reload
 * @difficulty beginner
 * @tags cli
 * @run -N --watch-hmr <url>
 * @resource {https://docs.deno.com/runtime/run/watch_mode/} Doc: Watch mode
 * @resource {/examples/http_server} Example: HTTP Server: Hello world
 * @group Network
 *
 * Restarting a server by hand after every edit gets old fast. The
 * --watch-hmr flag hot-replaces changed modules inside the running
 * process, so the server keeps serving while you edit.
 */

// Nothing in the code needs to change; this is a plain HTTP server.
function handler(_req: Request): Response {
  return new Response("Hello, World!");
}

Deno.serve(handler);

// Run it with the --watch-hmr flag:
//
//   deno run --watch-hmr -N server.ts
//   HMR Process started.
//   Listening on http://0.0.0.0:8000/
//
// Edit the response text and save. The module is swapped in place, without
// a restart, and the next request already returns the new text:
//
//   HMR Replaced changed module file:///.../server.ts
//
// When a change cannot be hot-replaced, the process restarts
// automatically, so you never serve stale code.

// The plain --watch flag is the simpler variant: it always restarts the
// whole process on every change. Use it when you want a clean slate, for
// example to rerun module-level setup.

// By default every local file the server imports is watched. To watch
// extra paths, like templates or static assets, list them explicitly:
//
//   deno run --watch-hmr=static/ -N server.ts

// The --watch flag also works with deno serve, deno test, and most other
// subcommands.

/**
 * @title HTTP server: Node.js streams
 * @difficulty intermediate
 * @tags cli
 * @run -N -R <url>
 * @resource {https://docs.deno.com/api/node/http/} Doc: node:http
 * @resource {/examples/convert_node_readable/} Example: Convert a Node.js Readable
 * @group Network
 *
 * Code ported from Node.js often produces Node streams: file streams,
 * database cursors, archive generators. This example serves them, both
 * from a node:http server and from Deno.serve.
 */
import { createServer } from "node:http";
import { Readable } from "node:stream";

// The node:http API works in Deno as-is. Piping a Readable into the
// response streams it to the client.
const nodeServer = createServer((_req, res) => {
  const stream = Readable.from(["Hello ", "from ", "node:http\n"]);
  res.setHeader("content-type", "text/plain");
  stream.pipe(res);
});
nodeServer.listen(8001);

// With Deno.serve, convert the Node stream to a web ReadableStream and use
// it as the Response body. Web streams carry bytes, so the chunks must be
// Uint8Arrays: a stream of strings will stall.
const encoder = new TextEncoder();
Deno.serve({ port: 8000 }, () => {
  const stream = Readable.from(
    ["Hello ", "from ", "Deno.serve\n"].map((s) => encoder.encode(s)),
  );
  return new Response(Readable.toWeb(stream) as ReadableStream, {
    headers: { "content-type": "text/plain" },
  });
});

// Both servers stream their responses chunk by chunk:
//
//   curl http://localhost:8001/
//   Hello from node:http
//
//   curl http://localhost:8000/
//   Hello from Deno.serve

/**
 * @title HTTP server: Performing CRUD operations using SQLite3
 * @difficulty intermediate
 * @tags web, cli, deploy
 * @run -A <url>
 * @resource {https://jsr.io/@oak/oak} Doc: @oak/oak/README.md
 * @resource {https://jsr.io/@db/sqlite} @db/sqlite on JSR
 * @group Network
 *
 * An example of an HTTP server for CRUD routes with oak middleware framework and SQLite3 database. It demonstrates the CRUD (Create, Read, Update and Delete) operations on file-based SQLite Database using HTTP methods (Get, Post, Put, Delete, Options)
 */
import { Application, Router } from "jsr:@oak/oak";
import { Database } from "jsr:@db/sqlite";
// Open a database from in-memory database or file. Here an in-memory database is used for CRUD demonstration.
const peopleDb = new Database(":memory:");
peopleDb.exec(
  "CREATE TABLE IF NOT EXISTS people (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT not null,age INTEGER not null)",
);
const app = new Application();
const router = new Router();
router
  .post("/people", async (ctx) => {
    const { name, age } = await ctx.request.body.json();
    peopleDb.exec("INSERT INTO people (name, age) VALUES (?,?)", name, age);
    const lastInsertRowId = peopleDb.lastInsertRowId; // Get the last inserted row ID
    ctx.response.status = 201;
    ctx.response.body = { id: lastInsertRowId, name, age };
  });
router.get("/people", (ctx) => {
  const users = peopleDb.prepare("SELECT * FROM people").all();
  ctx.response.body = users;
});
router.put("/people/:id", async (ctx) => {
  const { name, age } = await ctx.request.body.json();
  peopleDb.prepare("UPDATE people SET name =?, age=? WHERE id = ?").run(
    name,
    age,
    ctx.params.id,
  );
  ctx.response.body = { message: "person updated successfully as requested" };
});
router.delete("/people/:id", (ctx) => {
  peopleDb.prepare("DELETE FROM people WHERE id = ?").run(ctx.params.id);
  ctx.response.body = "person removed successfully as requested";
});
app.use(router.routes());
app.use(router.allowedMethods());
const PORT = 8369; // Any available port number can be defined here
console.log(
  `Server is running on http://localhost:${PORT} - try GET /people`,
);
await app.listen({ port: PORT });

/**
 * @title HTTP server: Paginating results
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/URLSearchParams} MDN: URLSearchParams
 * @resource {/examples/http_server_routing} Example: HTTP server: Routing
 * @group Network
 *
 * APIs that return lists need pagination so a single response stays small.
 * This server shows the two common schemes over one dataset: offset and
 * limit at /items, and a cursor at /items/cursor. Both return the link to
 * the next page so clients never construct page URLs themselves.
 */

// A stand-in for a database table. Real handlers would run a query with
// the same offset, limit, or cursor values instead.
const items = Array.from({ length: 25 }, (_, i) => ({
  id: i + 1,
  name: `Item ${i + 1}`,
}));

// Clamp client input so a request can never ask for the whole table or
// pass something negative.
function clamp(value: number, min: number, max: number): number {
  if (Number.isNaN(value)) return min;
  return Math.min(max, Math.max(min, value));
}

Deno.serve((req) => {
  const url = new URL(req.url);
  const limit = clamp(Number(url.searchParams.get("limit") ?? "5"), 1, 10);

  // Offset pagination: skip the first N items. Simple, and supports
  // jumping straight to an arbitrary page.
  if (url.pathname === "/items") {
    const offset = clamp(
      Number(url.searchParams.get("offset") ?? "0"),
      0,
      items.length,
    );
    const page = items.slice(offset, offset + limit);

    let next: string | null = null;
    if (offset + limit < items.length) {
      next = `/items?offset=${offset + limit}&limit=${limit}`;
    }
    return Response.json({ items: page, total: items.length, next });
  }

  // Cursor pagination: return items after the last id the client saw.
  // Offsets degrade on large or changing datasets: the database must scan
  // and discard all skipped rows, and an insert or delete between two
  // requests shifts every later row, so pages show duplicates or skip
  // items. A cursor on a stable, ordered column resumes exactly after the
  // last row regardless of what happened before it.
  if (url.pathname === "/items/cursor") {
    const after = Number(url.searchParams.get("after") ?? "0");
    const page = items.filter((item) => item.id > after).slice(0, limit);

    // The cursor is the id of the last item on this page. A null cursor
    // tells the client it has reached the end.
    const last = page.at(-1);
    const nextCursor = last !== undefined && last.id < items.length
      ? last.id
      : null;
    const next = nextCursor === null
      ? null
      : `/items/cursor?after=${nextCursor}&limit=${limit}`;
    return Response.json({ items: page, nextCursor, next });
  }

  return new Response("not found\n", { status: 404 });
});

// Two offset pages, then following a cursor. Oversized limits are clamped
// to 10:
//
//   curl -s "http://localhost:8000/items?limit=2"
//   {"items":[{"id":1,"name":"Item 1"},{"id":2,"name":"Item 2"}],"total":25,"next":"/items?offset=2&limit=2"}
//
//   curl -s "http://localhost:8000/items?offset=2&limit=2"
//   {"items":[{"id":3,"name":"Item 3"},{"id":4,"name":"Item 4"}],"total":25,"next":"/items?offset=4&limit=2"}
//
//   curl -s "http://localhost:8000/items/cursor?after=4&limit=2"
//   {"items":[{"id":5,"name":"Item 5"},{"id":6,"name":"Item 6"}],"nextCursor":6,"next":"/items/cursor?after=6&limit=2"}
//
//   curl -s "http://localhost:8000/items?limit=9999"
//   {"items":[{"id":1,"name":"Item 1"},{"id":2,"name":"Item 2"},{"id":3,"name":"Item 3"},{"id":4,"name":"Item 4"},{"id":5,"name":"Item 5"},{"id":6,"name":"Item 6"},{"id":7,"name":"Item 7"},{"id":8,"name":"Item 8"},{"id":9,"name":"Item 9"},{"id":10,"name":"Item 10"}],"total":25,"next":"/items?offset=10&limit=10"}

/**
 * @title HTTP server: Scaling across CPU cores
 * @difficulty intermediate
 * @tags cli
 * @run deno serve --parallel <url>
 * @resource {https://docs.deno.com/runtime/reference/cli/serve/} Doc: deno serve
 * @resource {/examples/http_server} Example: HTTP Server: Hello world
 * @group Network
 *
 * A single process handles requests on one core. The deno serve subcommand
 * can run a whole pool of workers behind one port with the --parallel
 * flag. The server exports its handler instead of calling Deno.serve.
 */

// With deno serve, the module's default export provides the fetch handler.
// The runtime owns the listening socket, which is what lets it share the
// port between workers.
export default {
  fetch(_req: Request): Response {
    return new Response("Hello, World!");
  },
} satisfies Deno.ServeDefaultExport;

// Start one worker per CPU core:
//
//   deno serve --parallel server.ts
//   deno serve: Listening on http://0.0.0.0:8000/ with 8 threads
//
// Incoming connections are distributed across the workers. Set the
// DENO_JOBS environment variable to control the worker count:
//
//   DENO_JOBS=4 deno serve --parallel server.ts

// Each worker is a separate isolate: module-level state like counters or
// caches is per worker, not shared. Keep shared state in something
// external, like a database or Deno KV.

/**
 * @title HTTP server: Rate limiting
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/HTTP/Status/429} MDN: 429 Too Many Requests
 * @resource {/examples/http_server} Example: HTTP server: Hello world
 * @group Network
 *
 * A rate limiter protects a server from clients that send too many requests.
 * The token bucket algorithm allows short bursts while enforcing a steady
 * average rate. Each client gets a bucket of tokens that refills over time,
 * and every request spends one token. When the bucket is empty the server
 * answers 429 with a retry-after header.
 */

// Each client may average REFILL_RATE requests per second, with bursts of
// up to BURST requests when the bucket is full.
const REFILL_RATE = 1;
const BURST = 5;

interface Bucket {
  tokens: number;
  last: number;
}

// Buckets are keyed by client IP and live in memory.
const buckets = new Map<string, Bucket>();

function take(ip: string): boolean {
  const now = Date.now();
  const bucket = buckets.get(ip) ?? { tokens: BURST, last: now };

  // Refill lazily based on how much time passed since the last request,
  // instead of running a timer per client.
  const elapsed = (now - bucket.last) / 1000;
  bucket.tokens = Math.min(BURST, bucket.tokens + elapsed * REFILL_RATE);
  bucket.last = now;
  buckets.set(ip, bucket);

  if (bucket.tokens < 1) return false;
  bucket.tokens -= 1;
  return true;
}

// Buckets for idle clients are useless after they refill completely, so a
// periodic sweep keeps the Map from growing forever. Deno.unrefTimer marks
// the interval as non-blocking, so the process can still exit normally.
const IDLE_MS = (BURST / REFILL_RATE) * 1000;
const sweeper = setInterval(() => {
  const cutoff = Date.now() - IDLE_MS;
  for (const [ip, bucket] of buckets) {
    if (bucket.last < cutoff) buckets.delete(ip);
  }
}, 30_000);
Deno.unrefTimer(sweeper);

Deno.serve((_req, info) => {
  // The second handler argument carries connection details, including the
  // network address of the client.
  const ip = info.remoteAddr.hostname;

  if (!take(ip)) {
    // retry-after tells well-behaved clients how long to back off. One
    // token takes 1 / REFILL_RATE seconds to appear.
    return new Response("too many requests\n", {
      status: 429,
      headers: { "retry-after": String(Math.ceil(1 / REFILL_RATE)) },
    });
  }

  return new Response("ok\n");
});

// Behind a load balancer the socket address belongs to the proxy, not the
// client. In that case derive the key from a trusted header such as
// x-forwarded-for instead of info.remoteAddr.

// Sending requests faster than the refill rate drains the bucket. The first
// five requests spend the burst capacity, then the server starts refusing:
//
//   for i in $(seq 1 7); do curl -s -o /dev/null -w "%{http_code}\n" http://localhost:8000/; done
//   200
//   200
//   200
//   200
//   200
//   429
//   429

/**
 * @title HTTP server: Routing
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {/examples/http_server} Example: HTTP Server: Hello World
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/URL_Pattern_API} MDN: URL Pattern API
 * @playground https://dash.deno.com/playground/example-routing
 * @group Network
 *
 * An example of an HTTP server that handles requests with different responses
 * based on the incoming URL.
 */

// URL patterns can be used to match request URLs. They can contain named groups
// that can be used to extract parts of the URL, e.g. the book ID.
const BOOK_ROUTE = new URLPattern({ pathname: "/books/:id" });

function handler(req: Request): Response {
  // Match the incoming request against the URL patterns.
  const match = BOOK_ROUTE.exec(req.url);
  // If there is a match, extract the book ID and return a response.
  if (match) {
    const id = match.pathname.groups.id;
    return new Response(`Book ${id}`);
  }

  // If there is no match, return a 404 response.
  return new Response("Not found (try /books/1)", {
    status: 404,
  });
}

// To start the server on the default port, call `Deno.serve` with the handler.
Deno.serve(handler);

/**
 * @title Generate an RSS feed
 * @difficulty beginner
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://www.rssboard.org/rss-specification} RSS 2.0 specification
 * @resource {/examples/http_server} Example: HTTP server: Hello world
 * @group Network
 *
 * An RSS feed is a small XML document that lets readers subscribe to a site.
 * Feeds are simple enough to build with a template string: escape the text
 * fields, format dates in the RFC 822 style the spec requires, and serve the
 * result with the right content type.
 */

const SITE = "https://example.com";

const posts = [
  {
    slug: "tips-tricks",
    title: "Tips & tricks for <template> elements",
    description: "Why & how to use them",
    published: new Date("2026-06-01T10:00:00Z"),
  },
  {
    slug: "hello-world",
    title: "Hello world",
    description: "The first post",
    published: new Date("2026-05-20T08:30:00Z"),
  },
];

// XML has five characters that must not appear raw in text content. The
// ampersand goes first, otherwise it would re-escape the others.
function escapeXml(text: string): string {
  return text
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&apos;");
}

// RSS wants RFC 822 dates, like Mon, 01 Jun 2026 10:00:00 GMT.
// Date.prototype.toUTCString produces exactly that format.
function buildFeed(): string {
  const items = posts.map((post) =>
    `    <item>
      <title>${escapeXml(post.title)}</title>
      <link>${SITE}/blog/${post.slug}</link>
      <guid>${SITE}/blog/${post.slug}</guid>
      <description>${escapeXml(post.description)}</description>
      <pubDate>${post.published.toUTCString()}</pubDate>
    </item>`
  ).join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<rss version="2.0">
  <channel>
    <title>Example blog</title>
    <link>${SITE}/blog</link>
    <description>Posts from the example blog</description>
${items}
  </channel>
</rss>
`;
}

Deno.serve((req) => {
  const { pathname } = new URL(req.url);
  if (pathname === "/feed.xml") {
    // application/rss+xml is the registered media type for RSS. Readers
    // also accept application/xml, but be precise when you can.
    return new Response(buildFeed(), {
      headers: { "content-type": "application/rss+xml; charset=utf-8" },
    });
  }
  return new Response("see /feed.xml\n");
});

// The feed validates as RSS 2.0, with the ampersand and angle brackets in
// the first title escaped:
//
//   curl -s http://localhost:8000/feed.xml | head -n 13
//   <?xml version="1.0" encoding="UTF-8"?>
//   <rss version="2.0">
//     <channel>
//       <title>Example blog</title>
//       <link>https://example.com/blog</link>
//       <description>Posts from the example blog</description>
//       <item>
//         <title>Tips &amp; tricks for &lt;template&gt; elements</title>
//         <link>https://example.com/blog/tips-tricks</link>
//         <guid>https://example.com/blog/tips-tricks</guid>
//         <description>Why &amp; how to use them</description>
//         <pubDate>Mon, 01 Jun 2026 10:00:00 GMT</pubDate>
//       </item>

/**
 * @title Generate sitemap.xml and robots.txt
 * @difficulty beginner
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://www.sitemaps.org/protocol.html} Sitemaps XML format
 * @resource {/examples/http_server_rss} Example: Generate an RSS feed
 * @group Network
 *
 * Search engines discover pages through a sitemap and learn crawling rules
 * from robots.txt. Both files derive from the same route list, so serving
 * them from one handler keeps them in sync as the site grows.
 */

// The sitemap protocol requires absolute URLs in every loc element, so the
// canonical origin has to be part of the data.
const SITE = "https://example.com";

const routes = [
  { path: "/", lastmod: "2026-06-01" },
  { path: "/about", lastmod: "2026-05-12" },
  { path: "/blog", lastmod: "2026-06-10" },
  { path: "/blog/hello-world", lastmod: "2026-05-20" },
];

// A urlset with one url element per route. lastmod uses the W3C date
// format, YYYY-MM-DD is enough.
function sitemap(): string {
  const urls = routes.map((route) =>
    `  <url>
    <loc>${SITE}${route.path}</loc>
    <lastmod>${route.lastmod}</lastmod>
  </url>`
  ).join("\n");

  return `<?xml version="1.0" encoding="UTF-8"?>
<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
${urls}
</urlset>
`;
}

// robots.txt points crawlers at the sitemap. The Sitemap line also needs
// an absolute URL.
const robots = `User-agent: *
Allow: /

Sitemap: ${SITE}/sitemap.xml
`;

Deno.serve((req) => {
  const { pathname } = new URL(req.url);

  if (pathname === "/sitemap.xml") {
    return new Response(sitemap(), {
      headers: { "content-type": "application/xml; charset=utf-8" },
    });
  }

  if (pathname === "/robots.txt") {
    return new Response(robots, {
      headers: { "content-type": "text/plain; charset=utf-8" },
    });
  }

  return new Response("hello\n");
});

// Both files come from the same route list:
//
//   curl -s http://localhost:8000/sitemap.xml | head -n 7
//   <?xml version="1.0" encoding="UTF-8"?>
//   <urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">
//     <url>
//       <loc>https://example.com/</loc>
//       <lastmod>2026-06-01</lastmod>
//     </url>
//     <url>
//
//   curl -s http://localhost:8000/robots.txt
//   User-agent: *
//   Allow: /
//
//   Sitemap: https://example.com/sitemap.xml

/**
 * @title HTTP server: Server-sent events
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Server-sent_events} MDN: Server-sent events
 * @resource {/examples/http_server_streaming} Example: HTTP server: Streaming
 * @group Network
 *
 * Server-sent events push updates from the server to the browser over a
 * single long-lived HTTP response, with automatic reconnection built into
 * the EventSource API. This example sends the time once per second.
 */

// An SSE response is a stream of text blocks. Each event is a line starting
// with data:, followed by a blank line.
function handler(_req: Request): Response {
  let timer: ReturnType<typeof setInterval>;
  const body = new ReadableStream({
    start(controller) {
      timer = setInterval(() => {
        const event = `data: ${new Date().toISOString()}\n\n`;
        controller.enqueue(new TextEncoder().encode(event));
      }, 1000);
    },
    // Stop producing events when the client disconnects.
    cancel() {
      clearInterval(timer);
    },
  });

  // The content type is what makes this server-sent events. Disabling
  // proxy buffering and caching keeps events flowing immediately.
  return new Response(body, {
    headers: {
      "content-type": "text/event-stream",
      "cache-control": "no-store",
    },
  });
}

Deno.serve(handler);

// In the browser, EventSource consumes the stream and reconnects
// automatically if the connection drops:
//
//   const source = new EventSource("http://localhost:8000/");
//   source.onmessage = (event) => console.log(event.data);
//
// From the terminal, curl shows the raw protocol:
//
//   curl http://localhost:8000/
//   data: 2026-06-11T13:37:00.000Z
//
//   data: 2026-06-11T13:37:01.000Z

/**
 * @title HTTP server: Caching headers
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -R <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching} MDN: HTTP caching
 * @resource {https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/ETag} MDN: ETag
 * @group Network
 *
 * Cache headers let clients skip downloads they already have. This server
 * sends cache-control, etag, and last-modified with a file, and answers a
 * matching if-none-match revalidation with 304 Not Modified and no body.
 */

// Serve this script's own source file so the example is self-contained.
const filePath = import.meta.filename!;

Deno.serve(async (req) => {
  const stat = await Deno.stat(filePath);

  // A weak etag (W/ prefix) derived from mtime and size is cheap and good
  // enough for cache validation. Hash the content instead if you need a
  // strong validator, for example to support byte-range resumption.
  const mtime = stat.mtime ?? new Date();
  const etag = `W/"${mtime.getTime().toString(16)}-${stat.size.toString(16)}"`;

  const headers = {
    "etag": etag,
    "last-modified": mtime.toUTCString(),
    // Clients may reuse the file for 60 seconds, then must revalidate.
    "cache-control": "max-age=60, must-revalidate",
    "content-type": "text/plain; charset=utf-8",
  };

  // The client revalidates by echoing the etag in if-none-match. If it
  // still matches, a bodyless 304 tells it to keep using its copy.
  if (req.headers.get("if-none-match") === etag) {
    return new Response(null, { status: 304, headers });
  }

  const file = await Deno.open(filePath, { read: true });
  return new Response(file.readable, { headers });
});

// The first request downloads the file and the validators:
//
//   curl -i http://localhost:8000/
//
//   HTTP/1.1 200 OK
//   etag: W/"19eb80919f8-8bd"
//   last-modified: Thu, 11 Jun 2026 18:54:24 GMT
//   cache-control: max-age=60, must-revalidate
//   content-type: text/plain; charset=utf-8
//   transfer-encoding: chunked
//   date: Thu, 11 Jun 2026 18:54:53 GMT
//
// Revalidating with that etag transfers no body:
//
//   curl -i http://localhost:8000/ -H 'if-none-match: W/"19eb80919f8-8bd"'
//
//   HTTP/1.1 304 Not Modified
//   etag: W/"19eb80919f8-8bd"
//   last-modified: Thu, 11 Jun 2026 18:54:24 GMT
//   cache-control: max-age=60, must-revalidate
//   content-type: text/plain; charset=utf-8
//   date: Thu, 11 Jun 2026 18:54:53 GMT

/**
 * @title HTTP server: TLS
 * @difficulty intermediate
 * @tags cli
 * @run -N -R <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.serve} Doc: Deno.serve
 * @resource {/examples/http_server} Example: HTTP Server: Hello world
 * @group Network
 *
 * Deno.serve speaks HTTPS when given a certificate and private key. This
 * example starts a TLS server with a locally generated certificate.
 */

// For local development, generate a self-signed certificate with openssl:
//
//   openssl req -x509 -newkey rsa:2048 -nodes -days 365
//     -keyout localhost-key.pem -out localhost-cert.pem
//     -subj "/CN=localhost" -addext "subjectAltName=DNS:localhost"
//
// In production, use the certificate files issued by your CA instead.

// Pass the certificate and key as strings; reading them needs the -R
// permission, and serving needs -N.
Deno.serve(
  {
    port: 8443,
    cert: Deno.readTextFileSync("localhost-cert.pem"),
    key: Deno.readTextFileSync("localhost-key.pem"),
  },
  () => new Response("Hello over TLS"),
);

// Test it with curl, telling it to trust the self-signed certificate:
//
//   curl --cacert localhost-cert.pem https://localhost:8443/
//   Hello over TLS

// Code written against the Node.js API works as well: node:https takes the
// same certificate material in its options.
import { createServer } from "node:https";

createServer(
  {
    cert: Deno.readTextFileSync("localhost-cert.pem"),
    key: Deno.readTextFileSync("localhost-key.pem"),
  },
  (_req, res) => res.end("Hello from node:https"),
).listen(8444);

// Browsers will warn about self-signed certificates. A tool like mkcert
// installs a locally trusted authority and removes the warning during
// development.

/**
 * @title HTTP server: Verifying webhook signatures
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://docs.github.com/en/webhooks/using-webhooks/validating-webhook-deliveries} GitHub: Validating webhook deliveries
 * @resource {/examples/hmac_generate_verify} Example: HMAC generation and verification
 * @group Network
 *
 * Webhook senders sign each delivery so receivers can prove the payload
 * came from them and was not tampered with in transit. GitHub, Stripe, and
 * many others use an HMAC of the request body with a shared secret. This
 * server verifies a GitHub style x-hub-signature-256 header before trusting
 * the payload.
 */

// Both sides know this secret. In a real deployment read it from an
// environment variable instead of hardcoding it.
const SECRET = "it-is-a-secret-to-everybody";

// Import the secret once at startup as an HMAC-SHA256 verification key.
const key = await crypto.subtle.importKey(
  "raw",
  new TextEncoder().encode(SECRET),
  { name: "HMAC", hash: "SHA-256" },
  false,
  ["verify"],
);

async function verify(req: Request): Promise<unknown | null> {
  // Read the raw bytes before any JSON parsing. The signature covers the
  // exact bytes that were sent; parsing and re-serializing can change key
  // order and whitespace, which would produce a different HMAC.
  const body = await req.bytes();

  // The header carries the hex digest behind a sha256= prefix.
  const header = req.headers.get("x-hub-signature-256") ?? "";
  if (!header.startsWith("sha256=")) return null;

  let signature: BufferSource;
  try {
    signature = Uint8Array.fromHex(header.slice("sha256=".length));
  } catch {
    return null;
  }

  // crypto.subtle.verify recomputes the HMAC and compares in constant time.
  // Comparing hex strings with === instead would leak how many leading
  // characters matched through response timing.
  const valid = await crypto.subtle.verify("HMAC", key, signature, body);
  if (!valid) return null;

  // Only now is it safe to parse and act on the payload.
  return JSON.parse(new TextDecoder().decode(body));
}

Deno.serve(async (req) => {
  if (req.method !== "POST") {
    return new Response("method not allowed\n", { status: 405 });
  }

  const payload = await verify(req);
  if (payload === null) {
    return new Response("invalid signature\n", { status: 401 });
  }

  console.log("verified webhook:", payload);
  return new Response("ok\n");
});

// A sender computes the same HMAC over the body and puts it in the header.
// The HMAC-SHA256 of {"action":"opened"} under the secret above is
// 04c343e56984578880ead1d6feefa1d581c4336c868f87358b81041f23a1a62a.
// Posting that exact body with that signature succeeds, and any change to
// the body makes the same signature fail:
//
//   curl -s -d '{"action":"opened"}' \
//     -H "x-hub-signature-256: sha256=04c343e56984578880ead1d6feefa1d581c4336c868f87358b81041f23a1a62a" \
//     http://localhost:8000/
//   ok
//
//   curl -s -d '{"action":"deleted"}' \
//     -H "x-hub-signature-256: sha256=04c343e56984578880ead1d6feefa1d581c4336c868f87358b81041f23a1a62a" \
//     http://localhost:8000/
//   invalid signature

/**
 * @title HTTP server: WebSockets
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {/examples/http_server} Example: HTTP Server: Hello World
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/WebSocket} MDN: WebSocket
 * @group Network
 *
 * An example of an HTTP server that handles websocket requests.
 */

// To start the server on the default port, call `Deno.serve` with the handler.
Deno.serve((req) => {
  // First, we verify if the client is negotiating to upgrade to websockets.
  // If not, we can give a status of 426 to specify we don't support plain
  // http requests.
  if (req.headers.get("upgrade") != "websocket") {
    return new Response(null, { status: 426 });
  }

  // We can then upgrade the request to a websocket
  const { socket, response } = Deno.upgradeWebSocket(req);

  // We now have access to a standard websocket object.
  // Let's handle the "open" event
  socket.addEventListener("open", () => {
    console.log("a client connected!");
  });

  // We can also handle messages in a similar way. Here we set up
  // a simple ping / pong example.
  socket.addEventListener("message", (event) => {
    if (event.data === "ping") {
      socket.send("pong");
    }
  });

  // Lastly we return the response created from upgradeWebSocket.
  return response;
});

