/**
 * @title Format dates for any locale
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/DateTimeFormat} MDN: Intl.DateTimeFormat
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/DateTimeFormat/formatRange} MDN: formatRange
 * @group Web Standard APIs
 *
 * Intl.DateTimeFormat turns a Date into text for any locale and time
 * zone. The dateStyle and timeStyle shortcuts cover most needs, and
 * formatRange renders a span of two dates without repeating the shared
 * parts. This example formats one fixed instant in several ways.
 */

// All examples format the same instant, given in UTC.
const date = new Date("2026-06-11T12:00:00Z");

// dateStyle picks a complete date layout for the locale. Passing an
// explicit timeZone makes the output independent of the machine settings.
const fullDate = new Intl.DateTimeFormat("en-US", {
  dateStyle: "full",
  timeZone: "UTC",
});
console.log(fullDate.format(date)); // Thursday, June 11, 2026

// dateStyle and timeStyle combine into a single string.
const dateTime = new Intl.DateTimeFormat("en-US", {
  dateStyle: "medium",
  timeStyle: "short",
  timeZone: "UTC",
});
console.log(dateTime.format(date)); // Jun 11, 2026, 12:00 PM

// Other locales bring their own month names, ordering, and punctuation.
const german = new Intl.DateTimeFormat("de-DE", {
  dateStyle: "full",
  timeZone: "UTC",
});
console.log(german.format(date)); // Donnerstag, 11. Juni 2026

const japanese = new Intl.DateTimeFormat("ja-JP", {
  dateStyle: "long",
  timeZone: "UTC",
});
console.log(japanese.format(date)); // 2026年6月11日

// The timeZone option converts the instant before formatting. The same
// moment is morning in New York and evening in Tokyo.
const newYork = new Intl.DateTimeFormat("en-US", {
  dateStyle: "short",
  timeStyle: "long",
  timeZone: "America/New_York",
});
console.log(newYork.format(date)); // 6/11/26, 8:00:00 AM EDT

const tokyo = new Intl.DateTimeFormat("en-US", {
  dateStyle: "short",
  timeStyle: "long",
  timeZone: "Asia/Tokyo",
});
console.log(tokyo.format(date)); // 6/11/26, 9:00:00 PM GMT+9

// formatRange writes a date range compactly. Shared parts like the month
// and year appear only once.
const range = new Intl.DateTimeFormat("en-US", {
  dateStyle: "medium",
  timeZone: "UTC",
});
const end = new Date("2026-06-15T12:00:00Z");
console.log(range.formatRange(date, end)); // Jun 11 – 15, 2026

// When the range crosses a month boundary, both months are spelled out.
const longRange = new Intl.DateTimeFormat("en-US", {
  month: "long",
  day: "numeric",
  year: "numeric",
  timeZone: "UTC",
});
const nextMonth = new Date("2026-07-02T12:00:00Z");
console.log(longRange.formatRange(date, nextMonth)); // June 11 – July 2, 2026

// Temporal values format through the same machinery: toLocaleString takes
// the same locales and options. An Instant is the Temporal analog of a
// Date.
const instant = Temporal.Instant.from("2026-06-11T12:00:00Z");
console.log(
  instant.toLocaleString("en-US", {
    dateStyle: "medium",
    timeStyle: "short",
    timeZone: "UTC",
  }),
); // Jun 11, 2026, 12:00 PM

// A ZonedDateTime already carries its time zone, so no timeZone option is
// needed (or allowed).
const zoned = instant.toZonedDateTimeISO("Europe/Warsaw");
console.log(zoned.toLocaleString("de-DE", {
  dateStyle: "full",
  timeStyle: "short",
})); // Donnerstag, 11. Juni 2026 um 14:00

/**
 * @title Format numbers and currencies
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/NumberFormat} MDN: Intl.NumberFormat
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/NumberFormat/formatRange} MDN: formatRange
 * @group Web Standard APIs
 *
 * Intl.NumberFormat formats numbers for any locale and style. It handles
 * grouping separators, currency symbols, compact notation, measurement
 * units, and percentages, so you never need to build those strings by
 * hand. This example shows the most common options.
 */

// Plain formatting picks the grouping and decimal separators of the
// locale. English and German disagree on both.
console.log(new Intl.NumberFormat("en-US").format(1234567.891)); // 1,234,567.891
console.log(new Intl.NumberFormat("de-DE").format(1234567.891)); // 1.234.567,891

// The currency style places the symbol and rounds to the right number of
// fraction digits for that currency.
const usd = new Intl.NumberFormat("en-US", {
  style: "currency",
  currency: "USD",
});
console.log(usd.format(1234.5)); // $1,234.50

const eur = new Intl.NumberFormat("de-DE", {
  style: "currency",
  currency: "EUR",
});
console.log(eur.format(1234.5)); // 1.234,50 €

// Compact notation abbreviates large numbers the way headlines do.
const compact = new Intl.NumberFormat("en-US", { notation: "compact" });
console.log(compact.format(1234567)); // 1.2M

// The long compact display spells the magnitude out.
const compactLong = new Intl.NumberFormat("en-US", {
  notation: "compact",
  compactDisplay: "long",
});
console.log(compactLong.format(1234567)); // 1.2 million

// The unit style appends a localized measurement unit.
const speed = new Intl.NumberFormat("en-US", {
  style: "unit",
  unit: "kilometer-per-hour",
});
console.log(speed.format(120)); // 120 km/h

// The long unit display writes the unit in full words.
const speedLong = new Intl.NumberFormat("en-US", {
  style: "unit",
  unit: "kilometer-per-hour",
  unitDisplay: "long",
});
console.log(speedLong.format(120)); // 120 kilometers per hour

// The percent style multiplies by 100 and adds the sign. The default
// rounds to whole percents unless you ask for fraction digits.
const percent = new Intl.NumberFormat("en-US", { style: "percent" });
console.log(percent.format(0.485)); // 49%

const percentExact = new Intl.NumberFormat("en-US", {
  style: "percent",
  minimumFractionDigits: 1,
});
console.log(percentExact.format(0.485)); // 48.5%

// formatRange renders a span of two values with locale aware punctuation.
// Deno supports it on every Intl.NumberFormat instance.
console.log(usd.formatRange(40, 60)); // $40.00 – $60.00
console.log(new Intl.NumberFormat("en-US").formatRange(2.9, 3.1)); // 2.9–3.1

/**
 * @title Pluralize and format lists
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/PluralRules} MDN: Intl.PluralRules
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/ListFormat} MDN: Intl.ListFormat
 * @group Web Standard APIs
 *
 * Hand-rolled pluralization like adding an s breaks as soon as you
 * leave English. Intl.PluralRules tells you which grammatical category a
 * number falls into for a locale, and Intl.ListFormat joins items with
 * the right separators and conjunction. This example shows both.
 */

// English has two plural categories, one and other.
const english = new Intl.PluralRules("en-US");
console.log(english.select(1)); // one
console.log(english.select(2)); // other
console.log(english.select(0)); // other
console.log(english.resolvedOptions().pluralCategories); // [ "one", "other" ]

// Polish has four. Numbers ending in 2 to 4 use few, most others use
// many, and fractions fall back to other.
const polish = new Intl.PluralRules("pl");
console.log(polish.select(1)); // one
console.log(polish.select(2)); // few
console.log(polish.select(5)); // many
console.log(polish.select(22)); // few
console.log(polish.select(1.5)); // other

// Arabic uses all six categories, including zero, one, and two.
const arabic = new Intl.PluralRules("ar");
console.log(arabic.select(0)); // zero
console.log(arabic.select(1)); // one
console.log(arabic.select(2)); // two
console.log(arabic.select(6)); // few
console.log(arabic.select(15)); // many

// A pluralize helper maps each category to a word form. For English you
// only need two forms.
const fileForms: Record<string, string> = { one: "file", other: "files" };

function pluralize(count: number): string {
  return `${count} ${fileForms[english.select(count)]}`;
}

console.log(pluralize(1)); // 1 file
console.log(pluralize(3)); // 3 files
console.log(pluralize(0)); // 0 files

// Intl.ListFormat joins arrays the way prose does. The conjunction type
// produces an and list, including the Oxford comma for en-US.
const and = new Intl.ListFormat("en-US", { type: "conjunction" });
console.log(and.format(["red", "green", "blue"])); // red, green, and blue
console.log(and.format(["red", "green"])); // red and green

// The disjunction type produces an or list.
const or = new Intl.ListFormat("en-US", { type: "disjunction" });
console.log(or.format(["red", "green", "blue"])); // red, green, or blue

// Other locales swap in their own conjunctions and comma rules.
const german = new Intl.ListFormat("de-DE", { type: "conjunction" });
console.log(german.format(["rot", "grün", "blau"])); // rot, grün und blau

/**
 * @title Format relative time
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/RelativeTimeFormat} MDN: Intl.RelativeTimeFormat
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/RelativeTimeFormat/format} MDN: format
 * @group Web Standard APIs
 *
 * Intl.RelativeTimeFormat produces phrases like 3 days ago or in 2
 * months for any locale. You pass a signed number and a unit, and the
 * formatter handles grammar, pluralization, and translation. This
 * example also builds a small helper that picks the right unit from a
 * millisecond difference.
 */

// Negative values describe the past, positive values the future.
const rtf = new Intl.RelativeTimeFormat("en", { numeric: "always" });
console.log(rtf.format(-3, "day")); // 3 days ago
console.log(rtf.format(2, "month")); // in 2 months

// With numeric always, even a single day stays numeric.
console.log(rtf.format(-1, "day")); // 1 day ago
console.log(rtf.format(1, "day")); // in 1 day

// With numeric auto, the formatter prefers idiomatic words when they
// exist for the locale.
const auto = new Intl.RelativeTimeFormat("en", { numeric: "auto" });
console.log(auto.format(-1, "day")); // yesterday
console.log(auto.format(1, "day")); // tomorrow
console.log(auto.format(0, "second")); // now
console.log(auto.format(-1, "week")); // last week

// Other locales come for free.
const spanish = new Intl.RelativeTimeFormat("es", { numeric: "auto" });
console.log(spanish.format(-1, "day")); // ayer
console.log(spanish.format(2, "month")); // dentro de 2 meses

// Real code usually starts from a difference between two timestamps.
// This helper walks from the largest unit down and uses the first unit
// the difference fills at least once.
const units: [Intl.RelativeTimeFormatUnit, number][] = [
  ["year", 365 * 24 * 60 * 60 * 1000],
  ["month", 30 * 24 * 60 * 60 * 1000],
  ["day", 24 * 60 * 60 * 1000],
  ["hour", 60 * 60 * 1000],
  ["minute", 60 * 1000],
  ["second", 1000],
];

function timeAgo(deltaMs: number): string {
  for (const [unit, ms] of units) {
    if (Math.abs(deltaMs) >= ms) {
      return auto.format(Math.round(deltaMs / ms), unit);
    }
  }
  return auto.format(0, "second");
}

// Fixed differences in milliseconds keep the demonstration exact.
console.log(timeAgo(-45 * 1000)); // 45 seconds ago
console.log(timeAgo(-90 * 60 * 1000)); // 1 hour ago
console.log(timeAgo(-26 * 60 * 60 * 1000)); // yesterday
console.log(timeAgo(11 * 24 * 60 * 60 * 1000)); // in 11 days
console.log(timeAgo(70 * 24 * 60 * 60 * 1000)); // in 2 months

// In an application you would compute the difference from the clock,
// for example timeAgo(postDate.getTime() - Date.now()).

// With Temporal, the unit math comes from the calendar instead of fixed
// millisecond constants: since() on zoned values yields a signed duration
// in the unit you ask for, ready to feed the formatter.
const now = Temporal.Instant.from("2026-06-11T12:00:00Z")
  .toZonedDateTimeISO("UTC");
const earlier = Temporal.Instant.from("2026-06-08T12:00:00Z")
  .toZonedDateTimeISO("UTC");
const elapsed = earlier.since(now, { largestUnit: "day" });
console.log(auto.format(elapsed.days, "day")); // 3 days ago

/**
 * @title Split text by words, sentences, and graphemes
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/Segmenter} MDN: Intl.Segmenter
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/Segmenter/segment} MDN: segment
 * @group Web Standard APIs
 *
 * Splitting text with split or slice breaks on punctuation, emoji, and
 * languages that do not use spaces. Intl.Segmenter understands locale
 * rules and can split by word, sentence, or grapheme, which is what a
 * human perceives as one character. This example shows all three
 * granularities and a truncation helper that never cuts an emoji in
 * half.
 */

// Word segmentation yields words and the separators between them. The
// isWordLike flag filters out spaces and punctuation.
const wordSegmenter = new Intl.Segmenter("en", { granularity: "word" });
const text = "Deno ships with web standard APIs. Try Intl.Segmenter!";
const words = [...wordSegmenter.segment(text)]
  .filter((segment) => segment.isWordLike)
  .map((segment) => segment.segment);
console.log(words.join("|")); // Deno|ships|with|web|standard|APIs|Try|Intl|Segmenter
console.log(words.length); // 9

// Word segmentation also works for languages without spaces, where
// split(" ") would return the whole sentence as one chunk.
const japaneseSegmenter = new Intl.Segmenter("ja", { granularity: "word" });
const japaneseWords = [...japaneseSegmenter.segment("デノは安全です")]
  .filter((segment) => segment.isWordLike)
  .map((segment) => segment.segment);
console.log(japaneseWords.join("|")); // デ|ノ|は|安全|です

// Sentence segmentation splits prose into sentences, keeping trailing
// spaces attached.
const sentenceSegmenter = new Intl.Segmenter("en", {
  granularity: "sentence",
});
const prose = "Deno is secure by default. It needs permission flags. Try it!";
const sentences = [...sentenceSegmenter.segment(prose)]
  .map((segment) => segment.segment.trim());
console.log(sentences.length); // 3
console.log(sentences[1]); // It needs permission flags.

// String length counts UTF-16 code units, not characters. A family emoji
// is several emoji joined invisibly, so length and even the spread
// operator report surprising numbers.
const family = "👨‍👩‍👧‍👦";
console.log(family.length); // 11
console.log([...family].length); // 7

// Grapheme segmentation counts what a reader sees, one character.
const graphemeSegmenter = new Intl.Segmenter("en", {
  granularity: "grapheme",
});
console.log([...graphemeSegmenter.segment(family)].length); // 1

// Slicing by index can land inside an emoji. Here slice keeps the wave
// but cuts off its skin tone modifier.
const greeting = "Hi 👋🏽! Welcome 👨‍👩‍👧‍👦";
console.log(greeting.slice(0, 5)); // Hi 👋

// A safe truncation helper slices whole graphemes instead of indexes.
function truncate(input: string, maxGraphemes: number): string {
  const graphemes = [...graphemeSegmenter.segment(input)];
  if (graphemes.length <= maxGraphemes) {
    return input;
  }
  const kept = graphemes.slice(0, maxGraphemes);
  return kept.map((segment) => segment.segment).join("") + "…";
}

console.log(truncate(greeting, 5)); // Hi 👋🏽!…
console.log(truncate("short", 80)); // short

/**
 * @title Stream JSON Lines data
 * @difficulty beginner
 * @tags cli, deploy
 * @run <url>
 * @resource {https://jsr.io/@std/json} Doc: @std/json
 * @resource {https://jsonlines.org} Spec: JSON Lines
 * @group Encoding
 *
 * JSON Lines, also called NDJSON, stores one JSON value per line. Log
 * files, data exports and streaming APIs use it because each line can be
 * processed on its own, without parsing the whole document. The Standard
 * Library provides stream transforms for both directions in jsr:@std/json.
 */
import { JsonParseStream, JsonStringifyStream } from "jsr:@std/json";
import { TextLineStream } from "jsr:@std/streams";

// This is a typical log in JSON Lines format, one JSON object per line.
const ndjson = `{"level":"info","message":"server started"}
{"level":"warn","message":"high memory usage"}
{"level":"error","message":"request failed"}
`;

// To consume it, build a pipeline. TextLineStream splits the text into
// lines and JsonParseStream parses each line into a value. Any readable
// stream of bytes works as a source, such as a file or a response body.
const entries = new Blob([ndjson]).stream()
  .pipeThrough(new TextDecoderStream())
  .pipeThrough(new TextLineStream())
  .pipeThrough(new JsonParseStream());

// Each entry arrives as soon as its line is complete, so a process can
// react to the first record before the last one even exists.
for await (const entry of entries) {
  console.log(entry);
}
//- { level: "info", message: "server started" }
//- { level: "warn", message: "high memory usage" }
//- { level: "error", message: "request failed" }

// To produce JSON Lines, pipe values through a JsonStringifyStream. Every
// chunk it emits is one JSON text followed by a newline character, ready
// to append to a file or send over a socket.
const events = [
  { id: 1, type: "click" },
  { id: 2, type: "scroll" },
];
const lines = ReadableStream.from(events)
  .pipeThrough(new JsonStringifyStream());

// We trim each chunk before logging because console.log adds its own
// newline.
for await (const line of lines) {
  console.log(line.trimEnd());
}
//- {"id":1,"type":"click"}
//- {"id":2,"type":"scroll"}

/**
 * @title Rich output in Jupyter notebooks
 * @difficulty intermediate
 * @tags cli
 * @resource {https://docs.deno.com/api/deno/~/Deno.jupyter} Doc: Deno.jupyter
 * @resource {https://docs.deno.com/runtime/reference/cli/jupyter/} deno jupyter in the manual
 * @group CLI
 *
 * Deno ships a Jupyter kernel, so notebooks can run TypeScript with full
 * access to the Deno and web APIs. Inside a notebook, the Deno.jupyter
 * namespace renders rich output: Markdown, HTML, images, and raw MIME
 * bundles. Install the kernel once with deno jupyter --install, then run
 * these snippets in notebook cells. Deno.jupyter only exists under the
 * deno jupyter subcommand, not in deno run.
 */

// Deno.jupyter.md and Deno.jupyter.html are tagged templates. When their
// result is the last expression of a cell, the notebook renders it as
// Markdown or HTML instead of plain text.
const name = "Deno";
Deno.jupyter.md`## Hello from ${name}
- supports **Markdown**
- and ${1 + 1} other things`;

// HTML works the same way, useful for small inline visualizations without
// pulling in a plotting library.
Deno.jupyter.html`<table>
  <tr><th>lang</th><th>typed</th></tr>
  <tr><td>TypeScript</td><td>yes</td></tr>
</table>`;

// Deno.jupyter.image displays a PNG or JPEG from a file path or from raw
// bytes, handy for images produced by canvas or image libraries.
Deno.jupyter.image("./chart.png");

// Any value can opt in to rich display by implementing the
// Deno.jupyter.$display symbol method and returning a MIME bundle. The
// notebook picks the richest representation it understands.
class Temperature {
  constructor(public celsius: number) {}
  [Deno.jupyter.$display]() {
    return {
      "text/plain": `${this.celsius} C`,
      "text/html": `<strong>${this.celsius} &deg;C</strong>`,
    };
  }
}
new Temperature(21);

// Deno.jupyter.display shows a value explicitly from anywhere in a cell,
// not just the final expression. The raw option treats the object as a
// MIME bundle as-is.
await Deno.jupyter.display({
  "text/markdown": "Progress: **done**",
}, { raw: true });

// Deno.jupyter.broadcast sends low-level Jupyter protocol messages, for
// example to update a display in place while a long computation runs.
await Deno.jupyter.broadcast("display_data", {
  data: { "text/plain": "working..." },
  metadata: {},
  transient: { display_id: "progress" },
});

/**
 * @title Deno KV: Key/Value database
 * @difficulty intermediate
 * @tags cli, deploy
 * @run --unstable-kv <url>
 * @resource {https://docs.deno.com/deploy/kv/} Deno KV user guide
 * @resource {https://docs.deno.com/api/deno/~/Deno.Kv} Deno KV Runtime API docs
 * @group Unstable APIs
 *
 * <strong>Warning: This is an unstable API that is subject to change or removal at any time.</strong><br>Deno KV is a key/value database built in to the Deno runtime, and works with
 * zero configuration on Deno Deploy. It's great for use cases that require fast
 * reads and don't require the query flexibility of a SQL database.
 */

// Open the default database
const kv = await Deno.openKv();

// Define an interface in TypeScript for our data
enum Rank {
  Bronze,
  Silver,
  Gold,
}

interface Player {
  username: string;
  rank: Rank;
}

// Create a few instances for testing
const player1: Player = { username: "carlos", rank: Rank.Bronze };
const player2: Player = { username: "briana", rank: Rank.Silver };
const player3: Player = { username: "alice", rank: Rank.Bronze };

// Store object data in Deno KV using the "set" operation. Keys can be arranged
// hierarchically, not unlike resources in a REST API.
await kv.set(["players", player1.username], player1);
await kv.set(["players", player2.username], player2);
await kv.set(["players", player3.username], player3);

// The "set" operation is used to both create and update data for a given key
player3.rank = Rank.Gold;
await kv.set(["players", player3.username], player3);

// Fetch a single object by key with the "get" operation
const record = await kv.get(["players", "alice"]);
const alice: Player = record.value as Player;
console.log(record.key, record.versionstamp, alice);

// Fetch several objects by key with "getMany"
const [record1, record2] = await kv.getMany([
  ["players", "carlos"],
  ["players", "briana"],
]);
console.log(record1, record2);

// List several records by key prefix - note that results are ordered
// lexicographically, so our players will be fetched in the order
// "alice", "briana", "carlos"
const records = kv.list({ prefix: ["players"] });
const players = [];
for await (const res of records) {
  players.push(res.value as Player);
}
console.log(players);

// Delete a value for a given key
await kv.delete(["players", "carlos"]);

// The Deno.KvU64 object is a wrapper for 64 bit integers (BigInt), so you can
// quickly update very large numbers. Let's add a "score" for alice.
const aliceScoreKey = ["scores", "alice"];
await kv.set(aliceScoreKey, new Deno.KvU64(0n));

// To prepare an atomic transaction to update the score, first we need to
// check if the score has been modified since we read it. We can use the
// versionstamp to check if the value has been modified since we read it.
const aliceScoreEntry = await kv.get<Deno.KvU64>(aliceScoreKey);
const atomicCheck = {
  key: aliceScoreEntry.key,
  versionstamp: aliceScoreEntry.versionstamp,
};

// Add 10 to the player's score in an atomic transaction
const res = await kv.atomic()
  .check(atomicCheck)
  .mutate({
    type: "sum",
    key: aliceScoreKey,
    value: new Deno.KvU64(10n),
  })
  .commit();
// Check if the transaction was successful
if (res.ok) {
  const newScore = (await kv.get<Deno.KvU64>(aliceScoreKey)).value;
  console.log("Alice's new score is:", newScore);
} else {
  console.error("Transaction failed ");
  // Optionally, implement retry logic or handle the conflict
}

/**
 * @title Atomic transactions in Deno KV
 * @difficulty intermediate
 * @tags cli, deploy
 * @run --unstable-kv <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.AtomicOperation} Doc: Deno.AtomicOperation
 * @resource {https://docs.deno.com/examples/kv/} Example: Deno KV
 * @group Deno KV and scheduling
 *
 * Deno KV transactions group reads and writes so they either all happen
 * or none do, with optimistic concurrency: a transaction only commits if
 * the values it read have not changed in the meantime. This example
 * transfers funds between two accounts safely and shows the retry pattern
 * used when transactions race.
 */

// Use an in-memory database for the example; omit the argument to open the
// default persistent database.
const kv = await Deno.openKv(":memory:");

await kv.set(["account", "alice"], 100);
await kv.set(["account", "bob"], 50);

// A transfer must read both balances, check the funds, and write both new
// balances as one unit. Each get returns the value together with a
// versionstamp identifying the exact revision that was read.
async function transfer(from: string, to: string, amount: number) {
  // Retry until the transaction commits. Commits fail only when another
  // writer changed one of the checked keys between our read and our write,
  // in which case we re-read and try again.
  while (true) {
    const fromEntry = await kv.get<number>(["account", from]);
    const toEntry = await kv.get<number>(["account", to]);
    if ((fromEntry.value ?? 0) < amount) {
      throw new Error("insufficient funds");
    }

    // check() asserts the versionstamps are still current at commit time.
    // If both checks pass, the two sets are applied atomically.
    const result = await kv.atomic()
      .check(fromEntry, toEntry)
      .set(["account", from], fromEntry.value! - amount)
      .set(["account", to], (toEntry.value ?? 0) + amount)
      .commit();
    if (result.ok) return;
  }
}

await transfer("alice", "bob", 25);
console.log((await kv.get(["account", "alice"])).value); // 75
console.log((await kv.get(["account", "bob"])).value); // 75

// For plain counters there is a shortcut: mutate with type "sum" adds to a
// value without needing a check, so concurrent increments never conflict.
// Sums use the 64-bit unsigned KvU64 wrapper type.
await kv.atomic().sum(["visits"], 1n).commit();
await kv.atomic().sum(["visits"], 1n).commit();
console.log((await kv.get(["visits"])).value); // [Deno.KvU64: 2n]

// A failed check leaves the database untouched and returns ok: false. Here
// the entry goes stale on purpose: the key is written again after we read
// it, so the versionstamp no longer matches.
const stale = await kv.get<number>(["account", "alice"]);
await kv.set(["account", "alice"], 75); // bump the versionstamp
const result = await kv.atomic()
  .check(stale)
  .set(["account", "alice"], 0)
  .commit();
console.log(result.ok); // false

kv.close();

/**
 * @title Deno KV watch
 * @difficulty intermediate
 * @tags cli, deploy
 * @run --unstable-kv -N <url>
 * @resource {https://docs.deno.com/deploy/kv/} Deno KV user guide
 * @resource {https://docs.deno.com/api/deno/~/Deno.Kv} Deno KV Runtime API docs
 * @group Unstable APIs
 *
 * <strong>Warning: This is an unstable API that is subject to change or removal at any time.</strong><br>Deno KV watch allows you to detect changes to your KV database, making
 * it easier to build real-time applications, newsfeeds, chat, and more.
 */

// Open the default database
const kv = await Deno.openKv();

// Set "counter" value to 0, then increment every second.
await kv.set(["counter"], new Deno.KvU64(0n));
setInterval(() => {
  kv.atomic().sum(["counter"], 1n).commit();
}, 1000);

// kv.watch([["counter"]]) also returns a ReadableStream you can consume
// yourself; here the server below streams each change to clients.

// To use server-sent events, let's create a server that
// responds with a stream. Each time a change to "counter"
// is detected, send the updated value to the client.
Deno.serve((_req) => {
  const stream = kv.watch([["counter"]]).getReader();
  const body = new ReadableStream({
    async start(controller) {
      while (true) {
        if ((await stream.read()).done) {
          return;
        }
        const data = await kv.get(["counter"]);
        controller.enqueue(
          new TextEncoder().encode(`Counter: ${data.value}\n`),
        );
      }
    },
    cancel() {
      stream.cancel();
    },
  });
  return new Response(body, {
    headers: {
      "Content-Type": "text/event-stream",
    },
  });
});

/**
 * @title Connect to an MCP server from a client
 * @difficulty intermediate
 * @tags cli
 * @run -R <url>
 * @resource {https://modelcontextprotocol.io/} Model Context Protocol
 * @resource {https://github.com/modelcontextprotocol/typescript-sdk} MCP TypeScript SDK
 * @group AI
 *
 * The other side of the Model Context Protocol: a client connects to a
 * server, discovers the tools it advertises, and calls them. This example
 * links a client to a small server over an in-memory transport so it runs on
 * its own. In practice the server is a separate process reached over stdio or
 * HTTP. See the "Build an MCP server" example for the server side.
 */

import { Client } from "npm:@modelcontextprotocol/sdk/client/index.js";
import { McpServer } from "npm:@modelcontextprotocol/sdk/server/mcp.js";
import { InMemoryTransport } from "npm:@modelcontextprotocol/sdk/inMemory.js";
import { z } from "npm:zod";

// A minimal server so the client has something to talk to.
const server = new McpServer({ name: "dinosaur-facts", version: "1.0.0" });
server.registerTool(
  "get_dinosaur_fact",
  {
    description: "Get a fact about a given dinosaur",
    inputSchema: { name: z.string().describe("The dinosaur's name") },
  },
  ({ name }: { name: string }) => ({
    content: [{ type: "text", text: `${name} was a dinosaur.` }],
  }),
);

// A client identifies itself with a name and version, like the server does.
const client = new Client({ name: "facts-client", version: "1.0.0" });

// A linked pair wires the two transports together in memory, with no
// subprocess or network. Connect each side to its end of the pair.
const [clientTransport, serverTransport] = InMemoryTransport.createLinkedPair();
await server.connect(serverTransport);
await client.connect(clientTransport);

// Discover what the server offers. Each tool carries a name, description, and
// input schema, which is how an AI client knows what it can call.
const { tools } = await client.listTools();
console.log("Available tools:", tools.map((t: { name: string }) => t.name));

// Call a tool by name with arguments matching its schema.
const result = await client.callTool({
  name: "get_dinosaur_fact",
  arguments: { name: "Velociraptor" },
});
console.log(result.content);

// Close the connection when done.
await client.close();

/**
 * @title Build an MCP server
 * @difficulty intermediate
 * @tags cli
 * @resource {https://modelcontextprotocol.io/} Model Context Protocol
 * @resource {https://github.com/modelcontextprotocol/typescript-sdk} MCP TypeScript SDK
 * @group AI
 *
 * The Model Context Protocol (MCP) is the standard way to expose tools and
 * data to AI assistants like Claude. An MCP server advertises tools the
 * model can call; the official TypeScript SDK runs in Deno through npm.
 * This server exposes a single tool over stdio, the transport desktop AI
 * clients use to launch and talk to local servers.
 */
import { McpServer } from "npm:@modelcontextprotocol/sdk/server/mcp.js";
import { StdioServerTransport } from "npm:@modelcontextprotocol/sdk/server/stdio.js";
import { z } from "npm:zod";

// A server has a name and version that clients use to identify it.
const server = new McpServer({
  name: "dinosaur-facts",
  version: "1.0.0",
});

// Register a tool the model can call. The inputSchema is a Zod schema: the
// SDK validates arguments against it and advertises the shape to the
// client, so the model knows what to pass. The handler returns content
// blocks, here a single piece of text.
const facts: Record<string, string> = {
  tyrannosaurus: "Tyrannosaurus rex could bite with 12,800 pounds of force.",
  velociraptor: "Velociraptor was about the size of a turkey.",
};

server.registerTool(
  "get_dinosaur_fact",
  {
    description: "Get a fact about a given dinosaur",
    inputSchema: { name: z.string().describe("The dinosaur's name") },
  },
  ({ name }: { name: string }) => {
    const fact = facts[name.toLowerCase()] ?? `No facts about ${name} yet.`;
    return { content: [{ type: "text", text: fact }] };
  },
);

// Connect the server to a transport. StdioServerTransport reads JSON-RPC
// messages from stdin and writes replies to stdout, which is how a desktop
// client runs the server as a subprocess. The server now waits for
// requests; it prints nothing on its own, so keep logging off stdout.
const transport = new StdioServerTransport();
await server.connect(transport);

// To use this server with Claude Desktop, add it to the client config and
// point the command at Deno:
//
//   {
//     "mcpServers": {
//       "dinosaur-facts": {
//         "command": "deno",
//         "args": ["run", "-R", "mcp_server.ts"]
//       }
//     }
//   }
//
// Or inspect it interactively with: npx @modelcontextprotocol/inspector

/**
 * @title Memoize an expensive function
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://jsr.io/@std/cache/doc/~/memoize} Doc: @std/cache memoize
 * @resource {https://jsr.io/@std/cache/doc/~/LruCache} Doc: @std/cache LruCache
 * @group Standard library
 *
 * Memoization caches the result of a function call so repeated calls
 * with the same arguments return instantly. The standard library ships
 * memoize for the wrapping and LruCache for keeping the cache bounded.
 * This example proves cache hits with a call counter and shows eviction
 * when the cache fills up.
 */

import { LruCache, type MemoizationCacheResult, memoize } from "jsr:@std/cache";

// A counter reveals how often the real function body runs.
let calls = 0;
function slowSquare(n: number): number {
  calls += 1;
  return n * n;
}

const fastSquare = memoize(slowSquare);

// The first call with a given argument computes the result.
console.log(fastSquare(9)); // 81
// The second call returns the cached value without running the body.
console.log(fastSquare(9)); // 81
console.log(calls); // 1

// A new argument is a cache miss, so the body runs again.
console.log(fastSquare(12)); // 144
console.log(calls); // 2

// By default the cache is an unbounded Map. The cache property exposes
// it for inspection or manual invalidation.
console.log(fastSquare.cache.size); // 2

// An LruCache keeps at most maxSize entries and evicts the least
// recently used one when a new entry would exceed the limit.
const lru = new LruCache<string, MemoizationCacheResult<number>>(2);

let lookups = 0;
const lookup = memoize((id: number): number => {
  lookups += 1;
  return id * 10;
}, { cache: lru });

lookup(1);
lookup(2);
// Adding a third entry evicts the entry for 1, the oldest of the two.
lookup(3);

// Calling with 1 again is a miss now, so the function body runs again.
lookup(1);
console.log(lookups); // 4

/**
 * @title Get the MIME type of a file
 * @difficulty beginner
 * @tags cli, deploy
 * @run <url>
 * @resource {https://jsr.io/@std/media-types} Doc: @std/media-types
 * @resource {https://developer.mozilla.org/en-US/docs/Web/HTTP/Basics_of_HTTP/MIME_types} MDN: MIME types
 * @group File System
 *
 * Serving a file over HTTP needs a content type header. The standard
 * library maps file extensions to MIME types. This example looks up the
 * type for a few file names.
 */
import { contentType } from "jsr:@std/media-types";
import { extname } from "node:path";

// Look up the MIME type for a file name by its extension.
console.log(contentType(extname("photo.png"))); // image/png
console.log(contentType(extname("data.json"))); // application/json

// Text types include their charset, ready to use in a header.
console.log(contentType(extname("index.html"))); // text/html; charset=UTF-8

// Unknown extensions return undefined, so provide a fallback. The standard
// fallback for arbitrary binary data is application/octet-stream.
const type = contentType(extname("archive.xyz")) ??
  "application/octet-stream";
console.log(type); // application/octet-stream

// A typical use: serving content with the right header.
const path = "data.json";
const body = new Blob(['{ "hello": "world" }']).stream();
const response = new Response(body, {
  headers: {
    "content-type": contentType(extname(path)) ?? "application/octet-stream",
  },
});
console.log(response.headers.get("content-type")); // application/json

// Note that the lookup trusts the file name. To identify a file by its
// actual contents, inspect its magic bytes instead.

/**
 * @title Connect to MongoDB
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -S -R <url>
 * @resource {https://www.npmjs.com/package/mongodb} MongoDB driver on npm
 * @group Databases
 *
 * Using the official MongoDB driver, you can connect to a MongoDB database
 * running anywhere.
 */

import { MongoClient } from "npm:mongodb@^7";

// Create a new instance of the MongoDB client running locally on port 27017
const client = new MongoClient("mongodb://127.0.0.1:27017");

// Connect to the MongoDB server
await client.connect();

// Define the schema for the collection
interface DinosaurSchema {
  name: string;
  skills: string[];
