/**
 * @title Hash and sign with node:crypto
 * @difficulty intermediate
 * @tags cli, deploy
 * @run <url>
 * @resource {https://docs.deno.com/api/node/crypto/} Doc: node:crypto
 * @resource {/examples/hashing/} Example: Hashing with the Web Crypto API
 * @group Cryptography
 *
 * Deno supports the node:crypto module so that npm packages relying on it
 * work out of the box. For new code the web-standard Web Crypto API is the
 * preferred path, but when you maintain code written against node:crypto,
 * or interoperate with packages that use it, the familiar functions are
 * available.
 */

import {
  createHash,
  createHmac,
  randomBytes,
  timingSafeEqual,
} from "node:crypto";

// Hash data with the classic update and digest chain. The hex digest of a
// fixed input is always the same.
const hash = createHash("sha256").update("hello world").digest("hex");
console.log(hash);
// b94d27b9934d3e08a52e52d7da7dabfac484efe37a5380ee9088f7ace2efcde9

// An HMAC authenticates a message with a shared secret key. Only someone
// who knows the key can produce or verify this tag.
const hmac = createHmac("sha256", "secret-key")
  .update("hello world")
  .digest("hex");
console.log(hmac);
// 095d5a21fe6d0646db223fdf3de6436bb8dfb2fab0b51677ecf6441fcf5f2a67

// randomBytes returns cryptographically secure random bytes as a Buffer.
console.log(randomBytes(16).toString("hex")); // e.g. 1dec06198400...

// timingSafeEqual compares two equal-length buffers in constant time,
// which is the right way to check secrets like HMAC tags.
const expected = Buffer.from(hmac, "hex");
const actual = createHmac("sha256", "secret-key")
  .update("hello world")
  .digest();
console.log(timingSafeEqual(expected, actual)); // true

/**
 * @title Read input line by line with node:readline
 * @difficulty beginner
 * @tags cli
 * @run -R -W <url>
 * @resource {https://docs.deno.com/api/node/readline/} Doc: node:readline
 * @resource {https://docs.deno.com/examples/reading_stdin/} Example: Read from stdin
 * @group System
 *
 * The node:readline module reads a stream one line at a time, no matter
 * how the bytes are chunked, and it powers interactive prompts in many
 * Node.js programs. Deno supports it out of the box. This example
 * processes a file line by line and asks a question on the terminal.
 */

// We write a small file to read back, so the example is self contained.
const dir = await Deno.makeTempDir();
const path = `${dir}/access.log`;
await Deno.writeTextFile(
  path,
  "GET /index.html\nGET /styles.css\nPOST /api/login\nGET /favicon.ico\n",
);

// createInterface takes any readable stream as input. Combined with a
// file stream from node:fs it iterates the file line by line. The
// crlfDelay option makes sure Windows style \r\n line endings count as
// one line break.
import { createReadStream } from "node:fs";
import { createInterface } from "node:readline";

const rl = createInterface({
  input: createReadStream(path),
  crlfDelay: Infinity,
});

// The interface is an async iterable of lines, without the line breaks.
let total = 0;
let gets = 0;
for await (const line of rl) {
  total++;
  if (line.startsWith("GET ")) gets++;
  console.log(`line ${total}: ${line}`);
}
console.log(`${gets} of ${total} requests were GETs`);
// line 1: GET /index.html
// line 2: GET /styles.css
// line 3: POST /api/login
// line 4: GET /favicon.ico
// 3 of 4 requests were GETs

// The promises variant adds question, which prints a prompt and resolves
// with the user's answer. That only makes sense on a terminal, so we
// guard it the same way interactive prompts usually are. (When stdin is a
// pipe or a file, this block is skipped.)
import readline from "node:readline/promises";
import process from "node:process";

if (Deno.stdin.isTerminal()) {
  const prompter = readline.createInterface({
    input: process.stdin,
    output: process.stdout,
  });
  const name = await prompter.question("What is your name? ");
  console.log(`Hello, ${name}!`);
  prompter.close();
}

// Reading the file requires the -R permission; creating the temporary
// file requires -W.
await Deno.remove(dir, { recursive: true });

