/**
 * @title Listen for OS signals
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.addSignalListener} Doc: Deno.addSignalListener
 * @group System
 *
 * You can listen for OS signals using the `Deno.addSignalListener` function.
 * This allows you to do things like gracefully shutdown a server when a
 * `SIGINT` signal is received.
 */

console.log("Counting seconds...");

let i = 0;

// We isolate the signal handler function so that we can remove it later.
function sigIntHandler() {
  console.log("interrupted! your number was", i);
  Deno.exit();
}

// Then, we can listen for the `SIGINT` signal,
// which is sent when the user presses Ctrl+C.
Deno.addSignalListener("SIGINT", sigIntHandler);

// While we're waiting for the signal, we can do other things,
// like count seconds, or start a server.
const interval = setInterval(() => {
  i++;
}, 1000);

// And, after 10 seconds, we can exit and remove the signal listener.
setTimeout(() => {
  clearInterval(interval);
  Deno.removeSignalListener("SIGINT", sigIntHandler);
  console.log("done! it has been 10 seconds");
}, 10_000);

/**
 * @title Parse and generate XML
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://jsr.io/@libs/xml} @libs/xml on JSR
 * @group Encoding
 *
 * The @libs/xml package on JSR converts XML in both directions: XML text
 * to plain JavaScript objects and back. This is enough for RSS feeds,
 * sitemaps, SVG manipulation, and API responses from older services.
 */
import { parse, stringify } from "jsr:@libs/xml";

// An RSS-style document with attributes, nesting, and repeated elements.
const xml = `<?xml version="1.0" encoding="UTF-8"?>
<feed>
  <title>Deno releases</title>
  <entry id="1" draft="false">
    <title>Deno 2.0</title>
  </entry>
  <entry id="2" draft="true">
    <title>Deno 2.1</title>
  </entry>
</feed>`;

// parse returns nested objects. Attributes are prefixed with @, text
// content of a leaf element becomes its value, and repeated elements
// become an array.
const doc = parse(xml) as unknown as {
  feed: {
    title: string;
    entry: { "@id": string; "@draft": string; title: string }[];
  };
};

console.log(doc.feed.title); // Deno releases
console.log(doc.feed.entry.length); // 2
console.log(doc.feed.entry[1]["@id"]); // 2

// Values keep their string form unless you opt into revival; attributes
// like draft="true" can be compared as strings or revived to booleans via
// the reviver options of parse.
const drafts = doc.feed.entry.filter((e) => e["@draft"] === "true");
console.log(drafts.map((e) => e.title)); // [ "Deno 2.1" ]

// stringify performs the reverse mapping: objects with @-prefixed keys
// become attributes, everything else becomes elements.
const generated = stringify({
  sitemap: {
    url: [
      { loc: "https://example.com/", "@priority": "1.0" },
      { loc: "https://example.com/docs", "@priority": "0.8" },
    ],
  },
});
console.log(generated);
// <sitemap>
//   <url priority="1.0">
//     <loc>https://example.com/</loc>
//   </url>
//   <url priority="0.8">
//     <loc>https://example.com/docs</loc>
//   </url>
// </sitemap>

/**
 * @title Parsing JSONC
 * @difficulty beginner
 * @tags cli, deploy
 * @run <url>
 * @resource {https://jsr.io/@std/jsonc} Doc: @std/jsonc
 * @resource {https://docs.deno.com/runtime/fundamentals/configuration/} Doc: deno.json configuration
 * @group Encoding
 *
 * JSONC is JSON extended with comments and trailing commas, which makes it
 * a friendlier format for configuration files that humans edit. Deno reads
 * its own deno.jsonc config file in this format. The Standard Library
 * provides a parser for it in jsr:@std/jsonc.
 */
import { parse } from "jsr:@std/jsonc";

// This config uses line comments, a block comment and trailing commas.
// All three are valid JSONC.
const text = `{
  // The name appears in log output.
  "name": "my-app",
  /* Ports below 1024 need extra privileges. */
  "port": 8080,
  "features": [
    "http",
    "websockets",
  ],
}`;

// To parse, pass the text to the parse function. Comments and trailing
// commas are dropped and a plain JavaScript value comes back.
const config = parse(text);
console.log(config); // { name: "my-app", port: 8080, features: [ "http", "websockets" ] }

// The return type is JsonValue, so cast it to the shape you expect before
// accessing properties.
const { name, port } = config as { name: string; port: number };
console.log(name, port); // my-app 8080

// The built-in JSON.parse rejects the same text, because comments and
// trailing commas are not valid JSON. It throws on the first comment.
try {
  JSON.parse(text);
} catch (error) {
  console.log((error as Error).name); // SyntaxError
}

