// First we will import the module from the Deno Standard Library
import * as path from "jsr:@std/path";
import * as posix from "jsr:@std/path/posix";
import * as windows from "jsr:@std/path/windows";

// Converting from a file url to a directory can be done simply by the `fromFileUrl`
// method from the appropriate implementation.
const p1 = posix.fromFileUrl("file:///home/foo");
const p2 = windows.fromFileUrl("file:///home/foo");
console.log(`Path 1: ${p1} Path 2: ${p2}`);

// We can also choose to not specify the platform and automatically use whatever Deno is running on
const p3 = path.fromFileUrl("file:///home/foo");
console.log(`Path on current OS: ${p3}`);

// We can get the last part of a file path using the basename method
const p = path.basename("./deno/is/awesome/mod.ts");
console.log(p); // mod.ts

// We can get the directory of a file path using the dirname method
const base = path.dirname("./deno/is/awesome/mod.ts");
console.log(base); // ./deno/is/awesome

// We can get the extension of a file path using the extname method
const ext = path.extname("./deno/is/awesome/mod.ts");
console.log(ext); // .ts

// We can format a path using a FormatInputPathObject
const formatPath = path.format({
  root: "/",
  dir: "/home/user/dir",
  ext: ".html",
  name: "index",
});
console.log(formatPath); // "/home/user/dir/index.html"

// When we want to make our code cross-platform, we can use the join method.
// This joins any number of string by the OS-specific file separator. On
// Mac OS this would be foo/bar. On windows, this would be foo\bar.
const joinPath = path.join("foo", "bar");
console.log(joinPath);

// We can get the current working directory using the built-in cwd method
const current = Deno.cwd();
console.log(current);

// We can get the directory name of the current module using the built-in
// dirname method
const dirname = import.meta.dirname;
console.log(dirname);

// We can get the URL of the current module using the built-in
// url method
const url = import.meta.url;
console.log(url);

// We can get the file name of the current module using the built-in
// filename method
const filename = import.meta.filename;
console.log(filename);

/**
 * @title Measure performance with marks and measures
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Performance} MDN: Performance
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Performance/measure} MDN: performance.measure
 * @group Web Standard APIs
 *
 * The performance API measures elapsed time with sub-millisecond
 * precision. performance.now gives quick deltas, while named marks and
 * measures build a timeline you can query later and inspect in the
 * DevTools performance panel when debugging with the inspector. Timings
 * differ on every machine and run, so the outputs below are examples.
 */

// performance.now returns milliseconds since the program started. The
// difference between two calls times a block of code.
const start = performance.now();
let total = 0;
for (let i = 0; i < 1_000_000; i++) {
  total += Math.sqrt(i);
}
const elapsed = performance.now() - start;
console.log(`loop took ${elapsed.toFixed(1)} ms`); // e.g. loop took 2.8 ms

// Marks are named points in time. Place one before and one after the
// work you care about.
performance.mark("wait-start");
await new Promise((resolve) => setTimeout(resolve, 50));
performance.mark("wait-end");

// A measure is the named span between two marks. It is returned and also
// recorded on the timeline.
const waitMeasure = performance.measure("wait", "wait-start", "wait-end");
console.log(`${waitMeasure.name}: ${waitMeasure.duration.toFixed(1)} ms`); // e.g. wait: 51.5 ms

// With one mark you can measure from it to now by omitting the end mark.
performance.mark("parse-start");
JSON.parse(
  JSON.stringify({ items: Array.from({ length: 10_000 }, (_, i) => i) }),
);
performance.measure("parse", "parse-start");

// All recorded measures are available later by type, so you can time
// several stages and report them together at the end.
for (const entry of performance.getEntriesByType("measure")) {
  console.log(`${entry.name} took ${entry.duration.toFixed(1)} ms`); // e.g. wait took 51.5 ms
}

// Entries can also be fetched by name.
console.log(performance.getEntriesByName("wait").length); // 1

// Clearing marks and measures resets the timeline, which keeps memory
// flat in long-running processes.
performance.clearMarks();
performance.clearMeasures();
console.log(performance.getEntriesByType("measure").length); // 0

/**
 * @title Permission management
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.Permissions} Doc: Deno.Permissions
 * @resource {https://docs.deno.com/runtime/fundamentals/security/} Doc: Permissions and the --allow-* flags
 * @group CLI
 *
 * There are times where depending on the state of permissions
 * granted to a process, we want to do different things. This is
 * made very easy to do with the Deno permissions API.
 *
 * This example covers the runtime permissions API. To grant permissions when
 * launching a program from the command line with flags like `--allow-read` or
 * `--allow-net`, see the permissions reference linked above.
 */

// In the most simple case, we can just request a permission by it's name.
// In this case, we ask for -E and prompt the user. The user will
// not be prompted if it was already allowed in the past and not revoked.
let status = await Deno.permissions.request({ name: "env" });
if (status.state === "granted") {
  console.log("'env' permission is granted.");
} else {
  console.log("'env' permission is denied.");
}

// There are also synchronous versions of all the permission APIs
status = Deno.permissions.requestSync({ name: "env" });
if (status.state === "granted") {
  console.log("'env' permission is granted.");
} else {
  console.log("'env' permission is denied.");
}

// We can also query permissions without asking for them. In this case,
// we are querying whether or not we have the read permission. Not only
// can we query whether we have a permission or not, we can even specify
// what directories we have permissions in using the path option.
const readStatus = await Deno.permissions.query({
  name: "read",
  path: "/etc",
});
console.log(readStatus.state);

// In the case that we no longer need a permission, it is also possible
// to revoke a process's access to that permission. This is useful when
// a process starts running untrusted code.
import { assert } from "jsr:@std/assert";

const runStatus = await Deno.permissions.revoke({ name: "run" });
assert(runStatus.state !== "granted");

