/**
 * @title Piping streams
 * @difficulty intermediate
 * @tags cli
 * @run -N -R -W <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/ReadableStream} MDN: ReadableStream
 * @resource {/examples/tcp_listener} Example: TCP Listener
 * @group Network
 *
 * Deno implements web-standard streams which comes with many advantages. One of the most useful
 * features of streams is how they can be piped to and from different sources.
 */

// A common usecase for streams is downloading files without buffering the whole file in memory.
// First, we open a file we want to write to
const download = await Deno.open("example.html", { create: true, write: true });

// Now let's make a request to a web page
const req = await fetch("https://examples.deno.land");

// We can pipe this response straight into the file. In a more realistic example, we would
// handle a bad request, but here we'll just use the nullish coalescing operator. Instead of
// opening the file and manually piping the fetch body to it, we could also just use `Deno.writeFile`.
req.body?.pipeTo(download.writable);

// Pipes can connect a lot of things. For example, we could pipe the file we just downloaded into
// stdout. We could also pipe our streams through transformers to get a more interesting result. In this
// case, we will pipe our file through a stream which will highlight all "<" characters in the terminal.

// First we will import a utility from the standard library to help us with this.
import { bgBrightYellow } from "jsr:@std/fmt/colors";

// Then we will create a transform stream utility class
class HighlightTransformStream extends TransformStream<string, string> {
  constructor() {
    super({
      transform: (chunk, controller) => {
        controller.enqueue(chunk.replaceAll("<", bgBrightYellow("<")));
      },
    });
  }
}

// Let's open our file for reading
const example = await Deno.open("example.html", { read: true });

// Now we can pipe the result from the file, into a TextDecoderStream, into our custom transform class,
// back through a TextEncoderStream, and finally into stdout
await example.readable
  .pipeThrough(new TextDecoderStream())
  .pipeThrough(new HighlightTransformStream())
  .pipeThrough(new TextEncoderStream())
  .pipeTo(Deno.stdout.writable);

/**
 * @title Connect to Postgres
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -E <url>
 * @resource {https://www.npmjs.com/package/postgres} postgres on npm
 * @group Databases
 *
 * Using the npm Postgres client, you can connect to a Postgres database
 * running anywhere. Connection settings belong in environment variables
 * rather than in the source, so the same code runs against your local
 * database and production.
 */

// Import the Postgres package from npm
import postgres from "npm:postgres";

// Read the connection settings from the standard libpq environment
// variables. Locally you might set PGDATABASE=test and nothing else;
// in production a managed database provides all of them. A common pattern
// is to keep these in a .env file and load it with the --env-file flag,
// for example: deno run --env-file -N -E main.ts
const sql = postgres({
  host: Deno.env.get("PGHOST") ?? "localhost",
  port: Number(Deno.env.get("PGPORT") ?? 5432),
  user: Deno.env.get("PGUSER") ?? "postgres",
  password: Deno.env.get("PGPASSWORD"),
  database: Deno.env.get("PGDATABASE") ?? "postgres",
});

// Execute a SQL query. Connections open lazily on first use, so this is
// the first place a bad address or password surfaces; handle it instead
// of leaking a stack trace, and close the connection pool either way.
// Connection failures arrive as an AggregateError with the cause on its
// code property, for example ECONNREFUSED when nothing is listening.
try {
  const people = await sql`
    SELECT id, name FROM people
  `;
  console.log(people);
} catch (error) {
  const reason = (error as { code?: string }).code ?? String(error);
  console.error("Query failed:", reason); // Query failed: ECONNREFUSED
} finally {
  // Close the connection to the database
  await sql.end();
}

/**
 * @title Show progress bars and spinners
 * @difficulty intermediate
 * @tags cli
 * @run <url>
 * @resource {https://jsr.io/@std/cli/doc/unstable-spinner/~} Doc: @std/cli Spinner
 * @resource {https://jsr.io/@std/cli/doc/unstable-progress-bar/~} Doc: @std/cli ProgressBar
 * @group CLI
 *
 * Long-running command line tools feel broken when they print nothing. The
 * standard library ships a Spinner for tasks of unknown length and a
 * ProgressBar for tasks with a known total. Both are currently exported
 * from unstable submodules of the cli package, so their APIs may still
 * change.
 */

// Spinner and ProgressBar live behind unstable- import paths until the
// APIs are stabilized.
import { Spinner } from "jsr:@std/cli@^1.0.30/unstable-spinner";
import { ProgressBar } from "jsr:@std/cli@^1.0.30/unstable-progress-bar";
import { delay } from "jsr:@std/async@^1.0.0/delay";

// Animations only make sense on an interactive terminal. When output is
// piped to a file or another process, redrawing the same line just dumps
// control characters into the stream, so check for a terminal first and
// fall back to plain lines.
const isInteractive = Deno.stdout.isTerminal();

// A spinner suits work with no measurable progress, like waiting on the
// network. It animates on its own; update the message as phases change.
if (isInteractive) {
  const spinner = new Spinner({
    message: "Contacting server...",
    color: "yellow",
  });
  spinner.start();
  await delay(1500);
  spinner.message = "Downloading manifest...";
  await delay(1500);
  spinner.stop();
}
console.log("Manifest downloaded.");

// A progress bar suits work with a known total. Progress is reported by
// assigning to the value property, and stop finishes the line. The bar
// redraws on a one second interval by default, and the formatter option
// controls the layout of the line.
const files = ["a.txt", "b.txt", "c.txt", "d.txt", "e.txt"];
if (isInteractive) {
  const bar = new ProgressBar({
    max: files.length,
    fillChar: "#",
    emptyChar: "-",
    formatter: (f) =>
      `[${f.styledTime}] [${f.progressBar}] ${f.value}/${f.max} files`,
  });
  for (const _file of files) {
    await delay(400);
    bar.value += 1;
  }
  await bar.stop();
} else {
  // The non-interactive fallback logs one line per step instead.
  for (const [i, file] of files.entries()) {
    await delay(100);
    console.log(`Copied ${file} (${i + 1}/${files.length})`);
  }
}
console.log("Done.");

// In a terminal the spinner animates in place while the message changes,
// and the bar fills a single line that ends like this:
//
//   ⠏ Downloading manifest...
//   [00:02] [##################################################] 5/5 files

// When output is piped, isTerminal() is false and only the fallback lines
// are printed:
//
//   deno run progress_spinners.ts | cat
//   Manifest downloaded.
//   Copied a.txt (1/5)
//   Copied b.txt (2/5)
//   Copied c.txt (3/5)
//   Copied d.txt (4/5)
//   Copied e.txt (5/5)
//   Done.

/**
 * @title Add a timeout to any promise
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://jsr.io/@std/async/doc/~/deadline} Doc: @std/async deadline
 * @resource {https://jsr.io/@std/async/doc/~/abortable} Doc: @std/async abortable
 * @group Standard library
 *
 * A promise has no built-in time limit, so a stalled request can hang a
 * program forever. The deadline function wraps any promise and rejects
 * it after a given number of milliseconds. The abortable function does
 * the same with an AbortSignal, which lets a user or another event
 * cancel the wait.
 */

import { abortable, deadline, delay } from "jsr:@std/async";

// When the promise settles before the time limit, deadline resolves
// with its value as if the wrapper was not there.
const fast = delay(50).then(() => "fetched 3 records");
console.log(await deadline(fast, 1_000)); // fetched 3 records

// When the time limit hits first, deadline rejects with a DOMException
// named TimeoutError.
const slow = delay(2_000, { persistent: false }).then(() => "too late");
try {
  await deadline(slow, 100);
} catch (err) {
  console.log((err as DOMException).name); // TimeoutError
}

// The rejection only stops the waiting. The slow task above keeps
// running in the background unless it accepts a signal and honors it,
// so pass an AbortSignal to the underlying work whenever you can.

// The abortable function ties a promise to an AbortSignal instead of a
// clock. Here the same signal also cancels the underlying delay, so no
// work is left running after the abort.
const controller = new AbortController();
const work = delay(2_000, { signal: controller.signal })
  .then(() => "report ready");

setTimeout(() => controller.abort(), 50);

try {
  await abortable(work, controller.signal);
} catch (err) {
  console.log((err as DOMException).name); // AbortError
}

