  },
});

const bucket = Deno.env.get("S3_BUCKET")!;

// Upload an object. Body also accepts a stream or Uint8Array for larger files.
await s3.send(
  new PutObjectCommand({
    Bucket: bucket,
    Key: "hello.txt",
    Body: "Hello from Deno!",
    ContentType: "text/plain",
  }),
);
console.log("Uploaded hello.txt");

// Presign a GET URL so a browser can download the object directly for a
// limited time, without your credentials.
const url = await getSignedUrl(
  s3,
  new GetObjectCommand({ Bucket: bucket, Key: "hello.txt" }),
  { expiresIn: 3600 },
);
console.log("Download URL (valid 1 hour):", url);

/**
 * @title Spin up a sandbox to run untrusted code
 * @difficulty beginner
 * @tags sandbox
 * @run -A --env-file <url>
 * @resource {https://docs.deno.com/sandbox/} Deno Deploy Sandbox
 * @group Deno Deploy
 *
 * Deno Deploy's Sandbox API lets you create secure microVMs to run untrusted code safely.
 * In this example, we ask Claude to generate a Deno script that fetches the current Bitcoin price,
 * then run that script inside a sandbox with strict resource limits and no access to the host environment.
 */

// Import the Anthropic SDK and the Deno Sandbox SDK.
import Anthropic from "npm:@anthropic-ai/sdk";
import { Sandbox } from "jsr:@deno/sandbox";

// Create an Anthropic client.
// It automatically picks up ANTHROPIC_API_KEY from your environment.
const client = new Anthropic();

// Ask Claude to write some code for us wrapped in a markdown code block.
const response = await client.messages.create({
  model: "claude-opus-4-6",
  max_tokens: 1024,
  messages: [{
    role: "user",
    content:
      "Write a Deno script that fetches the current Bitcoin price from the CoinGecko API and prints it.",
  }],
});

// Take the generated code out of Claude's response.
// Check it's a text block, then strip the markdown
// fences to get the raw source.
const firstBlock = response.content[0];
if (firstBlock.type !== "text") {
  throw new Error(`Unexpected content type: ${firstBlock.type}`);
}
const generatedCode = extractCode(firstBlock.text);

// Create a sandbox.
await using sandbox = await Sandbox.create();

// Write the AI-generated code into the sandbox filesystem.
await sandbox.fs.writeTextFile("/tmp/generated.ts", generatedCode);

// Run the code inside the sandbox with Deno.
// stdout and stderr are piped so we can capture and display them.
const child = await sandbox.spawn("deno", {
  args: [
    "run",
    "--allow-net=api.coingecko.com", // Only the specific host we expect
    "/tmp/generated.ts",
  ],
  stdout: "piped",
  stderr: "piped",
});

// AI-generated code could accidentally (or maliciously) loop forever —
// this ensures we kill the process after 10 seconds no matter what.
const timeout = setTimeout(() => child.kill(), 10_000);

// Wait for the process to finish and print the results.
// output.stdoutText / stderrText are pre-decoded UTF-8 strings.
// output.status.success is true only if the exit code was 0.
try {
  const output = await child.output();
  console.log("Output:\n", output.stdoutText ?? "No output");
  if (!output.status.success) {
    console.error("Error:\n", output.stderrText ?? "No error output");
  }
} finally {
  clearTimeout(timeout);
}

// Helper: extract the first code block from a markdown string.
// Falls back to returning the raw text if no fences are found.
function extractCode(text: string): string {
  const match = text.match(
    /```(?:typescript|ts|javascript|js)?\n([\s\S]*?)```/,
  );
  return match ? match[1] : text;
}

/**
 * @title Generate secure random values
 * @difficulty beginner
 * @tags cli, deploy
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Crypto/getRandomValues} MDN: crypto.getRandomValues
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Crypto/randomUUID} MDN: crypto.randomUUID
 * @group Cryptography
 *
 * Session tokens, password reset links, and API keys must be impossible to
 * guess. Math.random is not suitable for secrets because its output is
 * predictable from earlier outputs. The built-in Web Crypto API provides a
 * cryptographically secure random source instead.
 */

// Fill a typed array with random bytes from the secure random source.
const bytes = crypto.getRandomValues(new Uint8Array(16));
console.log(bytes); // e.g. Uint8Array(16) [ 81, 186, 47, ... ]

// Generate a v4 UUID, handy as a unique identifier.
console.log(crypto.randomUUID()); // e.g. 721475a3-3280-4f61-8d5f-374c83a7cdfa

// For tokens that travel in URLs or headers, encode random bytes as text.
// 32 random bytes give 256 bits of entropy, plenty for a session token.
const token = crypto.getRandomValues(new Uint8Array(32));
const options = { alphabet: "base64url", omitPadding: true } as const;
console.log(token.toBase64(options)); // e.g. QIUpF1ewQ-bc...
console.log(token.toHex()); // e.g. 4085291757b0...

// A uniform random integer in a range takes more care. The naive approach,
// value % range, is biased: 2 ** 32 is rarely a multiple of the range, so
// the leftover values at the top wrap around and make small results
// slightly more likely. Rejection sampling discards that uneven tail and
// retries, which keeps every value in the range equally likely.
function randomInt(min: number, max: number): number {
  const range = max - min;
  const limit = Math.floor(2 ** 32 / range) * range;
  const sample = new Uint32Array(1);
  do {
    crypto.getRandomValues(sample);
  } while (sample[0] >= limit);
  return min + (sample[0] % range);
}

// Roll a die: a uniform integer from 1 to 6.
console.log(randomInt(1, 7)); // e.g. 5

/**
 * @title Generate seeded random numbers
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://jsr.io/@std/random} @std/random on JSR
 * @resource {https://docs.deno.com/examples/secure_random_values/} Example: Generate secure random values
 * @group Standard library
 *
 * Math.random gives you no way to set a seed, so test runs and simulations
 * that need reproducible randomness cannot use it. The @std/random module
 * provides a seeded pseudo-random number generator (PCG32) plus helpers
 * for ranges, sampling, and shuffling that accept any generator. Do not
 * use seeded generators for security; for tokens and keys, see the secure
 * random values example.
 */
import {
  randomIntegerBetween,
  randomSeeded,
  sample,
  shuffle,
} from "jsr:@std/random";

// randomSeeded creates a generator from a bigint seed. It is a drop-in
// replacement for Math.random: a function returning floats in [0, 1).
const prng = randomSeeded(42n);

console.log(prng()); // 0.7916327826678753
console.log(prng()); // 0.7799280444160104

// The same seed always produces the same sequence, which is the point:
// a failing test that used seed 42 can be replayed exactly.
const replay = randomSeeded(42n);
console.log(replay()); // 0.7916327826678753

// The helpers take the generator through the prng option. Without it they
// fall back to Math.random.
console.log(randomIntegerBetween(1, 6, { prng })); // 1

// sample picks a random element, shuffle returns a new shuffled array.
const deck = ["ace", "king", "queen", "jack"];
console.log(sample(deck, { prng })); // jack
console.log(shuffle(deck, { prng })); // [ "ace", "queen", "jack", "king" ]

// For seeded bytes, getRandomValuesSeeded builds the seeded counterpart
// of crypto.getRandomValues: it takes a seed and returns a function that
// fills typed arrays.
import { getRandomValuesSeeded } from "jsr:@std/random";
const getRandomValues = getRandomValuesSeeded(42n);
console.log(getRandomValues(new Uint8Array(4)));

/**
 * @title Parse and compare semver versions
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://jsr.io/@std/semver/doc/~/parse} Doc: @std/semver parse
 * @resource {https://jsr.io/@std/semver/doc/~/satisfies} Doc: @std/semver satisfies
 * @group Standard library
 *
 * Version strings cannot be compared as plain text, because "1.10.0"
 * sorts before "1.2.0" alphabetically. The @std/semver package parses
 * semantic versions into objects and compares them by their numeric
 * parts, with full support for ranges like ^1.2.0.
 */

import {
  compare,
  format,
  maxSatisfying,
  parse,
  parseRange,
  satisfies,
} from "jsr:@std/semver";

// Parse turns a version string into an object with numeric fields.
const version = parse("1.2.3-rc.1");
console.log(version.major, version.minor, version.patch); // 1 2 3
console.log(version.prerelease); // [ "rc", 1 ]

// String comparison gets this wrong, semver comparison does not.
console.log("1.10.0" < "1.2.0"); // true
console.log(compare(parse("1.10.0"), parse("1.2.0"))); // 1

// Compare returns -1, 0, or 1, which makes it a ready-made sort
// comparator for a list of versions.
const versions = ["1.0.0", "2.1.3", "1.10.2", "0.9.0"].map(parse);
versions.sort(compare);
console.log(versions.map(format)); // [ "0.9.0", "1.0.0", "1.10.2", "2.1.3" ]

// Ranges use the same syntax as package manifests. Parse the range
// once, then test versions against it with satisfies.
const range = parseRange("^1.2.0");
console.log(satisfies(parse("1.9.9"), range)); // true
console.log(satisfies(parse("2.0.0"), range)); // false

// maxSatisfying picks the highest version that fits the range, which
// is how a package manager resolves a dependency.
const best = maxSatisfying(versions, parseRange(">=1.0.0 <2.0.0"));
console.log(format(best!)); // 1.10.2

