/**
 * @title Set the time zone
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Intl/DateTimeFormat} MDN: Intl.DateTimeFormat
 * @resource {/examples/temporal/} Example: Temporal API
 * @group System
 *
 * Date, Intl, and Temporal all format times in the process time zone,
 * which defaults to the operating system setting. The TZ environment
 * variable overrides it, which makes time-dependent behavior reproducible.
 */

// The current time zone is visible through the Intl API.
const zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
console.log(zone); // Europe/Warsaw (or whatever the OS is set to)

// Everything that formats local time follows it.
console.log(new Date().toString());

// Start the process with TZ set to pin the zone, for example to keep
// timestamps in CI logs consistent or to reproduce a user's bug report:
//
//   TZ=Asia/Tokyo deno run main.ts
//   Asia/Tokyo
//   Thu Jun 11 2026 22:15:00 GMT+0900 (Japan Standard Time)
//
//   TZ=UTC deno run main.ts
//   UTC

// The Temporal API is the preferred way to work with zoned time. The
// current moment in the process zone keeps its zone name attached.
const now = Temporal.Now.zonedDateTimeISO();
console.log(now.timeZoneId); // Europe/Warsaw (follows TZ like the above)

// Getting the same moment in another zone is an argument, not a process
// setting, so zone conversions stay explicit and local to the call.
const tokyoTime = Temporal.Now.zonedDateTimeISO("Asia/Tokyo");
console.log(tokyoTime.hour); // e.g. 22

// The Intl API formats a value for another zone the same way.
const tokyo = new Intl.DateTimeFormat("en-US", {
  timeStyle: "long",
  timeZone: "Asia/Tokyo",
}).format(new Date());
console.log(tokyo);

/**
 * @title Sleep and delay execution
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://jsr.io/@std/async/doc/~/delay} Doc: @std/async delay
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/AbortSignal} MDN: AbortSignal
 * @group Basics
 *
 * Scripts often need to wait: between retries, while polling, or to pace
 * requests. This example shows how to sleep without blocking, and how to
 * make a sleep cancelable.
 */

// The simplest sleep is a promise around setTimeout.
function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

console.log("waiting...");
await sleep(100);
console.log("done"); // prints 100ms later

// The same helper ships with the Node.js compatibility APIs as a promised
// setTimeout, with an optional resolution value.
import { setTimeout as nodeSleep } from "node:timers/promises";
console.log(await nodeSleep(100, "woke up")); // woke up

// The standard library provides the same thing as delay, with extras.
import { delay } from "jsr:@std/async/delay";
await delay(100);

// A delay accepts an AbortSignal, which makes it cancelable. Aborting
// rejects the promise.
const controller = new AbortController();
setTimeout(() => controller.abort(), 50);
try {
  await delay(10_000, { signal: controller.signal });
} catch {
  console.log("sleep canceled after 50ms"); // sleep canceled after 50ms
}

// A pending timer keeps the process alive. The persistent option releases
// it, so a long delay will not stop a finished program from exiting.
await delay(0, { persistent: false });

/**
 * @title Spy functions
 * @difficulty intermediate
 * @tags cli, deploy
 * @run <url>
 * @resource {https://jsr.io/@std/testing/doc/mock#spying} Spy docs on JSR
 * @resource {https://www.typescriptlang.org/docs/handbook/release-notes/typescript-5-2.html} Typescript docs for `using` keyword
 * @group Testing
 *
 * A function spy allows us to assert that a function was called with the correct arguments and a specific number of times.
 * This snippet demonstrates how to spy on a function using a mock function.
 */

import { assertSpyCall, assertSpyCalls, spy } from "jsr:@std/testing/mock";

function log(message: string) {
  console.log(message);
}

const logger = { log };

Deno.test("logger uses the log function", () => {
  // Create a spy on the `logger.log` method.
  const logSpy = spy(logger, "log");

  // Call the `logger.log` method.
  logger.log("Hello, world!");

  try {
    // Assert that the `log` function was called just once.
    assertSpyCalls(logSpy, 1);

    // Assert that the `log` function was called with the correct arguments.
    assertSpyCall(logSpy, 0, { args: ["Hello, world!"] });
  } finally {
    // Restore the logger.log function to stop spying it.
    logSpy.restore();
  }
});

Deno.test("Creating a spy with the using keyword", () => {
  // method spys are disposable, so we can create them with the keyword `using`
  using logSpy = spy(logger, "log");

  logger.log("Disposable spy");

  // Spys created with the `using` keyword are automatically restored at the end of the test
  assertSpyCalls(logSpy, 1);
});

