/**
 * @title Shamir's Secret Sharing
 * @difficulty intermediate
 * @tags cli
 * @run <url>
 * @group Cryptography
 *
 * This example demonstrates Shamir's Secret Sharing, where a secret, split into shares, allows its
 * reconstruction only when a sufficient number of shares are combined.
 */

// Random Number Generation within a range
async function getSecureRandom(min: number, max: number): Promise<number> {
  const range = max - min;
  const buffer = new Uint8Array(4);
  crypto.getRandomValues(buffer);
  const randomValue = new DataView(buffer.buffer).getUint32(0);
  return min + (randomValue % range);
}

// Finding the value of the polynomial at x
function evaluatePolynomial(coefficients: number[], x: number): number {
  return coefficients.reduce(
    (result, coeff, power) => result + coeff * Math.pow(x, power),
    0,
  );
}

// Generates shares based on the secret and threshold
async function generateShares(
  secret: number,
  totalShares: number,
  threshold: number,
) {
  // Generate random coefficients for the polynomial
  const coefficients = [secret];
  for (let i = 1; i < threshold; i++) {
    coefficients.push(await getSecureRandom(1, 1000));
  }

  const usedXValues = new Set<number>();
  const shares = [];

  // Generate unique random x values for shares
  while (shares.length < totalShares) {
    const x = await getSecureRandom(1, 1000);
    if (!usedXValues.has(x)) {
      usedXValues.add(x);
      shares.push({
        x,
        y: evaluatePolynomial(coefficients, x),
      });
    }
  }

  return { shares, coefficients };
}

// Secret Reconstruction from a subset of shares using Lagrange interpolation
function reconstructSecret(shares: Array<{ x: number; y: number }>): number {
  const secret = shares.reduce((sum, share, i) => {
    let product = share.y;
    for (let j = 0; j < shares.length; j++) {
      if (i !== j) {
        product *= shares[j].x / (shares[j].x - share.x);
      }
    }
    return sum + product;
  }, 0);

  return Math.round(secret);
}

const secret = 12345;
const totalShares = 5;
const threshold = 3;

// Generate shares
const { shares, coefficients } = await generateShares(
  secret,
  totalShares,
  threshold,
);
console.log("Generated Shares:", shares);

// Select random subset of shares to reconstruct the secret
const selectedIndices = new Set<number>();
while (selectedIndices.size < threshold) {
  selectedIndices.add(await getSecureRandom(0, totalShares));
}

const selectedShares = Array.from(selectedIndices).map((index) =>
  shares[index]
);
console.log("Selected Shares for Reconstruction:", selectedShares);

// Reconstruct the secret
const reconstructedSecret = reconstructSecret(selectedShares);
console.log("Original Secret:", secret);
console.log("Reconstructed Secret:", reconstructedSecret);

/**
 * @title Upgrade a TCP connection to TLS (STARTTLS)
 * @difficulty intermediate
 * @tags cli
 * @run --allow-net <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.startTls} Doc: Deno.startTls
 * @resource {https://docs.deno.com/examples/tls_connector/} Example: TCP/TLS connector
 * @group Network
 *
 * Some protocols start as plaintext and negotiate encryption mid-connection
 * instead of connecting over TLS from the start. SMTP, IMAP, and Postgres
 * all work this way. Deno.startTls performs that upgrade: it takes an
 * established TCP connection and runs the TLS handshake over it, returning
 * a TlsConn. This example speaks just enough SMTP to a mail server to
 * demonstrate the STARTTLS dance.
 */

// Connect to an SMTP server on the submission port, which expects a
// plaintext greeting before TLS. Helpers for the line-based protocol:
// SMTP commands and replies end with CRLF.
const conn = await Deno.connect({ hostname: "smtp.gmail.com", port: 587 });
const encoder = new TextEncoder();
const decoder = new TextDecoder();
const buffer = new Uint8Array(4096);

async function read(c: Deno.Conn): Promise<string> {
  const n = await c.read(buffer);
  return decoder.decode(buffer.subarray(0, n ?? 0));
}

async function send(c: Deno.Conn, line: string) {
  await c.write(encoder.encode(line + "\r\n"));
}

// The server greets us in plaintext, and EHLO asks what it supports. The
// STARTTLS line in the response advertises that an upgrade is available.
console.log((await read(conn)).split(" ", 2).join(" ")); // 220 smtp.gmail.com
await send(conn, "EHLO localhost");
const features = await read(conn);
console.log(features.includes("STARTTLS")); // true

// Ask for the upgrade. The server answers 220 and from this point on
// expects a TLS handshake on the wire.
await send(conn, "STARTTLS");
console.log((await read(conn)).trim()); // 220 2.0.0 Ready to start TLS

// Deno.startTls wraps the existing connection in TLS. The hostname is used
// to verify the server's certificate, exactly as in Deno.connectTls. The
// original conn must not be used afterwards.
const tlsConn = await Deno.startTls(conn, { hostname: "smtp.gmail.com" });

// The protocol resumes where it left off, now encrypted. RFC 3207 requires
// repeating EHLO after the upgrade because the pre-TLS responses are no
// longer trusted.
await send(tlsConn, "EHLO localhost");
console.log((await read(tlsConn)).split("\r\n")[0]); // 250-smtp.gmail.com at your service

await send(tlsConn, "QUIT");
tlsConn.close();

/**
 * @title Streaming file operations
 * @difficulty intermediate
 * @tags cli
 * @run -R -W <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.open} Doc: Deno.open
 * @resource {https://docs.deno.com/api/deno/~/Deno.FsFile} Doc: Deno.FsFile
 * @group File System
 *
 * Sometimes we need more granular control over file operations.
 * Deno provides a low level interface to file operations that
 * may be used for this purpose.
 */

// For our first example we will demonstrate using a writeable stream.
// To handle any low level file operations we must first open the file.
const output = await Deno.open("example.txt", {
  create: true,
  append: true,
});

// We are now able to obtain a writer from the output.
// This automatically handles closing the file when done.
const outputWriter = output.writable.getWriter();

// Before we do anything with the writer, we should make sure it's ready.
await outputWriter.ready;

// Let's write some text to the file
const outputText = "I love Deno!";
const encoded = new TextEncoder().encode(outputText);
await outputWriter.write(encoded);

// Now we close the write stream (and the file)
await outputWriter.close();

// For our next example, let's read the text from the file!
const input = await Deno.open("example.txt");

// Let's get a reader from the input
const inputReader = input.readable.getReader();
const decoder = new TextDecoder();

// Let's read each chunk from the file
// and print it to the console.
while (true) {
  const result = await inputReader.read();
  if (result.done) {
    break;
  }
  console.log(`Read chunk: ${decoder.decode(result.value)}`);
}

/**
 * @title Convert string case
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://jsr.io/@std/text/doc/~/toCamelCase} Doc: @std/text toCamelCase
 * @resource {https://jsr.io/@std/text/doc/~/toKebabCase} Doc: @std/text toKebabCase
 * @group Standard library
 *
 * Identifiers, file names, CSS classes, and database columns all expect
 * different casing conventions. The @std/text package converts between
 * them from a single input, splitting words on spaces, dashes,
 * underscores, and existing case boundaries.
 */

import {
  toCamelCase,
  toKebabCase,
  toPascalCase,
  toSnakeCase,
} from "jsr:@std/text";

// The same phrase rendered in the four common identifier styles.
const input = "shopping cart total";

console.log(toCamelCase(input)); // shoppingCartTotal
console.log(toKebabCase(input)); // shopping-cart-total
console.log(toSnakeCase(input)); // shopping_cart_total
console.log(toPascalCase(input)); // ShoppingCartTotal

// The converters also understand input that is already cased, so they
// can translate one convention into another.
console.log(toSnakeCase("getUserById")); // get_user_by_id
console.log(toKebabCase("HTTPServerError")); // http-server-error

// Sentence case and title case ship as unstable submodules, so their
// import paths carry an unstable- prefix until they stabilize.
import { toSentenceCase } from "jsr:@std/text/unstable-to-sentence-case";
import { toTitleCase } from "jsr:@std/text/unstable-to-title-case";

console.log(toSentenceCase("shopping cart total")); // Shopping cart total
console.log(toTitleCase("shopping cart total")); // Shopping Cart Total

/**
 * @title Accept payments with Stripe Checkout
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -E <url>
 * @resource {https://docs.stripe.com/checkout/quickstart} Stripe Checkout
 * @resource {https://www.npmjs.com/package/stripe} stripe on npm
 * @group Web frameworks and libraries
 *
 * Stripe Checkout hosts the payment page for you. This server starts a
 * checkout session and redirects the customer to it, then verifies the webhook
 * Stripe sends when payment completes. On Deno, verify with the async
 * constructEventAsync, which uses Web Crypto instead of Node APIs. Set
 * STRIPE_SECRET_KEY, STRIPE_PRICE_ID, and STRIPE_WEBHOOK_SECRET.
 */

import Stripe from "npm:stripe";

const stripe = new Stripe(Deno.env.get("STRIPE_SECRET_KEY")!);

async function handler(req: Request): Promise<Response> {
  const url = new URL(req.url);

  // Start a checkout session and send the customer to Stripe's hosted page.
  if (req.method === "POST" && url.pathname === "/checkout") {
    const session = await stripe.checkout.sessions.create({
      mode: "payment",
      line_items: [{ price: Deno.env.get("STRIPE_PRICE_ID")!, quantity: 1 }],
      success_url: "http://localhost:8000/success",
      cancel_url: "http://localhost:8000/cancel",
    });
    return Response.redirect(session.url!, 303);
  }

  // Stripe calls this URL when events happen. Always verify the signature so
  // you know the request really came from Stripe.
  if (req.method === "POST" && url.pathname === "/webhook") {
    const signature = req.headers.get("stripe-signature")!;
    const body = await req.text();
    let event: Stripe.Event;
    try {
      event = await stripe.webhooks.constructEventAsync(
        body,
        signature,
        Deno.env.get("STRIPE_WEBHOOK_SECRET")!,
      );
    } catch (err) {
      return new Response(`Invalid signature: ${err}`, { status: 400 });
    }

    if (event.type === "checkout.session.completed") {
      const session = event.data.object;
      console.log(`Payment received for session ${session.id}`);
      // Fulfill the order here.
    }
    return new Response("ok");
  }

  return new Response("Not found", { status: 404 });
}

Deno.serve(handler);

/**
 * @title Deep clone objects with structuredClone
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Window/structuredClone} MDN: structuredClone
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API/Structured_clone_algorithm} MDN: Structured clone algorithm
 * @group Web Standard APIs
 *
 * structuredClone deep copies a value, so changes to the copy never leak
 * back into the original. Unlike the JSON round trip trick, it handles
 * Maps, Sets, Dates, typed arrays, and circular references. This example
 * shows what it copies, where it beats JSON, and what it refuses to clone.
 */

// Spread syntax and Object.assign only copy one level deep. structuredClone
// copies the whole tree, so mutating the copy leaves the original alone.
const original = { user: { name: "Ada" }, tags: ["math", "code"] };
const copy = structuredClone(original);

copy.user.name = "Grace";
copy.tags.push("navy");

console.log(original.user.name); // Ada
console.log(copy.user.name); // Grace
console.log(original.tags.length); // 2
console.log(copy.tags.length); // 3

// Built-in types like Map, Set, Date, and Uint8Array survive the clone as
// real instances, not as plain objects or strings.
const record = {
  scores: new Map([["ada", 99]]),
  visited: new Set(["home", "docs"]),
  created: new Date("2024-01-15T00:00:00Z"),
  bytes: new Uint8Array([1, 2, 3]),
};
const recordCopy = structuredClone(record);

console.log(recordCopy.scores instanceof Map); // true
console.log(recordCopy.scores.get("ada")); // 99
console.log(recordCopy.visited.has("docs")); // true
console.log(recordCopy.created.getUTCFullYear()); // 2024
console.log(recordCopy.bytes[2]); // 3

// Circular references are preserved. The copy points at itself exactly
// like the original did.
type TreeNode = { name: string; parent?: TreeNode };
const node: TreeNode = { name: "root" };
node.parent = node;

const nodeCopy = structuredClone(node);
console.log(nodeCopy.parent === nodeCopy); // true

// The JSON round trip cannot do that. It throws on circular values.
try {
  JSON.stringify(node);
} catch (err) {
  console.log((err as Error).name); // TypeError
}

// JSON also silently drops undefined values and functions, which can hide
// bugs. Note how both keys disappear without any error.
const lossy = JSON.parse(JSON.stringify({ a: 1, b: undefined, c: () => 1 }));
console.log(Object.keys(lossy)); // [ "a" ]

// structuredClone is honest instead. Functions cannot be cloned, so it
// throws a DOMException whose name is DataCloneError.
try {
  structuredClone({ run: () => 1 });
} catch (err) {
  console.log((err as DOMException).name); // DataCloneError
}

// Class instances lose their identity. Own data properties are copied,
// but the prototype is not, so methods are gone on the copy.
class Point {
  x: number;
  constructor(x: number) {
    this.x = x;
  }
  double(): number {
    return this.x * 2;
  }
}

const point = structuredClone(new Point(2));
console.log(point.x); // 2
console.log(point instanceof Point); // false
console.log(typeof (point as Point).double); // undefined

/**
 * @title Structured logging
 * @difficulty beginner
 * @tags cli, deploy
 * @run -R -W <url>
 * @resource {https://jsr.io/@std/log} Doc: @std/log
 * @resource {https://jsr.io/@std/log/doc/~/FileHandler} Doc: @std/log FileHandler
 * @group Standard library
 *
 * The @std/log package routes log records through configurable handlers
 * with severity levels. This example sends INFO and above to the
 * console, writes WARN and above to a file as JSON lines, and shows
 * that records below a handler level are filtered out.
 */

import * as log from "jsr:@std/log";

const logFile = "/tmp/structured_logging_example.log";

// A handler decides where records go and which levels it accepts. The
// formatter option customizes the output line, here as JSON without
// timestamps to keep the example deterministic.
const fileHandler = new log.FileHandler("WARN", {
  filename: logFile,
  formatter: (record) =>
    JSON.stringify({ level: record.levelName, message: record.msg }),
});

// Setup wires handlers to the default logger. The console handler only
// accepts INFO and above, and useColors false keeps the output plain.
log.setup({
  handlers: {
    console: new log.ConsoleHandler("INFO", { useColors: false }),
    file: fileHandler,
  },
  loggers: {
    default: { level: "DEBUG", handlers: ["console", "file"] },
  },
});

// This record is below INFO, so neither handler prints or stores it.
log.debug("cache miss for key user:42");

// INFO reaches the console handler but not the WARN file handler.
log.info("server listening on port 8000"); // INFO server listening on port 8000

// WARN and ERROR reach both handlers.
log.warn("disk usage at 81%"); // WARN disk usage at 81%
log.error("upstream timed out"); // ERROR upstream timed out

// The file handler buffers writes, so flush before reading the file.
fileHandler.flush();

const contents = await Deno.readTextFile(logFile);
console.log(contents.trimEnd()); // {"level":"WARN","message":"disk usage at 81%"}
// {"level":"ERROR","message":"upstream timed out"}

// Close the handler and remove the file to clean up.
fileHandler.destroy();
await Deno.remove(logFile);

/**
 * @title Run a subprocess with custom env and cwd
 * @difficulty intermediate
 * @tags cli
 * @run --allow-run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.spawn} Doc: Deno.spawn
 * @resource {https://docs.deno.com/examples/subprocesses_output/} Example: Subprocesses: Collecting output
 * @group System
 *
 * A subprocess normally inherits the environment variables and working
 * directory of its parent. The spawn options can override both, which is
 * useful for passing configuration to a child or running a tool inside a
 * specific directory. The child here is deno eval, so the example is
 * portable.
 */

// Deno.spawn takes the command, its arguments, and options. The env option
// adds variables on top of the inherited environment, and the child's
// stdout stream offers the same convenience methods as a fetch Response.
const withEnv = Deno.spawn(Deno.execPath(), [
  "eval",
  "console.log(Deno.env.get('GREETING'))",
], {
  env: { GREETING: "hello from parent" },
  stdout: "piped",
});
console.log((await withEnv.stdout.text()).trim()); // hello from parent
await withEnv.status;

// With clearEnv set to true the child does not inherit anything, it only
// gets the variables listed in env. Even PATH is gone, so this is best
// combined with an absolute path to the executable. Note that the operating
// system may still inject a few variables of its own.
const cleared = Deno.spawn(Deno.execPath(), [
  "eval",
  "console.log('has PATH:', Deno.env.has('PATH'))",
], {
  env: { GREETING: "hello again" },
  clearEnv: true,
  stdout: "piped",
});
console.log((await cleared.stdout.text()).trim()); // has PATH: false
await cleared.status;

// The cwd option sets the working directory the child starts in. The child
// reports its own Deno.cwd() to prove it. Deno.spawnAndWait runs the
// command to completion and collects everything in one call.
const withCwd = await Deno.spawnAndWait(Deno.execPath(), [
  "eval",
  "console.log(Deno.cwd())",
], {
  cwd: "/",
  stdout: "piped",
});
console.log(new TextDecoder().decode(withCwd.stdout).trim()); // /

// The parent's own working directory is untouched by the child's cwd.
console.log(Deno.cwd() === "/"); // false

// The same options exist on the underlying Deno.Command API, which is the
// right tool when you need to configure a command before spawning it.

/**
 * @title Pipe data into a subprocess
 * @difficulty intermediate
 * @tags cli
 * @run --allow-run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.Command} Doc: Deno.Command
 * @resource {https://docs.deno.com/examples/subprocesses_spawn/} Example: Subprocesses: Spawning
 * @group System
 *
 * Many command line tools read their input from stdin. To drive such a tool
 * from a script, spawn it with a piped stdin and write data into it. This
 * example feeds lines to the sort command and streams text through cat.
 */

// Setting stdin to "piped" makes the child's stdin available as a web
// standard writable stream. The stdout is piped as well so the result can
// be collected.
const sortCommand = new Deno.Command("sort", {
  stdin: "piped",
  stdout: "piped",
});
const sortProcess = sortCommand.spawn();

// Get a writer for the child's stdin and write a few unsorted lines.
const writer = sortProcess.stdin.getWriter();
const encoder = new TextEncoder();
await writer.write(encoder.encode("banana\n"));
await writer.write(encoder.encode("apple\n"));
await writer.write(encoder.encode("cherry\n"));

// Closing the writer closes the child's stdin. This is important: sort waits
// for the end of its input before it prints anything, so forgetting this
// step would hang the program.
await writer.close();

// The child's stdout stream has the same convenience methods as a fetch
// Response, so collecting it as a string is one call.
const sorted = await sortProcess.stdout.text();
console.log(sorted.trim().split("\n")); // [ "apple", "banana", "cherry" ]
await sortProcess.status;

// When the input already exists as a stream or an iterable, skip the manual
// writer and pipe it into stdin in one shot. Deno.spawn is the shorthand
// for spawning: command, arguments, options. ReadableStream.from turns any
// iterable into a stream, and pipeTo closes the child's stdin when the
// stream ends.
const catProcess = Deno.spawn("cat", [], {
  stdin: "piped",
  stdout: "piped",
});

await ReadableStream.from(["hello from a stream\n"])
  .pipeThrough(new TextEncoderStream())
  .pipeTo(catProcess.stdin);

console.log((await catProcess.stdout.text()).trim()); // hello from a stream
await catProcess.status;

/**
 * @title Subprocesses: Collecting output
 * @difficulty intermediate
 * @tags cli
 * @run --allow-run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.Command} Doc: Deno.Command
 * @group System
 *
 * We don't often write programs in isolation. In a lot of cases we want
 * to interact with the outside system and spawning a subprocess is a
 * common way to do this.
 */

// The Deno namespace has a unified api for interacting with the outside system
// called Deno.Command. With it, we can initialize some information about the
// command but it will not be executed immediately.
const command = new Deno.Command("deno", {
  args: [
    "eval",
    "\
    console.log('hello from deno'); \
    console.error('hello from stderr'); \
    ",
  ],
});

// In the most simple case we just want to run the process to completion. This
// can be achieved using command.output()
let result = await command.output();

// It can also be achieved synchronously using command.outputSync()
result = command.outputSync();

// We can now interact with stdout and stderr
const textDecoder = new TextDecoder();
console.log("stdout:", textDecoder.decode(result.stdout));
console.log("stderr:", textDecoder.decode(result.stderr));

/**
 * @title Subprocesses: Spawning
 * @difficulty intermediate
 * @tags cli
 * @run --allow-run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.Command} Doc: Deno.Command
 * @group System
 *
 * For more complex usecases, we don't simply want the output of some
 * command. In this case, we can spawn a subprocess and interact with
 * it using convenience methods for reading output streams.
 */

// The Deno namespace has a unified api for interacting with the outside system
// called Deno.Command. With it, we can initialize some information about the
// command but it will not be executed immediately.
const command = new Deno.Command("deno", {
  args: [
    "fmt",
    "-",
  ],
  stdin: "piped",
  stdout: "piped",
});

// In a slightly more complex case, we want to interact with a spawned
// process. To do this, we first need to spawn it.
const process = command.spawn();

// We can now pipe the input into stdin. To do this we must first get
// a writer from the stream and write to it
const writer = process.stdin.getWriter();
await writer.write(new TextEncoder().encode("console.log('hello')"));
writer.releaseLock();

// We must then close stdin
await process.stdin.close();

// We can now wait for the process to output the results using convenience methods
const stdout = await process.stdout.text();
console.log(stdout);

// Wait for the process to complete
await process.status;

/**
 * @title Connect to Supabase
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N -E <url>
 * @resource {https://supabase.com/docs/reference/javascript/installing} supabase-js docs
 * @resource {https://jsr.io/@supabase/supabase-js} supabase-js on jsr.io
 * @group Databases
 *
 * Connect to a Supabase database with the supabase-js library.
 */

// Import the createClient function from jsr supabase-js package
import { createClient } from "jsr:@supabase/supabase-js@2";

// Create a single supabase client for interacting with your database
const supabase = createClient(
  Deno.env.get("SUPABASE_URL")!,
  Deno.env.get("SUPABASE_KEY")!,
);

// Insert data into the countries table
let resource = await supabase
  .from("countries")
  .insert({ code: "JP", name: "Japan" })
  .select();

if (resource.error) {
  console.error(resource.error);
}

console.log(resource.data); // [ { code: "JP", name: "Japan" } ]

// Get data from the countries table
resource = await supabase
  .from("countries")
  .select();

if (resource.error) {
  console.error(resource.error);
}

console.log(resource.data); // [ { code: "JP", name: "Japan" }, ... ]

/**
 * @title Creating & resolving symlinks
 * @difficulty beginner
 * @tags cli
 * @run -W -R <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.writeTextFile} Doc: Deno.writeTextFile
 * @resource {https://docs.deno.com/api/deno/~/Deno.symlink} Doc: Deno.symlink
 * @group File System
 *
 * Creating and resolving symlink is a common task. Deno has a number of
 * functions for this task.
 */

// First we will create a text file to link to.
await Deno.writeTextFile("example.txt", "hello from symlink!");

// Now we can create a soft link to the file
await Deno.symlink("example.txt", "link");

// To resolve the path of a symlink, we can use Deno.realPath
console.log(await Deno.realPath("link"));

// Symlinks are automatically resolved, so we can just read
// them like text files
console.log(await Deno.readTextFile("link"));

// In certain cases, soft links don't work. In this case we
// can choose to make "hard links".
await Deno.link("example.txt", "hardlink");
console.log(await Deno.readTextFile("hardlink"));

/**
 * @title Create and extract tar archives
 * @difficulty beginner
 * @tags cli, deploy
 * @run -R -W <url>
 * @resource {https://jsr.io/@std/tar} Doc: @std/tar
 * @resource {/examples/compress_decompress/} Example: Compress and decompress data
 * @group File System
 *
 * A tar archive bundles many files and directories into a single file,
 * usually compressed with gzip to produce the familiar .tar.gz format.
 * The Standard Library provides TarStream and UntarStream in jsr:@std/tar,
 * both built on web standard streams so they compose with CompressionStream
 * and file streams without buffering whole archives in memory.
 */
import { TarStream, type TarStreamInput, UntarStream } from "jsr:@std/tar";
import { normalize } from "jsr:@std/path";

// We prepare a directory with two files to archive.
const dir = await Deno.makeTempDir();
await Deno.mkdir(`${dir}/project`);
await Deno.writeTextFile(`${dir}/project/readme.txt`, "A sample project.");
await Deno.writeTextFile(`${dir}/project/config.json`, `{"name":"sample"}`);

// To create an archive, pipe a stream of entries through a TarStream.
// A directory entry only needs a path. A file entry also needs its size
// and a readable stream of its contents. Piping the result through a
// CompressionStream produces a .tar.gz file.
const readmeStat = await Deno.stat(`${dir}/project/readme.txt`);
const configStat = await Deno.stat(`${dir}/project/config.json`);
const archive = await Deno.create(`${dir}/project.tar.gz`);
const inputs: TarStreamInput[] = [
  { type: "directory", path: "project" },
  {
    type: "file",
    path: "project/readme.txt",
    size: readmeStat.size,
    readable: (await Deno.open(`${dir}/project/readme.txt`)).readable,
  },
  {
    type: "file",
    path: "project/config.json",
    size: configStat.size,
    readable: (await Deno.open(`${dir}/project/config.json`)).readable,
  },
];
await ReadableStream.from(inputs)
  .pipeThrough(new TarStream())
  .pipeThrough(new CompressionStream("gzip"))
  .pipeTo(archive.writable);

console.log((await Deno.stat(`${dir}/project.tar.gz`)).size); // 258

// To extract, run the pipeline in reverse: decompress the bytes, then
// pipe them through an UntarStream and iterate over the entries.
const outDir = `${dir}/extracted`;
await Deno.mkdir(outDir);
const tarball = await Deno.open(`${dir}/project.tar.gz`);
const entries = tarball.readable
  .pipeThrough(new DecompressionStream("gzip"))
  .pipeThrough(new UntarStream());

// Directory entries have no readable stream. For file entries, piping the
// readable into a file writes it to disk. Paths inside an archive are not
// trustworthy, so normalize them before touching the file system.
for await (const entry of entries) {
  console.log(entry.path);
  const target = `${outDir}/${normalize(entry.path)}`;
  if (entry.readable === undefined) {
    await Deno.mkdir(target, { recursive: true });
    continue;
  }
  const file = await Deno.create(target);
  await entry.readable.pipeTo(file.writable);
}
//- project
//- project/readme.txt
//- project/config.json

// The extracted files match the originals.
console.log(await Deno.readTextFile(`${outDir}/project/readme.txt`)); // A sample project.
console.log(await Deno.readTextFile(`${outDir}/project/config.json`)); // {"name":"sample"}

// Reading and writing files requires the -R and -W permissions.
await Deno.remove(dir, { recursive: true });

/**
 * @title TCP connector: Ping
 * @difficulty intermediate
 * @tags cli
 * @run -N <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.connect} Doc: Deno.connect
 * @resource {/examples/tcp_listener} Example: TCP Listener
 * @group Network
 *
 * An example of connecting to a TCP server on localhost and writing a 'ping' message to the server.
 */

// Instantiate an instance of text encoder to write to the TCP stream.
const encoder = new TextEncoder();
// Establish a connection to our TCP server that is currently being run on localhost port 8080.
const conn = await Deno.connect({
  hostname: "127.0.0.1",
  port: 8080,
  transport: "tcp",
});
// Encode the 'ping' message and write to the TCP connection for the server to receive.
await conn.write(encoder.encode("ping"));

/**
 * @title TCP Echo Server
 * @difficulty beginner
 * @tags cli
 * @run -N <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.listen} Deno listen API docs
 * @resource {https://docs.deno.com/api/deno/~/Deno.Conn#property_readable} Readable connection API docs
 * @resource {https://docs.deno.com/api/deno/~/Deno.Conn#property_writable} Writable connection docs
 * @group Network
 *
 * An echo server is a simple network application that listens for incoming connections and requests, and then repeats back any data it receives from clients.<br><br>To test this example, try sending data to it with <a href="https://en.wikipedia.org/wiki/Netcat">Netcat</a> (Linux/MacOS only). For example, in your terminal run: <code>echo 'Hello, Deno!' | nc localhost 8080</code>
 */

// Create a TCP listener that listens on port 8080. Log that it is listening.
const listener = Deno.listen({ port: 8080 });
console.log("listening on 0.0.0.0:8080");

// Wait for incoming connections, When a client connects to the server, read data from the client and write it back to the client.
for await (const conn of listener) {
  conn.readable.pipeTo(conn.writable);
}

/**
 * @title TCP listener: Ping
 * @difficulty intermediate
 * @tags cli
 * @run -N <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.listen} Doc: Deno.listen
 * @group Network
 *
 * An example of a TCP listener on localhost that will log the message if written to and close the connection if connected to.
 */

// Instantiate an instance of text decoder to read the TCP stream bytes back into plaintext.
const decoder = new TextDecoder();

// Instantiate an instance of a TCP listener on localhost port 8080.
const listener = Deno.listen({
  hostname: "127.0.0.1",
  port: 8080,
  transport: "tcp",
});
// Await asynchronous connections that are established to our TCP listener.
for await (const conn of listener) {
  // Instantiate an buffer array to store the contents of our read TCP stream.
  const buf = new Uint8Array(1024);
  // Read the contents of the TCP stream into our buffer array.
  await conn.read(buf);
  // Here we log the results of the bytes that were read into our buffer array.
  console.log("Server - received: ", decoder.decode(buf));
  // We close the connection that was established.
  conn.close();
}

/**
 * @title Temporal API
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://docs.deno.com/api/web/~/Temporal} Temporal API reference documentation
 * @resource {https://tc39.es/proposal-temporal/docs} Temporal API proposal documentation
 * @group Web APIs
 *
 * An example of using the Temporal API to work with dates, times, and timestamps.
 */

// Get the current date
const date = Temporal.Now.plainDateISO();

// Return the date in ISO 8601 date format (eg "2025-01-31")
const dateAsString = date.toString();
console.log(`Temporal date as string: ${dateAsString}`);

// Get current date and time in ISO 8601 format (eg "2025-01-31T10:51:40.269979904")
const plainDateTimeIsoString = Temporal.Now.plainDateTimeISO().toString();
console.log(`Temporal plainDateTimeISO as string: ${plainDateTimeIsoString}`);

// Get Unix timestamp (eg 2025-01-31T18:51:59.093355008Z)
const timeStamp = Temporal.Now.instant();
console.log(`Temporal timestamp as string: ${timeStamp}`);

// Return timestamp in milliseconds (eg 1738349519093)
const epochMilliseconds = timeStamp.epochMilliseconds;
console.log(`Temporal timestamp epoch milliseconds: ${epochMilliseconds}`);

// Get date and time in ISO 8601 format from milliseconds (eg "2025-01-31T18:51:59.093Z")
const futureTime = Temporal.Instant.fromEpochMilliseconds(1851222399924);
console.log(`Temporal future time: ${futureTime}`);

// Measure difference in hours from now.
const now = Temporal.Now.instant();
const differenceInHours = now.until(futureTime, { smallestUnit: "hour" });
console.log(`Temporal difference in hours: ${differenceInHours}`);

