/**
 * @title Detect a TTY and get terminal size
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.stdout} Doc: Deno.stdout
 * @resource {https://docs.deno.com/api/deno/~/Deno.consoleSize} Doc: Deno.consoleSize
 * @group System
 *
 * A program can check whether it is talking to a real terminal or to a pipe.
 * This is how command line tools decide to print colors and progress bars
 * for humans, but plain machine readable text when their output is piped to
 * another program or a file.
 */

// isTerminal reports whether a standard stream is attached to a terminal.
// Run directly in a terminal, both lines print true. Run piped, as in
// deno run terminal_detection.ts | cat, stdin stays attached to the
// terminal but stdout is now a pipe, so the second line prints false.
console.log(`stdin is a terminal: ${Deno.stdin.isTerminal()}`); // stdin is a terminal: true
console.log(`stdout is a terminal: ${Deno.stdout.isTerminal()}`); // stdout is a terminal: false (when piped; true in a terminal)

// Code written for Node.js checks the isTTY property of the process
// streams, which works in Deno and gives the same answer.
import process from "node:process";
console.log(`process.stdout.isTTY: ${process.stdout.isTTY}`); // undefined when piped; true in a terminal

// Deno.consoleSize returns the current size of the terminal window. It
// throws when no standard stream is attached to a terminal, for example in
// CI, so wrap it in a try/catch.
try {
  const { columns, rows } = Deno.consoleSize();
  console.log(`terminal size: ${columns}x${rows}`); // e.g. terminal size: 120x40
} catch {
  console.log("no terminal attached");
}

// The practical use: pick human friendly output only when stdout really is
// a terminal. Here ANSI color codes are skipped when the output is piped,
// so downstream programs receive clean text.
const useColor = Deno.stdout.isTerminal();
const status = useColor ? "\x1b[32mok\x1b[0m" : "ok";
console.log(status); // ok (shown in green in a terminal, plain when piped)

/**
 * @title Filtering and controlling test runs
 * @difficulty beginner
 * @tags cli
 * @run deno test <url>
 * @resource {https://docs.deno.com/runtime/reference/cli/test/} Doc: deno test
 * @resource {/examples/tests_skip_focus/} Example: Skipping and focusing tests
 * @group Testing
 *
 * The test runner has flags for the everyday loops: run one test by name,
 * stop at the first failure, rerun on save, and spread test files across
 * CPU cores. This example demonstrates each on a small test file.
 */
import { assertEquals } from "jsr:@std/assert";

Deno.test("addition", () => {
  assertEquals(1 + 1, 2);
});

Deno.test("subtraction", () => {
  assertEquals(2 - 1, 1);
});

Deno.test("async work completes in time", async () => {
  // There is no built-in per-test timeout, so race the work against a
  // deadline. Clearing the timer keeps the sanitizers happy.
  await withTimeout(Promise.resolve("done"), 1000);
});

function withTimeout<T>(work: Promise<T>, ms: number): Promise<T> {
  let timer: ReturnType<typeof setTimeout>;
  const deadline = new Promise<never>((_, reject) => {
    timer = setTimeout(() => reject(new Error(`timed out after ${ms}ms`)), ms);
  });
  return Promise.race([work, deadline]).finally(() => clearTimeout(timer));
}

// Run a single test by part of its name with --filter. Wrapping the value
// in slashes treats it as a regular expression:
//
//   deno test --filter "addition" control.test.ts
//   ok | 1 passed | 0 failed | 2 filtered out
//
//   deno test --filter "/add|sub/" control.test.ts

// Stop at the first failure with --fail-fast, or after N failures with
// --fail-fast=N. Without it, the runner reports every failure:
//
//   deno test --fail-fast control.test.ts

// Rerun tests automatically whenever a file in the module graph changes:
//
//   deno test --watch control.test.ts

// Run test FILES in parallel across CPU cores. Tests inside one file still
// run sequentially; the DENO_JOBS environment variable controls the worker
// count:
//
//   deno test --parallel
//   DENO_JOBS=4 deno test --parallel

/**
 * @title Skipping and focusing tests
 * @difficulty beginner
 * @tags cli
 * @run deno test <url>
 * @resource {https://docs.deno.com/runtime/fundamentals/testing/} Doc: Testing
 * @resource {/examples/writing_tests/} Example: Writing tests
 * @group Testing
 *
 * Sometimes a test should not run: it is half-written, broken on one
 * platform, or you want to focus on a single failing case. This example
 * shows how to skip and focus tests.
 */
import { assertEquals } from "jsr:@std/assert";

// A regular test, for comparison.
Deno.test("addition", () => {
  assertEquals(1 + 1, 2);
});

// To skip a test, set the ignore option. The test is reported as ignored
// rather than silently dropped, so it stays visible as a todo.
Deno.test({
  name: "subtraction",
  ignore: true,
  fn() {
    assertEquals(2 - 1, 1);
  },
});

// The shorthand reads nicely when there is no other option to set.
Deno.test.ignore("multiplication", () => {
  assertEquals(2 * 2, 4);
});

// The ignore option takes any boolean, which makes platform-specific or
// environment-specific skips one-liners.
Deno.test({
  name: "windows paths",
  ignore: Deno.build.os !== "windows",
  fn() {
    // Only runs on Windows.
  },
});

// Running the file reports each skipped test:
//
//   deno test skip.test.ts
//   ok | 1 passed | 0 failed | 3 ignored

// To focus on one test, use only. Every other test in the run is filtered
// out:
//
//   Deno.test.only("focus on this", () => {});
//
// As a guard against forgotten focus markers, the run itself fails after
// the tests pass:
//
//   ok | 1 passed | 0 failed | 1 filtered out
//   error: Test failed because the "only" option was used

// To pick tests at run time instead of in code, use the --filter flag; see
// the test runner documentation for the full options.

/**
 * @title Timeouts & intervals
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Window/setTimeout} MDN: setTimeout
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Window/setInterval} MDN: setInterval
 * @group Basics
 *
 * Timers are used to schedule functions to happen at a later time.
 */

// Here we create a timer that will print "Hello, World!" to the console after
// 1 second (1000 milliseconds).
setTimeout(() => console.log("Hello, World!"), 1000);

// You can also cancel a timer after it has been created.
const timerId = setTimeout(() => console.log("No!"), 1000);
