/**
 * @title Manipulating & parsing URLs
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/URL} MDN: URL
 * @group Basics
 *
 * URL is the web standard interface to parse and manipulate URLs.
 */

// We can create a new object in a variety of ways
// In the most simple case we can simply just write the whole url
let url = new URL("https://deno.land/manual/introduction");

// Alternatively we are able to pass a (relative) url which will
// be automatically resolved to an absolute url
url = new URL("/manual/introduction", "https://deno.land");

// To get the full url out of an object, we can check the href property
console.log(url.href); // https://deno.land/manual/introduction

// We are also able to get various other properties from the url.
// Here are a few examples of properties we have access to.
console.log(url.host); // deno.land
console.log(url.origin); // https://deno.land
console.log(url.pathname); // /manual/introduction
console.log(url.protocol); // https:

// When parsing a url we often need to read the search parameters.
url = new URL("https://docs.deno.com/api/deno?s=Deno.readFile");

console.log(url.searchParams.get("s")); // Deno.readFile

// We're able to manipulate any of these parameters on the fly
url.host = "deno.com";
url.protocol = "http:";

console.log(url.href); // http://deno.com/api?s=Deno.readFile

/**
 * @title Match URLs with URLPattern
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/URLPattern} MDN: URLPattern
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/URL_Pattern_API} MDN: URL Pattern API
 * @group Web Standard APIs
 *
 * URLPattern matches URLs against route-style patterns and extracts the
 * dynamic parts. It is the same syntax used by many web routers, built
 * directly into the platform. This example matches pathnames, reads named
 * groups, and builds a tiny router on top of it.
 */

// A pattern component named with a colon, like :id, matches one path
// segment and captures it under that name. Components that are not
// specified, like protocol and hostname, default to wildcards.
const pattern = new URLPattern({ pathname: "/users/:id" });

// The test method returns a boolean and is useful for quick checks.
console.log(pattern.test("https://example.com/users/123")); // true
console.log(pattern.test("https://example.com/posts/123")); // false

// The exec method returns a result object, or null when there is no match.
// Each URL component has its own groups object with the captured values.
const match = pattern.exec("https://example.com/users/123");
console.log(match?.pathname.groups.id); // 123

// A wildcard written as * matches across segment boundaries. Unnamed
// wildcards are captured under numeric keys, starting at 0.
const assets = new URLPattern({ pathname: "/static/*" });
const asset = assets.exec("https://example.com/static/css/site.css");
console.log(asset?.pathname.groups[0]); // css/site.css

// Patterns can also match the search and hash components. The leading ?
// and # characters are not part of the pattern.
const paged = new URLPattern({ search: "page=:page" });
console.log(paged.exec("https://example.com/list?page=4")?.search.groups.page); // 4

const section = new URLPattern({ hash: "section-:name" });
console.log(
  section.exec("https://example.com/docs#section-install")?.hash.groups.name,
); // install

// A router is just an ordered list of pattern and handler pairs. The first
// pattern that matches wins and receives the captured groups.
type Handler = (groups: Record<string, string | undefined>) => string;

const routes: [URLPattern, Handler][] = [
  [new URLPattern({ pathname: "/" }), () => "home page"],
  [new URLPattern({ pathname: "/users/:id" }), (g) => `user ${g.id}`],
  [
    new URLPattern({ pathname: "/users/:id/posts/:post" }),
    (g) => `post ${g.post} by user ${g.id}`,
  ],
];

function route(url: string): string {
  for (const [pattern, handler] of routes) {
    const result = pattern.exec(url);
    if (result) return handler(result.pathname.groups);
  }
  return "404 not found";
}

// In a real server the URL would come from the incoming request. Calling
// the lookup function directly shows the same logic without a server.
console.log(route("https://example.com/")); // home page
console.log(route("https://example.com/users/42")); // user 42
console.log(route("https://example.com/users/42/posts/7")); // post 7 by user 42
console.log(route("https://example.com/about")); // 404 not found

/**
 * @title Generating & validating UUIDs
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Crypto/randomUUID} MDN: crypto.randomUUID
 * @resource {https://jsr.io/@std/uuid/doc} Doc: @std/uuid
 * @group Cryptography
 *
 * UUIDs (universally unique identifier) can be used to uniquely identify some
 * object or data.
 */

// A random UUID can be generated using the builtin Web Cryptography API. This
// type of UUID is also known as UUID v4.
const myUUID = crypto.randomUUID();
console.log("Random UUID:", myUUID);

// The standard library contains some more functions for working with UUIDs.
import * as uuid from "jsr:@std/uuid";

// You can validate that a given string is a valid UUID.
console.log(uuid.validate("not a UUID")); // false
console.log(uuid.validate("6ec0bd7f-11c0-43da-975e-2a8ad9ebae0b")); // true

// You can also generate a time-based (v1) UUID. By default this uses system
// time as the time source.
console.log(uuid.v1.generate());

// SHA-1 namespaced (v5) UUIDs can also be generated. For this you need
// to specify a namespace and data:
const NAMESPACE_URL = "6ba7b810-9dad-11d1-80b4-00c04fd430c8";
const data = new TextEncoder().encode("deno.land");
console.log(await uuid.v5.generate(NAMESPACE_URL, data));

/**
 * @title Walking directories
 * @difficulty beginner
 * @tags cli
 * @run -R <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.readDir} Doc: Deno.readDir
 * @resource {https://jsr.io/@std/fs/doc/walk/~} Doc: @std/fs/walk
 * @group File System
 *
 * When doing something like filesystem routing, it is
 * useful to be able to walk down a directory to visit
 * files.
 */

// If the directory has no depth (no folders), we can use
// the built-in Deno.readDir
for await (const dirEntry of Deno.readDir(".")) {
  console.log("Basic listing:", dirEntry.name);
}

// If on the other hand you need to recursively walk
// a repository, the standard library has a method for this.
// In the most simple case it is a drop-in replacement
import { walk } from "jsr:@std/fs/walk";

for await (const dirEntry of walk(".")) {
  console.log("Recursive walking:", dirEntry.name);
}

// We are also able to specify some settings to customize
// our results. In the case of building filesystem routing
// limiting results to only certain extensions may be useful
for await (const dirEntry of walk(".", { exts: ["ts"] })) {
  console.log("Recursive walking with extension:", dirEntry.name);
}

/**
 * @title Watching the filesystem
 * @difficulty beginner
 * @tags cli
 * @run -R <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.watchFs} Doc: Deno.watchFs
 * @resource {https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Statements/for-await...of} MDN: for await of
 * @resource {https://jsr.io/@std/async/doc/debounce/~} Doc: @std/async/debounce
 * @group File System
 *
 * When creating frameworks or CLI tools, it is often necessary to watch the filesystem for changes.
 */
// The easiest way to watch a filesystem is to use the Deno builtin watchFs.
// Deno.watchFs returns an FsWatcher which is an async iterable.
let watcher = Deno.watchFs("./");

// The easiest way to interact with async iterables is the javascript for await of syntax.
for await (const event of watcher) {
  console.log(">>>> event", event);

  // To stop the watcher we can simply call `watcher.close()`
  watcher.close();
}

// In real applications, it is quite rare that an application needs to react
// to every change instantly. Events will be duplicated and multiple events will
// be dispatched for the same changes. To get around this, we can "debounce" our
// functions.
import { debounce } from "jsr:@std/async/debounce";

// In this specific case, we use the standard library to do the work for us.
// This function will run at most once every two hundred milliseconds
const log = debounce((event: Deno.FsEvent) => {
  console.log("[%s] %s", event.kind, event.paths[0]);
}, 200);

watcher = Deno.watchFs("./");

for await (const event of watcher) {
  log(event);
}

/**
 * @title Cache HTTP responses with the Web Cache API
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run -N <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Cache} MDN: Cache
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/CacheStorage} MDN: CacheStorage
 * @group Web Standard APIs
 *
 * Deno implements the Web Cache API from service workers. The caches
 * global stores Response objects keyed by request URL, persisted on disk
 * between runs, and the same code works on Deno Deploy. This example
 * starts a local server that counts requests, then proves a cached fetch
 * helper only hits the server once.
 */

// This server counts how many requests actually reach it. Port 0 asks
// the operating system for any free port.
let requestCount = 0;
const server = Deno.serve({ port: 0, onListen: () => {} }, () => {
  requestCount++;
  return new Response(JSON.stringify({ message: "hello" }), {
    headers: { "content-type": "application/json" },
  });
});

// caches.open returns a named cache, creating it on first use. No extra
// permission flags are needed for the cache itself.
const cache = await caches.open("example-cache-v1");

// The helper tries the cache first and falls back to the network. A
// response body can be read only once, so store a clone and return the
// original.
async function cachedFetch(url: string): Promise<Response> {
  const cached = await cache.match(url);
  if (cached) {
    return cached;
  }
  const response = await fetch(url);
  await cache.put(url, response.clone());
  return response;
}

// The first call misses the cache and reaches the server.
const url = `http://localhost:${server.addr.port}/data`;
const first = await cachedFetch(url);
console.log(await first.json()); // { message: "hello" }

// The second call is served from the cache.
const second = await cachedFetch(url);
console.log(await second.json()); // { message: "hello" }

// The server saw exactly one request, so the cache really answered the
// second call.
console.log(requestCount); // 1

// cache.delete removes a single entry, caches.delete removes the whole
// named cache. Both return whether something was deleted.
console.log(await cache.delete(url)); // true
console.log(await caches.delete("example-cache-v1")); // true

await server.shutdown();

/**
 * @title Connect two peers with WebTransport
 * @difficulty intermediate
 * @tags cli
 * @run --unstable-net --allow-net --allow-read <url>
 * @resource {https://docs.deno.com/api/web/~/WebTransport} Doc: WebTransport
 * @resource {https://docs.deno.com/api/deno/~/Deno.upgradeWebTransport} Doc: Deno.upgradeWebTransport
 * @group Network
 *
 * <strong>Warning: This is an unstable API that is subject to change or removal at any time.</strong><br>WebTransport is the web platform's API for low-latency, multiplexed
 * communication over HTTP/3. Browsers can use it where raw QUIC and TCP
 * sockets are unavailable, and unlike WebSockets it offers many independent
 * streams plus unreliable datagrams. Deno provides both the client API and,
 * via Deno.upgradeWebTransport, the server side. This example runs both in
 * one process.
 *
 * WebTransport runs over QUIC, which always requires TLS. Generate a local
 * self-signed certificate with:
 * <code>openssl req -x509 -newkey rsa:2048 -keyout server.key -out server.crt -days 14 -nodes -subj "/CN=localhost" -addext "subjectAltName=DNS:localhost" -addext "basicConstraints=critical,CA:FALSE"</code>
 */

const cert = Deno.readTextFileSync("./server.crt");
const key = Deno.readTextFileSync("./server.key");

// The server side is a QUIC endpoint speaking the HTTP/3 ALPN protocol.
// Deno.upgradeWebTransport performs the WebTransport handshake on an
// accepted QUIC connection.
const endpoint = new Deno.QuicEndpoint({ hostname: "localhost", port: 4433 });
const listener = endpoint.listen({ cert, key, alpnProtocols: ["h3"] });

(async () => {
  for await (const incoming of listener) {
    const conn = await incoming.accept();
    const transport = await Deno.upgradeWebTransport(conn);
    await transport.ready;
    // Echo the first message on each incoming bidirectional stream.
    const { value: stream } = await transport.incomingBidirectionalStreams
      .getReader().read();
    if (!stream) continue;
    const { value } = await stream.readable.getReader().read();
    const writer = stream.writable.getWriter();
    await writer.write(value);
    await writer.close();
  }
})();

// Browsers normally require a certificate signed by a real CA, but
// serverCertificateHashes lets a client trust a specific self-signed
// certificate by the SHA-256 hash of its DER encoding. This is the
// standard way to develop locally with WebTransport.
const der = Deno.readFileSync("./server.der"); // openssl x509 -in server.crt -outform der -out server.der
const certHash = await crypto.subtle.digest("SHA-256", der);

const transport = new WebTransport("https://localhost:4433", {
  serverCertificateHashes: [{ algorithm: "sha-256", value: certHash }],
});
await transport.ready;

// Streams work like their QUIC counterparts: open a bidirectional stream,
// write, and read the echo back.
const stream = await transport.createBidirectionalStream();
const writer = stream.writable.getWriter();
await writer.write(new TextEncoder().encode("hello WebTransport"));
const { value } = await stream.readable.getReader().read();
console.log(new TextDecoder().decode(value)); // hello WebTransport

transport.close();
endpoint.close();

/**
 * @title Web workers
 * @difficulty intermediate
 * @tags cli, web
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API/Using_web_workers} MDN: Web Workers
 * @resource {https://docs.deno.com/api/web/~/Worker/} API: Worker
 * @group Advanced
 *
 * Workers are the only way of running javascript off of the main thread.
 * This can be useful for a wide variety of programs, especially those where
 * there is a lot of computation that needs to be done without blocking a
 * thread. This example is not runnable on its own; the worker expects
 * separate `worker.ts` and log files, so it is meant to be read rather than
 * executed directly.
 */

// File: ./worker.ts

// First we will define a web worker, we can receive messages from the main
// thread and do some processing as a result of them.
self.onmessage = async (e) => {
  const { filename } = e.data;
  const text = await Deno.readTextFile(filename);
  console.log(text);
  self.close();
};

// File: ./main.ts

// Currently, Deno only supports module-type workers. To instantiate one
// we can use similar syntax to what is found on the web.
const worker = new Worker(
  new URL("./worker.ts", import.meta.url).href,
  {
    type: "module",
  },
);

// We can send a message to the worker by using the `postMessage` method
worker.postMessage({ filename: "./log.txt" });

// By default the worker inherits the permissions of the thread it was
// instantiated from. We can give workers certain permissions by using
// the deno.permissions option.
const worker2 = new Worker(
  new URL("./worker.ts", import.meta.url).href,
  {
    type: "module",
    deno: {
      permissions: {
        read: [
          new URL("./file_1.txt", import.meta.url),
          new URL("./file_2.txt", import.meta.url),
        ],
      },
    },
  },
);

// Because we instantiated this worker with specific permissions, this will
// cause the worker to try to read a file it doesn't have access to and thus
// will throw a permission error.
worker2.postMessage({ filename: "./log.txt" });

/**
 * @title Web assembly
 * @difficulty intermediate
 * @tags cli, deploy, web
 * @run <url>
 * @resource {https://webassembly.github.io/spec/core/syntax/modules.html} WebAssembly Spec: Modules
 * @resource {https://webassembly.github.io/spec/core/syntax/instructions.html} WebAssembly Spec: Instructions
 * @resource {https://webassembly.github.io/spec/core/syntax/values.html} WebAssembly Spec: Values
 * @resource {https://webassembly.github.io/spec/core/syntax/types.html} WebAssembly Spec: Types
 * @group Advanced
 *
 * WebAssembly is a binary format for describing a program's data and instructions.
 * It is a new and more efficient binary format.
 */

// We create a new Uint8Array with the bytes of the WebAssembly module.
// This is usually the output of some compiler and not written by hand.
// deno-fmt-ignore
const bytes = new Uint8Array([
  0,97,115,109,1,0,0,0,1,7,1,96,2,
  127,127,1,127,2,1,0,3,2,1,0,4,1,
  0,5,1,0,6,1,0,7,7,1,3,97,100,100,
  0,0,9,1,0,10,10,1,8,0,32,0,32,1,
  106,15,11,11,1,0,
]);
// We create an interface for the WebAssembly module containing all exports.
interface WebAssemblyExports {
  add(a: number, b: number): number;
}
// The WebAssembly module is a binary format for describing a program's data and instructions.
const exports = await WebAssembly.instantiate(bytes);
// We get the exports from the WebAssembly module and cast it to the interface.
const functions = exports.instance.exports as unknown as WebAssemblyExports;
// We call the exported function.
console.log(functions.add(1, 2)); // 3

/**
 * @title Run a compute shader with WebGPU
 * @difficulty intermediate
 * @tags cli
 * @run <url>
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/WebGPU_API} MDN: WebGPU API
 * @resource {https://www.w3.org/TR/WGSL/} WGSL specification
 * @group Web standard APIs
 *
 * WebGPU gives JavaScript direct access to the GPU, and unlike WebGL it is
 * not limited to graphics: compute shaders run arbitrary parallel
 * computation. Deno implements the WebGPU API natively, so the same code
 * that runs in the browser runs on the command line. This example doubles
 * an array of floats on the GPU.
 */

// Request an adapter (a physical GPU) and a device (a logical connection
// to it). On machines without a GPU, requestAdapter resolves to null.
const adapter = await navigator.gpu.requestAdapter();
if (!adapter) throw new Error("No GPU adapter found");
const device = await adapter.requestDevice();

// Compute shaders are written in WGSL. This one reads and writes a storage
// buffer; each invocation handles one element, and the workgroup size
// controls how many invocations run together.
const shader = `
@group(0) @binding(0) var<storage, read_write> data: array<f32>;

@compute @workgroup_size(64)
fn main(@builtin(global_invocation_id) id: vec3u) {
  if (id.x < arrayLength(&data)) {
    data[id.x] = data[id.x] * 2.0;
  }
}`;

// Compile the shader and build a compute pipeline around its entry point.
const module = device.createShaderModule({ code: shader });
const pipeline = device.createComputePipeline({
  layout: "auto",
  compute: { module },
});

// Upload the input data into a storage buffer on the GPU.
const input = new Float32Array([1, 2, 3, 4]);
const storageBuffer = device.createBuffer({
  size: input.byteLength,
  usage: GPUBufferUsage.STORAGE | GPUBufferUsage.COPY_SRC |
    GPUBufferUsage.COPY_DST,
});
device.queue.writeBuffer(storageBuffer, 0, input);

// GPU buffers cannot be read directly from JavaScript, so create a second
// buffer that can be mapped for reading and will receive a copy of the
// results.
const readBuffer = device.createBuffer({
  size: input.byteLength,
  usage: GPUBufferUsage.COPY_DST | GPUBufferUsage.MAP_READ,
});

// Bind the storage buffer to the shader's binding 0, then record the
// commands: run the pipeline with enough workgroups to cover the array,
// and copy the results into the readable buffer.
const bindGroup = device.createBindGroup({
  layout: pipeline.getBindGroupLayout(0),
  entries: [{ binding: 0, resource: { buffer: storageBuffer } }],
});
const encoder = device.createCommandEncoder();
const pass = encoder.beginComputePass();
pass.setPipeline(pipeline);
pass.setBindGroup(0, bindGroup);
pass.dispatchWorkgroups(Math.ceil(input.length / 64));
pass.end();
encoder.copyBufferToBuffer(storageBuffer, 0, readBuffer, 0, input.byteLength);

// Submit the work to the GPU queue, then map the read buffer to pull the
// results back into JavaScript.
device.queue.submit([encoder.finish()]);
await readBuffer.mapAsync(GPUMapMode.READ);
const output = new Float32Array(readBuffer.getMappedRange());
console.log([...output]); // [ 2, 4, 6, 8 ]

/**
 * @title Outbound WebSockets
 * @difficulty beginner
 * @tags cli, deploy, web
 * @run -N <url>
 * @resource {/examples/http_server_websocket} HTTP Server: WebSockets
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/WebSocket} MDN: WebSocket
 * @group Network
 *
 * Opening a WebSocket connection for real-time, bi-directional communication with Deno is very simple.
 */

// First we need to use the WebSocket constructor to initiate
// our connection to an external server
const socket = new WebSocket("ws://localhost:8000");

// Before we do anything with the websocket, we should
// wait to make sure that we are connected. We can do
// so by listening to the "open" event.
socket.addEventListener("open", () => {
  // We can read the "ready state" of our instance.
  // This determines if we are able to send messages.
  // The ready state for open should be 1.
  console.log(socket.readyState);

  // We can now send messages to the server. The messages
  // can be of the type string, ArrayBuffer, Blob, or
  // TypedArray. In this case we will be sending a string
  socket.send("ping");
});

// We can handle messages back from the server by listening
// to the "message" event. We can read the data sent by
// the server using the data property of the event.
socket.addEventListener("message", (event) => {
  console.log(event.data);
});

/**
 * @title WebSocket server: Per-socket state
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.upgradeWebSocket} Doc: Deno.upgradeWebSocket
 * @resource {/examples/websocket_pubsub/} Example: WebSocket server: Broadcasting messages
 * @group Network
 *
 * Most WebSocket servers need to know who each socket belongs to: a
 * username, a room, a session. This example attaches state to every
 * connection and uses it when handling messages.
 */

// State for one connection. The upgrade request is the natural place to
// pull it from: query parameters, cookies, or an auth header.
interface Session {
  username: string;
  joined: Date;
}

const sessions = new Map<WebSocket, Session>();

Deno.serve((req) => {
  if (req.headers.get("upgrade") !== "websocket") {
    return new Response("This endpoint expects a WebSocket", { status: 426 });
  }
  const { socket, response } = Deno.upgradeWebSocket(req);

  // Read the username from the connection URL, e.g. /?username=ada.
  const username = new URL(req.url).searchParams.get("username") ?? "guest";

  // Each handler closes over this connection's socket, and the Map lets
  // any other part of the server look the session up later.
  socket.onopen = () => {
    sessions.set(socket, { username, joined: new Date() });
    socket.send(`welcome, ${username}`);
  };

  socket.onmessage = (event) => {
    const session = sessions.get(socket)!;
    socket.send(`${session.username} said: ${event.data}`);
  };

  socket.onclose = () => {
    sessions.delete(socket);
  };

  return response;
});

// Connecting with a username tags every reply:
//
//   const ws = new WebSocket("ws://localhost:8000/?username=ada");
//   ws.onmessage = (event) => console.log(event.data);
//   ws.onopen = () => ws.send("hi");
//
//   welcome, ada
//   ada said: hi

// Note that Deno's WebSocket upgrade does not negotiate per-message
// compression; large payloads are sent as-is, so compress them yourself if
// it matters.

/**
 * @title WebSocket server: Broadcasting messages
 * @difficulty intermediate
 * @tags cli, deploy
 * @run -N <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.upgradeWebSocket} Doc: Deno.upgradeWebSocket
 * @resource {/examples/http_server_websocket/} Example: HTTP server: WebSockets
 * @group Network
 *
 * Chat rooms, live dashboards, and multiplayer games all need one thing:
 * deliver a message from one client to all the others. This example keeps
 * track of connected sockets and broadcasts every message it receives.
 */

// All currently connected clients. A Set handles disconnects cleanly.
const clients = new Set<WebSocket>();

function broadcast(message: string) {
  for (const client of clients) {
    // A socket may be mid-handshake or closing; only send when open.
    if (client.readyState === WebSocket.OPEN) {
      client.send(message);
    }
  }
}

Deno.serve((req) => {
  if (req.headers.get("upgrade") !== "websocket") {
    return new Response("This endpoint expects a WebSocket", { status: 426 });
  }
  const { socket, response } = Deno.upgradeWebSocket(req);

  // Register the socket once the connection is established, and clean up
  // when it goes away for any reason.
  socket.onopen = () => {
    clients.add(socket);
    broadcast(`${clients.size} clients connected`);
  };
  socket.onclose = () => {
    clients.delete(socket);
    broadcast(`${clients.size} clients connected`);
  };

  // Relay each incoming message to everyone, including the sender.
  socket.onmessage = (event) => {
    broadcast(event.data);
  };

  return response;
});

// Connect two clients from another terminal and every message appears in
// both:
//
//   const ws = new WebSocket("ws://localhost:8000/");
//   ws.onmessage = (event) => console.log(event.data);
//   ws.onopen = () => ws.send("hello, everyone");

// This state lives in one worker. To broadcast across the workers of
// deno serve --parallel, relay each message through a BroadcastChannel,
// which reaches the other workers; on Deno Deploy it reaches the other
// instances too.
//
//   const relay = new BroadcastChannel("chat");
//   relay.onmessage = (event) => broadcast(event.data);
//   socket.onmessage = (event) => {
//     broadcast(event.data);
//     relay.postMessage(event.data);
//   };
//
// Separate processes and machines do not share a BroadcastChannel; for
// those, relay through something external like Deno KV watch or a Redis
// channel.

/**
 * @title Two-way streaming with WebSocketStream
 * @difficulty intermediate
 * @tags cli
 * @run --unstable-net --allow-net <url>
 * @resource {https://docs.deno.com/api/web/~/WebSocketStream} Doc: WebSocketStream
 * @resource {https://docs.deno.com/examples/websocket/} Example: Outbound WebSockets
 * @group Network
 *
 * <strong>Warning: This is an unstable API that is subject to change or removal at any time.</strong><br>WebSocketStream is a promise-based alternative to the event-based
 * WebSocket API. It exposes the connection as a pair of web streams, which
 * brings backpressure and async iteration to WebSocket code and composes
 * with everything else that speaks ReadableStream and WritableStream.
 */

// Start a WebSocket echo server to talk to. The server side uses the
// standard Deno.upgradeWebSocket, so only the client below needs the
// unstable WebSocketStream API.
const server = Deno.serve({ port: 8000 }, (req) => {
  const { socket, response } = Deno.upgradeWebSocket(req);
  socket.onmessage = (event) => socket.send(`echo: ${event.data}`);
  return response;
});

// Connect with WebSocketStream. Instead of waiting for an open event, you
// await the opened promise, which resolves with the readable and writable
// ends of the connection once the handshake completes.
const wss = new WebSocketStream("ws://localhost:8000");
const { readable, writable } = await wss.opened;

// Send messages by writing to the writable stream.
const writer = writable.getWriter();
await writer.write("hello");
await writer.write("world");

// Receive messages by reading from the readable stream. Backpressure works
// the way it does in any web stream: if you stop reading, the other side
// is eventually told to stop sending.
const reader = readable.getReader();
console.log((await reader.read()).value); // echo: hello
console.log((await reader.read()).value); // echo: world

// Closing takes an optional code and reason, and the closed promise
// resolves with the code and reason the connection closed with.
wss.close({ code: 1000, reason: "done" });
console.log(await wss.closed); // { closeCode: 1000, reason: "done" }

await server.shutdown();

/**
 * @title Distribute work across a worker pool
 * @difficulty intermediate
 * @tags cli
 * @resource {https://docs.deno.com/examples/web_workers/} Example: Web workers
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/Web_Workers_API/Using_web_workers} MDN: Using web workers
 * @group Web standard APIs
 *
 * A single web worker moves heavy computation off the main thread, but a
 * pool of workers uses every CPU core. The pattern: spawn one worker per
 * core, feed each a task, and hand out the next task whenever a worker
 * reports back. This example counts primes below several limits in
 * parallel.
 */

// File: ./worker.ts

// The worker receives a number, does the CPU-heavy counting, and posts
// the result back. Workers process messages one at a time, which is what
// makes "send the next task when a result arrives" work.
self.onmessage = (e: MessageEvent<number>) => {
  const limit = e.data;
  let count = 0;
  for (let i = 2; i <= limit; i++) {
    let isPrime = true;
    for (let j = 2; j * j <= i; j++) {
      if (i % j === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) count++;
  }
  self.postMessage({ limit, count });
};

// File: ./main.ts

// A queue of independent tasks, more than we have cores.
const tasks = [1e6, 2e6, 3e6, 4e6, 5e6, 6e6, 7e6, 8e6];
const results: { limit: number; count: number }[] = [];

// navigator.hardwareConcurrency reports the number of logical cores.
// Spawning more workers than that only adds scheduling overhead.
const poolSize = Math.min(navigator.hardwareConcurrency, tasks.length);
console.log(`pool size: ${poolSize}`); // pool size: 8

// Each worker runs a loop expressed with messages: assign a task, wait
// for the result, assign the next. When the queue is empty the worker is
// terminated and its slot resolves.
let nextTask = 0;
await Promise.all(
  Array.from({ length: poolSize }, () => {
    const worker = new Worker(new URL("./worker.ts", import.meta.url), {
      type: "module",
    });
    return new Promise<void>((resolve) => {
      const assign = () => {
        if (nextTask >= tasks.length) {
          worker.terminate();
          resolve();
          return;
        }
        worker.postMessage(tasks[nextTask++]);
      };
      worker.onmessage = (e) => {
        results.push(e.data);
        assign();
      };
      assign();
    });
  }),
);

// Results arrive in completion order, not submission order, so sort them
// if order matters. On an 8-core machine this runs roughly 4x faster
// than the same loop on the main thread.
results.sort((a, b) => a.limit - b.limit);
console.log(results[0]); // { limit: 1000000, count: 78498 }
console.log(results.at(-1)); // { limit: 8000000, count: 539777 }

/**
 * @title Use worker_threads in Deno
 * @difficulty intermediate
 * @tags cli
 * @run --allow-read <url>
 * @resource {https://docs.deno.com/api/node/worker_threads/} Doc: node:worker_threads
 * @resource {https://docs.deno.com/examples/web_workers/} Example: Web workers
 * @group System
 *
 * Deno supports the node:worker_threads module for moving work off the main
 * thread. A worker receives startup data through workerData and talks to
 * the main thread through parentPort. This example launches itself as a
 * worker to stay self-contained; normally the worker is its own module. The
 * web standard Worker API is the Deno-native alternative.
 */
import {
  isMainThread,
  parentPort,
  Worker,
  workerData,
} from "node:worker_threads";
import process from "node:process";

// isMainThread distinguishes the two roles this one file plays.
if (isMainThread) {
  // The main thread starts the worker. The workerData option carries any
  // structured value to the worker as startup input.
  const worker = new Worker(new URL(import.meta.url), {
    workerData: { numbers: [3, 4, 5] },
  });

  // Replies from the worker arrive on the message event as structured
  // values, no parsing needed. Once the result is in, the main thread asks
  // the worker to stop.
  worker.on("message", (message) => {
    console.log("from worker:", JSON.stringify(message)); // from worker: {"sum":12}
    worker.postMessage("stop");
  });

  // The exit event fires when the worker thread has shut down.
  worker.on("exit", (code) => {
    console.log(`worker exited with code ${code}`); // worker exited with code 0
  });
} else {
  // This branch runs inside the worker thread. The startup input is
  // available as workerData, and parentPort sends results back.
  const total = workerData.numbers.reduce((a: number, b: number) => a + b, 0);
  parentPort!.postMessage({ sum: total });

  // The worker stays alive while it listens on parentPort. Exiting the
  // process inside a worker ends just that thread.
  parentPort!.on("message", (message) => {
    if (message === "stop") {
      process.exit(0);
    }
  });
}

/**
 * @title Write to stdout
 * @difficulty beginner
 * @tags cli
 * @run <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.stdout} Doc: Deno.stdout
 * @resource {https://docs.deno.com/examples/reading_stdin/} Example: Read from stdin
 * @group System
 *
 * console.log is fine for debugging, but command line tools often need
 * precise control over standard output: no forced newline, raw bytes, or
 * piping a whole stream. This example shows each approach.
 */

// Deno.stdout accepts raw bytes. Unlike console.log, nothing is appended,
// so the two writes below land on the same line.
const encoder = new TextEncoder();
await Deno.stdout.write(encoder.encode("Hello, "));
await Deno.stdout.write(encoder.encode("World!\n")); // Hello, World!

// A single low-level write call may write fewer bytes than given. The web
// standard writer on Deno.stdout guarantees the whole chunk is written.
// Release the lock afterwards so other code can use stdout again.
const writer = Deno.stdout.writable.getWriter();
await writer.write(encoder.encode("All bytes written\n"));
writer.releaseLock();

// There is a synchronous variant of the low-level write as well.
Deno.stdout.writeSync(encoder.encode("Sync write\n"));

// A readable stream can be piped to stdout directly. Prevent the pipe from
// closing stdout if the program continues.
const stream = ReadableStream.from(["Streamed to stdout\n"])
  .pipeThrough(new TextEncoderStream());
await stream.pipeTo(Deno.stdout.writable, { preventClose: true });

// Code written for Node.js uses process.stdout, which works in Deno too
// and accepts strings directly.
import process from "node:process";
process.stdout.write("Via process.stdout\n");

// Errors and diagnostics belong on stderr instead, so they do not corrupt
// output that is being piped to another program.
await Deno.stderr.write(encoder.encode("A diagnostic message\n"));

/**
 * @title Writing files
 * @difficulty beginner
 * @tags cli
 * @run -R -W <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.writeFile} Doc: Deno.writeFile
 * @resource {https://docs.deno.com/api/deno/~/Deno.create} Doc: Deno.create
 * @resource {https://docs.deno.com/api/deno/~/Deno.FsFile} Doc: Deno.FsFile
 * @resource {https://developer.mozilla.org/en-US/docs/Web/API/TextEncoder} MDN: TextEncoder
 * @group File System
 *
 * Many applications need to write files to disk. Deno provides a simple
 * interface for writing files.
 */

// The easiest way to write a file, is to dump an entire buffer into the file at
// once. Here is a simple example that writes an array of bytes to a file.
const bytes = new Uint8Array([72, 101, 108, 108, 111]);
await Deno.writeFile("hello.txt", bytes, { mode: 0o644 });

// You can also write a string instead of a byte array.
await Deno.writeTextFile("hello.txt", "Hello World");

// To append to a text file, set the `append` parameter to `true`.
await Deno.writeTextFile("server.log", "Request: ...", { append: true });

// Synchronous writing is also supported.
Deno.writeFileSync("hello.txt", bytes);
Deno.writeTextFileSync("hello.txt", "Hello World");

// For more granular writes, open a new file for writing.
const file = await Deno.create("hello.txt");

// You can write chunks of data to the file.
const written = await file.write(bytes);
console.log(`${written} bytes written.`);

// A `file.write` returns the number of bytes written, as it might not write all
// bytes passed. We can get a Writer instead to make sure the entire buffer is written.
const writer = file.writable.getWriter();
await writer.write(new TextEncoder().encode("World!"));

// Closing the writer automatically closes the file.
// If you don't use a writer, make sure to close the file after you are done with it.
await writer.close();

// The `-W` permission is required to write files.

/**
 * @title Writing tests
 * @difficulty beginner
 * @tags cli
 * @run deno test -R -W <url>
 * @resource {https://docs.deno.com/api/deno/~/Deno.test} Doc: Deno.test
 * @resource {https://jsr.io/@std/assert/doc} Doc: @std/assert
 * @group CLI
 *
 * One of the most common tasks in developing software is writing tests for
 * existing code. Deno has a built-in test runner which makes this very easy.
 */

// First, we import assert statements from the standard library. There are
// quite a few options but we will just import the most common ones here.
import { assert, assertEquals } from "jsr:@std/assert";

// The most simple way to use the test runner is to just pass it a description
// and a callback function
Deno.test("assert works correctly", () => {
  assert(true);
  assertEquals(1, 1);
});

// In more complex scenarios, we often need to have some setup and teardown code
// with some steps in between. This is also made simple with the built-in test runner.
Deno.test("testing steps", async (t) => {
  const file = await Deno.open("example.txt", {
    read: true,
    write: true,
    create: true,
  });
  const encoder = new TextEncoder();
  const data = encoder.encode("Hello world!");

  await t.step("write some bytes", async () => {
    const bytesWritten = await file.write(data);
    assertEquals(bytesWritten, data.length);
    await file.seek(0, Deno.SeekMode.Start);
  });

  await t.step("read some bytes", async () => {
    const buffer = new Uint8Array(data.length);
    await file.read(buffer);
    assertEquals(buffer, data);
  });

  file.close();
});

// The test runner by default makes it very hard to shoot yourself in the foot. For
// each test, the test runner checks to make sure all resources created during the
// test are freed. There are situations where this is not useful behavior. We can use
// the more complex test definition to disable this behavior
Deno.test({
  name: "leaky test",
  async fn() {
    await Deno.open("example.txt");
  },
  sanitizeResources: false,
});

/**
 * @title Compress data with node:zlib
 * @difficulty beginner
 * @tags cli, deploy
 * @run <url>
 * @resource {https://docs.deno.com/api/node/zlib/} Doc: node:zlib
 * @resource {/examples/compress_decompress/} Example: Compress and decompress data
 * @group Encoding
 *
 * The node:zlib module is built into Deno and offers more codecs and
 * options than the web standard streams, including brotli and synchronous
 * one-shot helpers. For simple gzip and deflate streaming, the web
 * standard CompressionStream in /examples/compress_decompress/ needs no
 * imports at all.
 */
import {
  brotliCompressSync,
  brotliDecompressSync,
  gunzipSync,
  gzip,
  gzipSync,
} from "node:zlib";
import { promisify } from "node:util";

// We compress some repetitive data, which compresses well.
const input = new TextEncoder().encode("Hello Deno! ".repeat(100));

// To compress a buffer in one call, use gzipSync. The result is a Buffer,
// which is a Uint8Array subclass.
const gzipped = gzipSync(input);
console.log(input.length, "->", gzipped.length); // 1200 -> 47

// To decompress, use gunzipSync. The round trip restores the exact bytes.
const restored = gunzipSync(gzipped);
console.log(new TextDecoder().decode(restored).slice(0, 11)); // Hello Deno!
console.log(restored.length === input.length); // true

// The sync functions block the event loop while they run. In a server,
// promisify the callback variant and await it instead.
const gzipAsync = promisify(gzip);
const gzipped2 = await gzipAsync(input);
console.log(gzipped2.length); // 47

// node:zlib also implements brotli, which CompressionStream does not
// offer. Brotli usually compresses text harder than gzip.
const brotli = brotliCompressSync(input);
console.log(brotli.length); // 30
console.log(brotliDecompressSync(brotli).length); // 1200

